    # and its mtime map (no live file yet).
    imm.ELECTION_EXTRA_SERIES.clear()
    imm._election_extra_state["mtime"] = 0.0
    imm.ELECTION_DATES_EXTRA[:] = []
    imm.AWARDS_DATES_EXTRA[:] = []
    imm._rows_extra_state.clear()
    # ...and the awards by Kalshi tag (awards_extra_series.json, 2026-10-12),
    # the same way: its path follows STATUS_DIR, so only memory is reset
    imm.AWARDS_EXTRA_SERIES.clear()
    imm._awards_extra_state["mtime"] = 0.0
    # ...and the graduate families by Kalshi metadata (graduate_auto_series.json)
    imm.GRADUATE_AUTO_SERIES.clear()
    imm._graduate_auto_state["mtime"] = 0.0
    # ...and the single-event mentions by Kalshi category (mention_auto_series.json)
    imm.MENTION_AUTO_SERIES.clear()
    imm._mention_auto_state["mtime"] = 0.0
    # the data center count file (2026-10-01) is reloaded by every run_cycle
    imm.DC_FAIR_FILE = os.path.join(tmp, "datacenter_fair.json")
    imm._dc_state.update(mtime=0.0, entries={})
    # the OpenRouter market-share fair file (2026-09-30) is reloaded by every
    # run_cycle (missed in the first cut: a full-suite run left the share
    # gate's fixture in the live run-logs/incentive-mm -- see
    # TestNoLivePathUnderTest)
    imm.SHARE_FAIR_FILE = os.path.join(tmp, "openrouter_share_fair.json")
    imm._share_fair_state.update(mtime=0.0, entries={}, moved_at={})
    # the monthly rain fair file (2026-10-01), same reason
    imm.RAIN_MONTHLY_FILE = os.path.join(tmp, "rain_monthly_fair.json")
    imm._rain_monthly_state.update(mtime=0.0, markets={}, events={})
    # ...and the monthly snow one (2026-10-04)
    imm.SNOW_MONTHLY_FILE = os.path.join(tmp, "snow_monthly_fair.json")
    imm._snow_monthly_state.update(mtime=0.0, markets={}, events={})
    # the 2026-10-11 fair-file gates (CPI pilot, weekend rain)
    imm.CPI_FAIR_FILE = os.path.join(tmp, "cpi_fair.json")
    imm._cpi_fair_state.update(mtime=0.0, markets={}, events={})
    imm.RAIN_WKND_FILE = os.path.join(tmp, "rain_wknd_fair.json")
