class TestEventStartResolver(unittest.TestCase):
    MLB_JSON = {"dates": [{"games": [{
        "gameDate": "2026-07-12T22:40:00Z",
        "teams": {"away": {"team": {"abbreviation": "MIL"}},
                  "home": {"team": {"abbreviation": "PIT"}}}}]}]}
    ESPN_JSON = {"events": [{
        "date": "2026-07-11T16:00Z",
        "competitions": [{"competitors": [
            {"team": {"abbreviation": "ARG"}}, {"team": {"abbreviation": "SUI"}}]}]}]}

    def test_mlb_resolves_game_time(self):
        r = imm.EventStartResolver(http_get_json=lambda url: self.MLB_JSON)
        start = r.resolve("KXMLBMENTION", "KXMLBMENTION-26JUL12MILPIT")
        self.assertEqual(start, utc(2026, 7, 12, 22, 40))

    def test_wc_resolves_kickoff(self):
        r = imm.EventStartResolver(http_get_json=lambda url: self.ESPN_JSON)
        start = r.resolve("KXWCMENTION", "KXWCMENTION-26JUL11ARGSUI")
        self.assertEqual(start, utc(2026, 7, 11, 16, 0))

    def test_fixed_hour_series(self):
        r = imm.EventStartResolver(http_get_json=lambda url: {})
        start = r.resolve("KXLOVEISLMENTION", "KXLOVEISLMENTION-26JUL10")
        et = start.astimezone(imm.ET)
        self.assertEqual((et.hour, et.minute, et.day), (21, 0, 10))

    def test_latenight_fixed_hour(self):
        r = imm.EventStartResolver(http_get_json=lambda url: {})
        start = r.resolve("KXLATENIGHTMENTION", "KXLATENIGHTMENTION-26JUL19")
        et = start.astimezone(imm.ET)
        self.assertEqual((et.hour, et.minute, et.day), (22, 0, 19))

    WNBA_JSON = {"events": [{
        "date": "2026-07-19T17:00Z",
        "competitions": [{"competitors": [
            {"team": {"abbreviation": "DAL"}}, {"team": {"abbreviation": "LA"}}]}]}]}

    NFL_JSON = {"events": [{
        "date": "2026-09-25T00:15Z", "shortName": "ATL @ GB",
        "status": {"type": {"name": "STATUS_SCHEDULED"}},
        "competitions": [{"competitors": [
            {"team": {"abbreviation": "GB", "location": "Green Bay"},
             "homeAway": "home"},
            {"team": {"abbreviation": "ATL", "location": "Atlanta"},
             "homeAway": "away"}]}]}]}

    def test_sports_ladder_resolves_kickoff_from_espn(self):
        # Jack 2026-09-24: "allowlist sports ladders and escalators, up until
        # the game starts ... these shouldnt be quoted since the game
        # started". Kalshi's occurrence_datetime on these is kickoff + ~3h,
        # so the resolver's kickoff is what keeps the bot out of the game.
        urls = []

        def get(url):
            urls.append(url)
            return self.NFL_JSON
        r = imm.EventStartResolver(http_get_json=get)
        for ev in ("KXNFLLADDERREC-26SEP24ATLGB",
                   "KXNFLESCALATORRECYDS-26SEP24ATLGB",
                   "KXNFLFFPTSLADDER-26SEP24ATLGB"):
            self.assertEqual(r.resolve(ev.split("-")[0], ev),
                             utc(2026, 9, 25, 0, 15), ev)
        self.assertIn("site.web.api.espn.com/apis/site/v2/sports/football/nfl/"
                      "scoreboard?dates=20260924", urls[0])
        # either team order in the blob
        self.assertEqual(r.resolve("KXNFLLADDERREC", "KXNFLLADDERREC-26SEP24GBATL"),
                         utc(2026, 9, 25, 0, 15))
        # no matching game -> None -> the midnight-ET fallback upstream
        self.assertIsNone(r.resolve("KXNFLLADDERREC", "KXNFLLADDERREC-26SEP24KCLAC"))
        # a league without an ESPN path resolves nothing (fallback = quote less)
        with mock.patch.dict(imm.ESPN_LEAGUE_PATHS, {}, clear=True):
            r2 = imm.EventStartResolver(http_get_json=get)
            self.assertIsNone(r2.resolve("KXNFLLADDERREC",
                                         "KXNFLLADDERREC-26SEP25ATLGB"))
        # and the fallback itself is the night BEFORE the game, never the
        # occurrence three hours into it
        self.assertEqual(imm.trade_cutoff_utc("KXNFLLADDERREC-26SEP24ATLGB",
                                              utc(2026, 9, 25, 3, 15),
                                              utc(2026, 9, 25, 6, 15)),
                         utc(2026, 9, 24, 4, 0))

    def test_wnba_resolves_tip_either_order(self):
        # Ticker blob LADAL = away+home; ESPN lists home (DAL) first — the
        # variable-length codes can't be split, so both concat orders match.
        r = imm.EventStartResolver(http_get_json=lambda url: self.WNBA_JSON)
        start = r.resolve("KXWNBAMENTION", "KXWNBAMENTION-26JUL19LADAL")
        self.assertEqual(start, utc(2026, 7, 19, 17, 0))

    def test_wnba_no_game_match_returns_none(self):
        r = imm.EventStartResolver(http_get_json=lambda url: self.WNBA_JSON)
        self.assertIsNone(r.resolve("KXWNBAMENTION", "KXWNBAMENTION-26JUL19NYIND"))

    def test_wnba_kalshi_code_longer_than_espn(self):
        # Kalshi CONN vs ESPN CON (live miss 2026-07-19): prefix match must
        # recover the game.
        j = {"events": [{
            "date": "2026-07-19T23:00Z",
            "competitions": [{"competitors": [
                {"team": {"abbreviation": "PHX", "location": "Phoenix"}},
                {"team": {"abbreviation": "CON", "location": "Connecticut"}}]}]}]}
        r = imm.EventStartResolver(http_get_json=lambda url: j)
        start = r.resolve("KXWNBAMENTION", "KXWNBAMENTION-26JUL19CONNPHX")
        self.assertEqual(start, utc(2026, 7, 19, 23, 0))

    def test_wnba_location_prefix_match(self):
        # Kalshi WAS vs ESPN WSH: neither is a prefix of the other, but the
        # location (WASHINGTON) rescues it.
        j = {"events": [{
            "date": "2026-07-20T00:00Z",
            "competitions": [{"competitors": [
                {"team": {"abbreviation": "WSH", "location": "Washington"}},
                {"team": {"abbreviation": "LV", "location": "Las Vegas"}}]}]}]}
        r = imm.EventStartResolver(http_get_json=lambda url: j)
        start = r.resolve("KXWNBAMENTION", "KXWNBAMENTION-26JUL19WASLV")
        self.assertEqual(start, utc(2026, 7, 20, 0, 0))

    NYDAL_POSTPONED = {"events": [
        {"date": "2026-07-17T01:00Z",
         "status": {"type": {"name": "STATUS_POSTPONED"}},
         "competitions": [{"competitors": [
             {"team": {"abbreviation": "DAL"}}, {"team": {"abbreviation": "NY"}}]}]},
        {"date": "2026-07-21T00:00Z",
         "status": {"type": {"name": "STATUS_SCHEDULED"}},
         "competitions": [{"competitors": [
             {"team": {"abbreviation": "DAL"}}, {"team": {"abbreviation": "NY"}}]}]}]}

    def test_wnba_postponed_uses_makeup_start(self):
        # NYDAL 7/16: original postponed, makeup 7/20 8pm ET — the cutoff must
        # come from the makeup, not the (past) original.
        r = imm.EventStartResolver(http_get_json=lambda url: self.NYDAL_POSTPONED)
        start = r.resolve("KXWNBAMENTION", "KXWNBAMENTION-26JUL16NYDAL")
        self.assertEqual(start, utc(2026, 7, 21, 0, 0))

    def test_wnba_postponed_unscheduled_returns_none(self):
        j = {"events": [self.NYDAL_POSTPONED["events"][0]]}
        r = imm.EventStartResolver(http_get_json=lambda url: j)
        self.assertIsNone(r.resolve("KXWNBAMENTION", "KXWNBAMENTION-26JUL16NYDAL"))

    def test_wnba_final_game_not_resurrected_by_next_meeting(self):
        # A FINISHED game must keep anchoring its past start even when the
        # same pair meets again inside the 14-day range window.
        j = {"events": [
            {"date": "2026-07-17T01:00Z",
             "status": {"type": {"name": "STATUS_FINAL"}},
             "competitions": [{"competitors": [
                 {"team": {"abbreviation": "DAL"}}, {"team": {"abbreviation": "NY"}}]}]},
            self.NYDAL_POSTPONED["events"][1]]}
        r = imm.EventStartResolver(http_get_json=lambda url: j)
        start = r.resolve("KXWNBAMENTION", "KXWNBAMENTION-26JUL16NYDAL")
        self.assertEqual(start, utc(2026, 7, 17, 1, 0))

    def test_api_failure_returns_none_and_caches(self):
        calls = {"n": 0}

        def boom(url):
            calls["n"] += 1
            raise RuntimeError("down")
        r = imm.EventStartResolver(http_get_json=boom)
        self.assertIsNone(r.resolve("KXMLBMENTION", "KXMLBMENTION-26JUL12MILPIT"))
        self.assertIsNone(r.resolve("KXMLBMENTION", "KXMLBMENTION-26JUL12MILPIT"))
        self.assertEqual(calls["n"], 1)   # negative-cached

    def test_no_game_match_returns_none(self):
        r = imm.EventStartResolver(http_get_json=lambda url: {"dates": [{"games": []}]})
        self.assertIsNone(r.resolve("KXMLBMENTION", "KXMLBMENTION-26JUL12MILPIT"))

    def test_unresolvable_series(self):
        r = imm.EventStartResolver(http_get_json=lambda url: {})
        self.assertIsNone(r.resolve("KXBTCMAXY", "KXBTCMAXY-26"))

    def test_override_change_is_live_not_cached(self):
        # A hot-reloaded override CHANGE must take effect immediately, not sit
        # behind the resolver's 6h cache (live bug 2026-07-23: INTC 5pm->4pm
        # ignored while the bot kept quoting past the new cutoff).
        ev = "KXEARNINGSMENTIONZZZ-26JUL23"
        r = imm.EventStartResolver(http_get_json=lambda url: {})
        t1 = imm.parse_iso_utc("2026-07-23T17:00:00-04:00")
        t2 = imm.parse_iso_utc("2026-07-23T16:00:00-04:00")
        imm.EVENT_START_OVERRIDES[ev] = t1
        try:
            self.assertEqual(r.resolve("KXEARNINGSMENTIONZZZ", ev), t1)
            imm.EVENT_START_OVERRIDES[ev] = t2          # changed mid-run
            self.assertEqual(r.resolve("KXEARNINGSMENTIONZZZ", ev), t2)
        finally:
            imm.EVENT_START_OVERRIDES.pop(ev, None)


class TestPlaceWithCaps(unittest.TestCase):
    def setUp(self):
        self.bot = IncentiveMarketMaker(client=None, live=False)
        self.now = time.time()

    def test_places_fresh(self):
        placed = self.bot.place_with_caps(
            [Quote("T", "bid", 49, 5), Quote("T", "bid", 48, 10)], [], set(), self.now)
        self.assertEqual(placed, 2)
        self.assertEqual(len(self.bot.state.sim_orders), 2)

    def test_side_cap_blocks(self):
        resting = [_resting("a", "T", "bid", 49, imm.SIDE_MAX_CONTRACTS)]
        placed = self.bot.place_with_caps([Quote("T", "bid", 48, 5)], resting,
                                          set(), self.now)
        self.assertEqual(placed, 0)

    def test_side_cap_rounds_the_lean_as_the_quote_loop_does(self):
        # Jack 2026-10-30 ("Yes"): KXRIRESPOWER-27FEB28-T29.0's evening rung
        # of 45 on a 1.5 bid lean is 67.5 -> 68 in the quote loop, x3 at a
        # deep reference = 204; the cap read 45 x 3 x 1.5 = 202.5 and refused
        # it every cycle from 6 PM ET (679 side_cap alerts)
        with mock.patch.object(imm, "LADDER_MODE", "atref"), \
                mock.patch.object(imm, "REF_DEPTH_MAX_MULT", 3.0), \
                mock.patch.dict(imm.SIDE_MULT_SERIES, {"KXCAPT": (1.5, 0.75)}), \
                mock.patch.object(imm, "hour_scaled_levels", lambda s, now: [(0, 45)]):
            self.assertEqual(self.bot.place_with_caps(
                [Quote("KXCAPT-27FEB28-T29", "bid", 80, 204)], [], set(), self.now), 1)
            # ...the cap still binds just past it
            self.assertEqual(self.bot.place_with_caps(
                [Quote("KXCAPT-27FEB28-T30", "bid", 80, 205)], [], set(), self.now), 0)
            # ...and a lean under 1 leaves the side at the plain ladder's 135
            self.assertEqual(self.bot.place_with_caps(
                [Quote("KXCAPT-27FEB28-T31", "ask", 90, 135)], [], set(), self.now), 1)
            self.assertEqual(self.bot.place_with_caps(
                [Quote("KXCAPT-27FEB28-T32", "ask", 90, 136)], [], set(), self.now), 0)

    def test_side_cap_ignores_cancelled(self):
        resting = [_resting("a", "T", "bid", 49, imm.SIDE_MAX_CONTRACTS)]
        placed = self.bot.place_with_caps([Quote("T", "bid", 48, 5)], resting,
                                          {"a"}, self.now)
        self.assertEqual(placed, 1)

    def test_level_cap_blocks(self):
        biggest = max(s for _t, s in imm.LEVELS)
        resting = [_resting("a", "T", "bid", 49, biggest)]
        placed = self.bot.place_with_caps([Quote("T", "bid", 49, 5)], resting,
                                          set(), self.now)
        self.assertEqual(placed, 0)

    def test_cycle_cap(self):
        quotes = [Quote(f"T{i}", "bid", 40, 1)
                  for i in range(imm.MAX_PLACEMENTS_PER_CYCLE + 10)]
        placed = self.bot.place_with_caps(quotes, [], set(), self.now)
        self.assertEqual(placed, imm.MAX_PLACEMENTS_PER_CYCLE)


# ----------------------------------------------------------------------------
# Fake-client integration (dry-run cycles against a canned exchange)
# ----------------------------------------------------------------------------

class FakeClient:
    """Just enough of ExchangeClient for dry-run cycles."""

    def __init__(self):
        now = datetime.now(timezone.utc)
        start = (now - timedelta(days=1)).strftime("%Y-%m-%dT%H:%M:%SZ")
        end = (now + timedelta(days=6)).strftime("%Y-%m-%dT%H:%M:%SZ")
        far = (now + timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")
        self.programs = [
            {"market_ticker": "KXGOOD-99DEC31-A", "incentive_type": "liquidity",
             "period_reward": 7000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": start, "end_date": end},
            {"market_ticker": "KXWIDE-99DEC31-B", "incentive_type": "liquidity",
             "period_reward": 7000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": start, "end_date": end},
            {"market_ticker": "KXHIGHNY-26JUL10-B90", "incentive_type": "liquidity",
             "period_reward": 9000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": start, "end_date": end},
        ]
        self.markets = {
            "KXGOOD-99DEC31-A": {
                "ticker": "KXGOOD-99DEC31-A", "event_ticker": "KXGOOD-99DEC31",
                "status": "active", "close_time": far,
                "yes_bid_dollars": "0.4900", "yes_ask_dollars": "0.5100",
                "volume_fp": "500.00"},
            "KXWIDE-99DEC31-B": {
                "ticker": "KXWIDE-99DEC31-B", "event_ticker": "KXWIDE-99DEC31",
                "status": "active", "close_time": far,
                "yes_bid_dollars": "0.1000", "yes_ask_dollars": "0.9000",
                "volume_fp": "500.00"},
        }
        self.books = {
            "KXGOOD-99DEC31-A": {"orderbook_fp": {
                "yes_dollars": [["0.48", "500"], ["0.49", "600"]],
                "no_dollars": [["0.49", "1200"]]}},   # ext ask = 51
        }
        self.positions = {}
        # open-scan tier reads (2026-09-05): GET /series/<s> and the hourly
        # candlesticks. Absent entries RAISE, like a failed live read.
        self.series_meta = {}
        self.candles = {}

    def get(self, path, params=None):
        if path == "/incentive_programs":
            return {"incentive_programs": self.programs, "next_cursor": None}
        if path.startswith("/series/") and path.endswith("/candlesticks"):
            ticker = path.split("/markets/")[1].rsplit("/", 1)[0]
            self.candle_reads = getattr(self, "candle_reads", 0) + 1
            c = self.candles.get(ticker)
            if c is None:
                raise RuntimeError(f"no candles for {ticker}")
            return {"candlesticks": c}
        if path.startswith("/series/"):
            series = path.split("/")[2]
            self.series_reads = getattr(self, "series_reads", 0) + 1
            meta = self.series_meta.get(series)
            if meta is None:
                raise RuntimeError(f"no series meta for {series}")
            return {"series": meta}
        raise AssertionError(f"unexpected GET {path}")

    def get_markets(self, **kw):
        wanted = (kw.get("tickers") or "").split(",")
        return {"markets": [self.markets[t] for t in wanted if t in self.markets]}

    def get_orderbook(self, ticker, depth=None):
        if ticker not in self.books:
            raise RuntimeError("no book")
        return self.books[ticker]

    def get_positions(self, **kw):
        mp = [{"ticker": t, "position": p} for t, p in self.positions.items()]
        return {"market_positions": mp, "cursor": None}

    def get_fills(self, **kw):
        self.fills_reads = getattr(self, "fills_reads", 0) + 1
        return {"fills": list(getattr(self, "fills", [])), "cursor": None}

    def get_orders(self, **kw):
        return {"orders": [], "cursor": None}

    def get_order(self, order_id):
        return {"order": dict(getattr(self, "order_lookup", {}).get(order_id) or {})}

    def get_market(self, ticker):
        return {"market": dict(self.markets.get(ticker) or {})}

    def create_order(self, **kw):
        self.created = getattr(self, "created", [])
        self.created.append(kw)
        return {"order": {"order_id": f"real-{len(self.created)}"}}

    def cancel_order(self, order_id, exchange_index=None, market_ticker=None):
        self.cancelled = getattr(self, "cancelled", [])
        self.cancelled.append(order_id)
        # (order id, exchange_index, market_ticker) per call: the shard routing
        self.cancel_calls = getattr(self, "cancel_calls", [])
        self.cancel_calls.append((order_id, exchange_index, market_ticker))
        return {}


class TestToxicSideHalt(unittest.TestCase):
    """Jack 2026-09-29: "i need a mechanism to halt a side/market when there
    is toxic flow / adverse selection in the form of repeatedly getting
    picked off going in one direction". A maker fill is a pick-off when the
    mark TOXIC_CONFIRM_SECS later is TOXIC_PICKOFF_CENTS+ against it;
    TOXIC_PICKOFFS of them on one side inside TOXIC_WINDOW_SECS halt that
    side for TOXIC_HALT_SECS."""

    def setUp(self):
        _clean_persist()
        self.bot = IncentiveMarketMaker(client=None, live=False)
        self.now = 1_800_000_000.0
        self.t = "KXGOOD-99DEC31-A"

    def _due(self, side, px, ago=400.0):
        self.bot.state.toxic_pending.append([self.t, side, px, self.now - ago])

    def test_fills_queue_by_the_side_that_was_hit_pads_and_takers_never(self):
        b = self.bot
        for i, (side, action, want) in enumerate((
                ("yes", "buy", "bid"), ("no", "sell", "bid"),
                ("yes", "sell", "ask"), ("no", "buy", "ask"))):
            b._toxic_note_fill({"order_id": f"o{i}", "ts": 1000 + i},
                               self.t, side, action, 50.0)
            self.assertEqual(b.state.toxic_pending[-1],
                             [self.t, want, 50.0, float(1000 + i)])
        n = len(b.state.toxic_pending)
        b._toxic_note_fill({"order_id": "tk", "ts": 1, "is_taker": True},
                           self.t, "yes", "buy", 50.0)          # rain take
        b.state.ledger["pad"] = {"book_side": "bid",
                                 "yes_price": imm.PAD_BID_CENTS}
        b._toxic_note_fill({"order_id": "pad", "ts": 1}, self.t, "yes", "buy",
                           float(imm.PAD_BID_CENTS))           # a 1c pad
        self.assertEqual(len(b.state.toxic_pending), n)

    def test_second_pick_off_on_a_side_halts_that_side_only(self):
        b = self.bot
        b.state.last_mark[self.t] = 44.0                  # 6c under both buys
        self._due("bid", 50.0)
        self.assertEqual(b._toxic_confirm(self.now, {self.t}), [])
        self.assertEqual(len(b.state.toxic_picks[f"{self.t}|bid"]), 1)
        self._due("bid", 50.0)
        self.assertEqual(b._toxic_confirm(self.now, {self.t}), [f"{self.t}|bid"])
        self.assertEqual(b.state.toxic_halt_until[f"{self.t}|bid"],
                         self.now + imm.TOXIC_HALT_SECS)
        self.assertTrue(b.toxic_side_halted(self.t, "bid", self.now + 60))
        self.assertFalse(b.toxic_side_halted(self.t, "ask", self.now + 60))
        self.assertFalse(b.toxic_side_halted(
            self.t, "bid", self.now + imm.TOXIC_HALT_SECS + 1))
        self.assertEqual(b.state.toxic_pending, [])
        # asks mirror it: sold at 50, the mark 6c higher
        b.state.last_mark[self.t] = 56.0
        self._due("ask", 50.0)
        self._due("ask", 50.0)
        self.assertEqual(b._toxic_confirm(self.now, {self.t}), [f"{self.t}|ask"])

    def test_small_or_favourable_moves_are_not_pick_offs(self):
        b = self.bot
        for mark in (46.0, 50.0, 60.0):                   # 4c against, flat, in favour
            b.state.last_mark[self.t] = mark
            self._due("bid", 50.0)
            self._due("bid", 50.0)
            self.assertEqual(b._toxic_confirm(self.now, {self.t}), [])
        self.assertEqual(b.state.toxic_picks.get(f"{self.t}|bid", []), [])

    def test_checks_wait_for_their_time_and_a_fresh_mark(self):
        b = self.bot
        b.state.last_mark[self.t] = 40.0
        self._due("bid", 50.0, ago=100)                   # not due yet
        self.assertEqual(b._toxic_confirm(self.now, {self.t}), [])
        self.assertEqual(len(b.state.toxic_pending), 1)
        b.state.toxic_pending = []
        self._due("bid", 50.0)                            # due, mark not fresh
        b._toxic_confirm(self.now, set())
        self.assertEqual(len(b.state.toxic_pending), 1)
        b.state.toxic_pending = []
        self._due("bid", 50.0, ago=imm.TOXIC_CONFIRM_SECS
                  + imm.TOXIC_MAX_LATE_SECS + 10)          # too late: dropped
        b._toxic_confirm(self.now, {self.t})
        self.assertEqual(b.state.toxic_pending, [])
        self.assertEqual(b.state.toxic_picks.get(f"{self.t}|bid", []), [])

    def test_pick_offs_outside_the_window_do_not_add_up(self):
        b = self.bot
        b.state.last_mark[self.t] = 40.0
        b.state.toxic_picks[f"{self.t}|bid"] = [self.now - imm.TOXIC_WINDOW_SECS - 60]
        self._due("bid", 50.0)
        self.assertEqual(b._toxic_confirm(self.now, {self.t}), [])
        self.assertEqual(b.state.toxic_picks[f"{self.t}|bid"], [self.now])

    def test_kill_switch(self):
        b = self.bot
        b.state.toxic_halt_until[f"{self.t}|bid"] = self.now + 600
        with mock.patch.object(imm, "TOXIC_HALT", False):
            self.assertFalse(b.toxic_side_halted(self.t, "bid", self.now))
            b._toxic_note_fill({"order_id": "x", "ts": 1}, self.t, "yes", "buy", 50.0)
            self.assertEqual(b.state.toxic_pending, [])

    # ---- event-wide (Jack 2026-09-29: "yes add event-wide halting too") ----

    def _sink_rows(self):
        path = os.path.join(imm.STATUS_DIR, "toxic_halts_"
                            + datetime.now(timezone.utc).strftime("%Y-%m-%d")
                            + ".jsonl")
        if not os.path.exists(path):
            return []
        with open(path, encoding="utf-8") as fh:
            return [json.loads(l) for l in fh]

    def test_pick_offs_on_two_markets_halt_the_whole_event(self):
        b = self.bot
        ev = "KXGOOD-99DEC31"
        a, c, other = f"{ev}-A", f"{ev}-B", "KXOTHER-99DEC31-A"
        b.state.last_mark.update({a: 40.0, c: 60.0})
        before = len(self._sink_rows())
        # one pick-off on A's bid, one on B's ask, 20 minutes apart
        b.state.toxic_pending = [[a, "bid", 50.0, self.now - 1600]]
        self.assertEqual(b._toxic_confirm(self.now - 1200, {a, c}), [])
        b.state.toxic_pending = [[c, "ask", 50.0, self.now - 400]]
        self.assertEqual(b._toxic_confirm(self.now, {a, c}), [ev])
        for t in (a, c, f"{ev}-C"):                 # every market of the event
            self.assertTrue(b.toxic_market_halted(t, self.now + 60), t)
        self.assertFalse(b.toxic_market_halted(other, self.now + 60))
        self.assertFalse(b.toxic_event_halted(ev, self.now + imm.TOXIC_EVENT_HALT_SECS + 1))
        # one pick-off per side is no SIDE halt
        self.assertEqual(b.state.toxic_halt_until, {})
        rows = self._sink_rows()[before:]
        self.assertEqual([r["kind"] for r in rows], ["pickoff", "pickoff", "event_halt"])
        self.assertEqual(rows[-1]["markets_picked"], [a, c])
        self.assertEqual(rows[-1]["until"], round(self.now + imm.TOXIC_EVENT_HALT_SECS, 1))

    def test_same_market_twice_is_a_side_halt_not_an_event_halt(self):
        b = self.bot
        b.state.last_mark[self.t] = 40.0
        self._due("bid", 50.0)
        self._due("bid", 50.0)
        self.assertEqual(b._toxic_confirm(self.now, {self.t}), [f"{self.t}|bid"])
        self.assertFalse(b.toxic_event_halted("KXGOOD-99DEC31", self.now + 60))
        self.assertTrue(b.toxic_market_halted(self.t, self.now + 60))

    def test_event_pick_offs_outside_the_window_or_rule_off_do_not_halt(self):
        b = self.bot
        ev = "KXGOOD-99DEC31"
        a, c = f"{ev}-A", f"{ev}-B"
        b.state.last_mark.update({a: 40.0, c: 40.0})
        b.state.toxic_event_picks[ev] = [[self.now - imm.TOXIC_EVENT_WINDOW_SECS - 60, a]]
        b.state.toxic_pending = [[c, "bid", 50.0, self.now - 400]]
        self.assertEqual(b._toxic_confirm(self.now, {a, c}), [])
        with mock.patch.object(imm, "TOXIC_EVENT_MARKETS", 0):
            b.state.toxic_pending = [[a, "bid", 50.0, self.now - 400]]
            self.assertEqual(b._toxic_confirm(self.now, {a, c}), [])
        self.assertFalse(b.toxic_event_halted(ev, self.now))

    def test_mention_series_are_exempt(self):
        """Jack 2026-10-09: "turn off toxic halts on MENTION markets" -- a
        mention pick-off is still written to the sink (flagged exempt) but
        counts toward no side or event halt, and a halt already in saved
        state no longer stands anything down."""
        b = self.bot
        ev = "KXTRUMPMENTION-26OCT09"
        a, c = f"{ev}-ISRA", f"{ev}-TRUMA"
        b.state.last_mark.update({a: 40.0, c: 60.0, self.t: 40.0})
        before = len(self._sink_rows())
        # two bid pick-offs on ISRA + one ask on TRUMA: a side AND an event
        # halt anywhere else
        b.state.toxic_pending = [[a, "bid", 50.0, self.now - 400],
                                 [a, "bid", 50.0, self.now - 350],
                                 [c, "ask", 50.0, self.now - 400]]
        self.assertEqual(b._toxic_confirm(self.now, {a, c}), [])
        self.assertEqual((b.state.toxic_halt_until, b.state.toxic_event_halt_until,
                          b.state.toxic_picks, b.state.toxic_event_picks,
                          b.state.toxic_pending), ({}, {}, {}, {}, []))
        rows = self._sink_rows()[before:]
        self.assertEqual([(r["kind"], r["ticker"], r["exempt"]) for r in rows],
                         [("pickoff", a, True), ("pickoff", a, True),
                          ("pickoff", c, True)])
        # the same pick-offs on a non-mention market still halt it
        self._due("bid", 50.0)
        self._due("bid", 50.0)
        self.assertEqual(b._toxic_confirm(self.now, {self.t}), [f"{self.t}|bid"])
        self.assertFalse(self._sink_rows()[-2]["exempt"])
        # halts saved before the change are ignored, restored with the knob
        b.state.toxic_halt_until[f"{a}|bid"] = self.now + 600
        b.state.toxic_event_halt_until[ev] = self.now + 600
        self.assertFalse(b.toxic_market_halted(a, self.now))
        self.assertFalse(b.toxic_market_halted(c, self.now))
        with mock.patch.object(imm, "TOXIC_EXEMPT_WORDS", ()):
            self.assertTrue(b.toxic_side_halted(a, "bid", self.now))
            self.assertTrue(b.toxic_event_halted(ev, self.now))
        self.assertTrue(imm.toxic_exempt("KXEARNINGSMENTIONDPZ"))
        self.assertTrue(imm.toxic_exempt("KXWORLDNEWSMENTION"))
        self.assertFalse(imm.toxic_exempt("KXAAAGASD"))

    def test_halts_and_near_misses_survive_a_restart(self):
        b = self.bot
        now = time.time()
        b.state.toxic_halt_until = {f"{self.t}|bid": now + 900,
                                    f"{self.t}|ask": now - 5}       # expired
        b.state.toxic_picks = {f"{self.t}|ask": [now - 60],
                               "OLD|bid": [now - imm.TOXIC_WINDOW_SECS - 60]}
        b.state.toxic_pending = [[self.t, "bid", 50.0, now - 30],
                                 ["STALE", "bid", 50.0, now - 99999]]
        b.state.toxic_event_halt_until = {"KXGOOD-99DEC31": now + 900,
                                          "KXGONE-99DEC31": now - 5}
        b.state.toxic_event_picks = {
            "KXGOOD-99DEC30": [[now - 60, "KXGOOD-99DEC30-A"]],
            "KXGONE-99DEC30": [[now - imm.TOXIC_EVENT_WINDOW_SECS - 60, "X"]]}
        b._save_persist()
        b2 = IncentiveMarketMaker(client=None, live=False)
        self.assertEqual(set(b2.state.toxic_halt_until), {f"{self.t}|bid"})
        self.assertEqual(set(b2.state.toxic_picks), {f"{self.t}|ask"})
        self.assertEqual([p[0] for p in b2.state.toxic_pending], [self.t])
        self.assertTrue(b2.toxic_side_halted(self.t, "bid", now))
        self.assertEqual(set(b2.state.toxic_event_halt_until), {"KXGOOD-99DEC31"})
        self.assertEqual(set(b2.state.toxic_event_picks), {"KXGOOD-99DEC30"})
        self.assertTrue(b2.toxic_event_halted("KXGOOD-99DEC31", now))


class TestDryRunCycle(unittest.TestCase):
    def _bot(self):
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        return bot

    def test_a_wide_managed_book_marks_at_the_last_trade_inside_its_touch(self):
        # Jack 2026-10-01 ("Yes, at 50c+"): a quoted market whose EXTERNAL
        # book goes 10/90 marks the held position at the last trade (30)
        # clamped inside 10/90 -- through _refresh_marks, since the order
        # book carries no last trade -- while prev_mid (the breakers) stays
        # on the 50 mid. The bulk read's own 49/51 touch must not be used.
        bot = self._bot()
        t = "KXGOOD-99DEC31-A"
        bot.run_cycle()
        self.assertEqual(bot.state.last_mark[t], 50.0)
        bot.pnl.pos[t], bot.pnl.avg[t] = 20.0, 40.0
        bot.client.positions[t] = 20.0
        bot.client.markets[t]["last_price_dollars"] = "0.3000"
        bot.client.books[t] = {"orderbook_fp": {
            "yes_dollars": [["0.10", "500"]], "no_dollars": [["0.10", "500"]]}}
        bot.run_cycle()
        self.assertEqual(bot.state.prev_mid[t], 50.0)
        self.assertEqual(bot.state.last_mark[t], 30.0)
        with mock.patch.object(imm, "MARK_WIDE_SPREAD_CENTS", 0):
            bot.run_cycle()
        self.assertEqual(bot.state.last_mark[t], 50.0)

    def test_toxic_side_halt_cancels_only_the_picked_off_side(self):
        # end to end: two bid fills at 50c, the book then 43/45 (mark 44,
        # 6c against each) -> the next cycle judges them, halts the BID side
        # and the diff cancels every resting bid; asks keep quoting; when
        # the halt runs out the bids come back
        bot = self._bot()
        t = "KXGOOD-99DEC31-A"
        bot.run_cycle()
        self.assertEqual({o["book_side"] for o in bot.state.sim_orders.values()},
                         {"bid", "ask"})
        now = time.time()
        bot.state.toxic_pending = [[t, "bid", 50.0, now - 400],
                                   [t, "bid", 50.0, now - 350]]
        bot.client.books[t] = {"orderbook_fp": {
            "yes_dollars": [["0.42", "500"], ["0.43", "600"]],
            "no_dollars": [["0.55", "1200"]]}}
        bot.run_cycle()
        self.assertTrue(bot.toxic_side_halted(t, "bid", time.time()))
        self.assertEqual({o["book_side"] for o in bot.state.sim_orders.values()},
                         {"ask"})
        bot.state.toxic_halt_until[f"{t}|bid"] = time.time() - 1
        bot.run_cycle()
        self.assertIn("bid", {o["book_side"] for o in bot.state.sim_orders.values()})

    def test_toxic_event_halt_cancels_every_market_of_the_event(self):
        # end to end: a second market in the same event; pick-offs on both
        # (A's bid, B's ask) -> the next cycle halts the EVENT and the diff
        # cancels every order on both markets, both sides; an unrelated
        # event keeps quoting; when the halt runs out both come back
        bot = self._bot()
        c = bot.client
        a, b2 = "KXGOOD-99DEC31-A", "KXGOOD-99DEC31-B"
        c.programs.append(dict(c.programs[0], market_ticker=b2))
        c.markets[b2] = dict(c.markets[a], ticker=b2)
        c.books[b2] = c.books[a]
        bot.run_cycle()
        tick = {o["ticker"] for o in bot.state.sim_orders.values()}
        self.assertTrue({a, b2} <= tick)
        now = time.time()
        # marks the cycle will read: A's book moves down, B's up
        c.books[a] = {"orderbook_fp": {"yes_dollars": [["0.42", "500"], ["0.43", "600"]],
                                       "no_dollars": [["0.55", "1200"]]}}   # mid 44
        c.books[b2] = {"orderbook_fp": {"yes_dollars": [["0.54", "500"], ["0.55", "600"]],
                                        "no_dollars": [["0.43", "1200"]]}}  # mid 56
        bot.state.toxic_pending = [[a, "bid", 50.0, now - 400],
                                   [b2, "ask", 50.0, now - 350]]
        bot.run_cycle()
        self.assertTrue(bot.toxic_event_halted("KXGOOD-99DEC31", time.time()))
        self.assertEqual({o["ticker"] for o in bot.state.sim_orders.values()} & {a, b2}, set())
        bot.state.toxic_event_halt_until["KXGOOD-99DEC31"] = time.time() - 1
        bot.run_cycle()
        self.assertTrue({a, b2} <= {o["ticker"] for o in bot.state.sim_orders.values()})

    def test_a_cut_market_never_burns_a_lifetime_event_slot(self):
        """Jack 2026-09-09: "fix the lifetime slot ordering too". The ledger
        was written straight after event_top_n_cut, but THREE more filters run
        after that point — finecon_group_cut, scan_group_cut and the
        MAX_MARKETS/collateral loop. A market taken by any of them had already
        recorded a PERMANENT slot on its event without ever being quoted.
        Measured live 2026-09-09 17:17Z: 3 such slots on events with live
        programs (KXDIESELYE-26DEC31 held 2 of its 3, KXAAAGASDVA-26SEP10 1).

        Driven here through the MAX_MARKETS filter, which is the last of the
        three and sits furthest from the old write point."""
        _clean_persist()
        c = FakeClient()
        now = datetime.now(timezone.utc)
        start = (now - timedelta(days=1)).strftime("%Y-%m-%dT%H:%M:%SZ")
        end = (now + timedelta(days=6)).strftime("%Y-%m-%dT%H:%M:%SZ")
        far = (now + timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")
        evs = ["KXGOOD-99DEC31", "KXGOOD-99DEC30"]
        c.programs, c.markets, c.books = [], {}, {}
        for ev in evs:
            t = f"{ev}-A"
            c.programs.append(
                {"market_ticker": t, "incentive_type": "liquidity",
                 "period_reward": 7000000, "target_size_fp": "1000.00",
                 "discount_factor_bps": 5000, "paid_out": False,
                 "start_date": start, "end_date": end})
            c.markets[t] = {
                "ticker": t, "event_ticker": ev, "status": "active",
                "close_time": far, "yes_bid_dollars": "0.4900",
                "yes_ask_dollars": "0.5100", "volume_fp": "500.00"}
            c.books[t] = {"orderbook_fp": {
                "yes_dollars": [["0.48", "500"], ["0.49", "600"]],
                "no_dollars": [["0.49", "1200"]]}}

        bot = IncentiveMarketMaker(client=c, live=False)
        # KXGOOD is not a capped family by default; make it one so the
        # lifetime ledger applies, and let only ONE event through.
        with mock.patch.object(imm, "EVENT_TOP_N", [("KXGOOD", 3)]),                 mock.patch.object(imm, "EVENT_TOP_N_LIFETIME", True),                 mock.patch.object(imm, "MAX_MARKETS", 1):
            bot.run_cycle()

        chosen = {m.event_ticker for m in bot.state.selected.values()}
        self.assertEqual(len(chosen), 1, "the MAX_MARKETS filter did not bite")
        cut_ev = [e for e in evs if e not in chosen][0]
        sel_ev = chosen.pop()

        # the SELECTED event spent its slot
        self.assertEqual(
            (bot.state.event_slots.get(sel_ev) or {}).get("markets"),
            [f"{sel_ev}-A"])
        # THE REGRESSION: the CUT event must have spent nothing...
        self.assertEqual(
            (bot.state.event_slots.get(cut_ev) or {}).get("markets") or [], [],
            f"{cut_ev} burned a lifetime slot on a market it never quoted")
        # ...while still holding a live ledger entry, so the 14-day persist
        # TTL cannot age it out and hand the event a fresh lifetime budget.
        self.assertIn(cut_ev, bot.state.event_slots)
        self.assertGreater((bot.state.event_slots[cut_ev] or {}).get("ts", 0), 0)

    def test_fast_tick_touches_nothing_without_fast_series(self):
        # Fast-lane mini-cycle (Jack 2026-08-02) on a universe with no
        # fast-lane series: every order the full cycle placed must survive
        # untouched (preserved through the diff, NOT cancelled as unmatched),
        # and the shared accrual stamp / cycle counter must not move (fast
        # ticks defer accrual so other markets' integrals aren't robbed).
        bot = self._bot()
        bot.run_cycle()
        self.assertTrue(bot.state.sim_orders)
        before = dict(bot.state.sim_orders)
        stamp = bot.state.reward_accrue_at
        cycles = bot.state.cycles_today
        bot.run_cycle(fast_only=True)
        self.assertEqual(bot.state.sim_orders, before)
        self.assertEqual(bot.state.reward_accrue_at, stamp)
        self.assertEqual(bot.state.cycles_today, cycles)

