    def test_rainstorm_span_quotes_until_the_start_date(self):
        # "up until the start date": out at 00:00 ET on the window's first
        # day (the ticker's second segment), pinned by the KXRAINSBOS
        # archetype and inherited by every other city through the pattern
        # parent. Kalshi's occurrence equals expiration, so it never wins.
        ev = "KXRAINSBOS-26SEP26-27SEP26"
        occ = exp = utc(2026, 9, 28, 5, 0)
        close = utc(2026, 9, 28, 4, 59)
        stop = utc(2026, 9, 26, 4, 0)                   # 00:00 EDT Sep 26
        self.assertEqual(imm.parse_event_date(ev), stop)
        raw = imm.trade_cutoff_utc(ev, occ, exp)
        self.assertEqual(raw, stop)
        self.assertEqual(imm.apply_series_cutoff_adjustments(
            "KXRAINSBOS", ev, raw, close_time=close), stop)
        # the orphan-restore producer (no occurrence/close) lands the same
        self.assertEqual(imm.apply_series_cutoff_adjustments(
            "KXRAINSBOS", ev, imm.trade_cutoff_utc(ev, None, None)), stop)
        ov = imm.series_override("KXRAINSBOS")
        self.assertEqual(ov.cutoff_before_event_min, 0)
        self.assertEqual((imm.series_price_min("KXRAINSBOS"),
                          imm.series_price_max("KXRAINSBOS")), (5, 90))
        self.assertIsNone(ov.cutoff_from_close_min)
        self.assertIsNone(ov.levels)
        self.assertFalse(ov.safe_join)
        # a new city clones the archetype at first sight in the candidates
        # loop, and lands the same cutoff
        imm.SERIES_OVERRIDES.pop("KXRAINSNYC", None)
        try:
            imm.ensure_family_override("KXRAINSNYC")
            self.assertEqual(
                imm.series_override("KXRAINSNYC").cutoff_before_event_min, 0)
            self.assertEqual(imm.apply_series_cutoff_adjustments(
                "KXRAINSNYC", "KXRAINSNYC-26SEP26-27SEP26",
                imm.trade_cutoff_utc("KXRAINSNYC-26SEP26-27SEP26", occ, exp),
                close_time=close), stop)
        finally:
            imm.SERIES_OVERRIDES.pop("KXRAINSNYC", None)
        # a member quotes to the instant; fresh entry stops the buffer early
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        meta = imm.MarketMeta(
            ticker="KXRAINSBOS-26SEP26-27SEP26-T1", event_ticker=ev,
            series="KXRAINSBOS", dollars_per_day=16.57, program_end=exp,
            target_size=1000.0, discount_factor=0.5, cutoff=stop,
            close_time=close, mid_cents=50.0, spread_cents=2,
            volume=50.0, status="active")
        self.assertIsNone(bot._screen(meta, stop - timedelta(minutes=2),
                                      member=True))
        self.assertEqual(bot._screen(meta, stop - timedelta(minutes=2)),
                         "cutoff")
        self.assertEqual(bot._screen(meta, stop, member=True), "cutoff")

    def test_rain_weekend_quotes_to_ticker_date_midnight(self):
        # Jack 2026-09-10: "allowlist KXRAINWKND ... but only quote until the
        # cutoff e.g. KXRAINWKND-26SEP12 stops quoting on 9/12". The ticker
        # date is the weekend's FIRST day and the cutoff is 00:00 ET that
        # day (the plain ticker rule) — NOT the dailies' 10pm-the-night-
        # before, and nothing Kalshi stamps on the market may push it later.
        ov = imm.series_override("KXRAINWKND")
        self.assertEqual(ov.cutoff_before_event_min, 0)
        # x1 again (Jack 2026-10-09: "undouble weekend rain"); daily stays x2
        self.assertEqual(imm.applied_mention_mult("KXRAINWKND"), 1.0)
        self.assertEqual(imm.applied_mention_mult("KXRAIN"), 2.0)
        self.assertEqual((imm.series_price_min("KXRAINWKND"),
                          imm.series_price_max("KXRAINWKND")), (5, 90))
        self.assertIsNone(ov.cutoff_from_close_min)
        self.assertIsNone(ov.levels)
        # live 9/10 market shape: listed Thu, closes Mon 05:00Z; Kalshi's
        # occurrence sits AFTER expiration, so it can never win the min()
        close, exp, occ = (utc(2026, 9, 14, 5), utc(2026, 9, 15, 3, 59),
                           utc(2026, 9, 15, 5))
        midnight_sat = utc(2026, 9, 12, 4)              # 00:00 EDT Sep 12
        raw = imm.trade_cutoff_utc("KXRAINWKND-26SEP12", occ, exp)
        self.assertEqual(raw, midnight_sat)
        cut = imm.apply_series_cutoff_adjustments(
            "KXRAINWKND", "KXRAINWKND-26SEP12", raw, close_time=close)
        self.assertEqual(cut, midnight_sat)
        # the orphan-restore producer (no occurrence/close) lands the same
        self.assertEqual(imm.apply_series_cutoff_adjustments(
            "KXRAINWKND", "KXRAINWKND-26SEP12",
            imm.trade_cutoff_utc("KXRAINWKND-26SEP12", None, None)),
            midnight_sat)
        # a member quotes to the instant; fresh entry stops the buffer early
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        meta = imm.MarketMeta(
            ticker="KXRAINWKND-26SEP12-NYC",
            event_ticker="KXRAINWKND-26SEP12", series="KXRAINWKND",
            dollars_per_day=29.0, program_end=close, target_size=1000,
            discount_factor=0.5, cutoff=cut, close_time=close,
            mid_cents=50.0, spread_cents=4)
        self.assertNotEqual(bot._screen(
            meta, midnight_sat - timedelta(minutes=1), member=True), "cutoff")
        self.assertEqual(bot._screen(meta, midnight_sat, member=True), "cutoff")
        self.assertEqual(bot._screen(
            meta, midnight_sat - timedelta(minutes=4)), "cutoff")
        # family rules by PREFIX read across: the KXRAIN 7pm ET halving
        self.assertEqual(imm.hour_size_mult(
            "KXRAINWKND", utc(2026, 9, 11, 23, 30)), 0.5)   # 7:30pm EDT
        self.assertEqual(imm.hour_size_mult(
            "KXRAINWKND", utc(2026, 9, 11, 16, 0)), 1.0)    # noon EDT
        # exact-match daily-rain machinery does NOT read across
        self.assertFalse(imm.curated_event(
            "KXRAINWKND-26SEP12", "KXRAINWKND", utc(2026, 9, 11, 16)))
        self.assertIsNone(imm.rain_fair_p("KXRAINWKND-26SEP12-NYC",
                                          time.time()))

    def test_curated_tier_and_econ_runoff(self):
        # 2026-07-29 pm: (a) the rolling next-day rain event is CURATED —
        # floor/hopeless bypass rolls with the gate exemption (JUL30-NYC
        # was hopeless-evicted when only the gate rolled); (b) econ series
        # join the no-new run-off (SCFI-26EOY grandfathered).
        now = utc(2026, 7, 29, 18, 0)      # 2pm ET Jul 29 -> next day is JUL30
        self.assertTrue(imm.curated_event("KXRAIN-26JUL30", "KXRAIN", now))
        self.assertFalse(imm.curated_event("KXRAIN-26JUL31", "KXRAIN", now))
        self.assertFalse(imm.curated_event("KXOTHER-26JUL30", "KXOTHER", now))
        # 2026-08-03 (Jack, TRUMPMENTION AUG03 "same rules as other
        # markets"): an event-start override supplies the CUTOFF only — it
        # no longer curates past the floors/hopeless.
        imm.EVENT_START_OVERRIDES["KXFOO-26AUG01"] = now
        try:
            self.assertFalse(imm.curated_event("KXFOO-26AUG01", "KXFOO", now))
        finally:
            imm.EVENT_START_OVERRIDES.pop("KXFOO-26AUG01", None)
        # 2026-08-02 (Jack) RE-ENTRY: company/econ freeze + no-new lifted;
        # they quote again behind the $2/day rate floor + safe-join rule.
        for s in ("KXSCFI", "KXNHSALES", "KXBA", "KXHOOD", "KXAAAGASD",
                  "KXUSGASCPI"):
            self.assertNotIn(s, imm.NO_NEW_SERIES)
            self.assertNotIn(s, imm.FREEZE_SERIES)
            self.assertEqual(imm.series_min_est_rate(s), 2.0)
            self.assertTrue(imm.series_safe_join(s))
        self.assertEqual(imm.series_min_est_rate("KXGOOD"), 0.0)
        self.assertFalse(imm.series_safe_join("KXTEMPDCH"))
        # 2026-08-02 (Jack): KXRT pulled out of the econ set — entertainment
        # reveals are not macro prints; the 7/29 econ run-off had swept it
        # by config placement. Still allowed, no longer no_new'd.
        self.assertNotIn("KXRT", imm.NO_NEW_SERIES)
        self.assertTrue(imm.IncentiveMarketMaker._allowed("KXRT-X"))

