class TestLoveIslandCycle(unittest.TestCase):
    def _client(self, n_markets=4, mid_bid="0.48", mid_ask="0.49",
                no_bid="0.49", yes_depth="1200", no_depth="1200"):
        _clean_persist()
        client = FakeClient()
        client.programs = []
        client.markets = {}
        client.books = {}
        # TODAY's episode (dynamic — a hardcoded date breaks the moment that
        # ET day ends: the pre-filter drops date-expired tickers). Past ~8pm
        # ET, today's 9pm cutoff is imminent, so use tomorrow's episode.
        now = datetime.now(timezone.utc)
        et_now = now.astimezone(imm.ET)
        day = et_now if et_now.hour < 20 else et_now + timedelta(days=1)
        seg = day.strftime("%y%b%d").upper()
        ev = f"KXLOVEISLMENTION-{seg}"
        start = (now - timedelta(hours=1)).strftime("%Y-%m-%dT%H:%M:%SZ")
        end = (now + timedelta(hours=15)).strftime("%Y-%m-%dT%H:%M:%SZ")
        far = "2099-01-01T00:00:00Z"
        for i in range(n_markets):
            t = f"{ev}-M{i}"
            client.programs.append({
                "market_ticker": t, "incentive_type": "liquidity",
                "period_reward": 3000000, "target_size_fp": "1000.00",
                "discount_factor_bps": 5000, "paid_out": False,
                "start_date": start, "end_date": end})
            client.markets[t] = {
                "ticker": t, "event_ticker": ev, "status": "active",
                "close_time": far, "open_time": start,
                "yes_bid_dollars": "0.48", "yes_ask_dollars": "0.50",
                "volume_fp": "500.00"}
            client.books[t] = {"orderbook_fp": {
                "yes_dollars": [[mid_bid, yes_depth]],
                "no_dollars": [[no_bid, no_depth]]}}
        return client, ev

    def _use_resolver(self, bot):
        # Fixed 9pm ET start via SERIES_START_ET; Love Island buffer=0 -> cutoff
        # 9:00pm ET. Real resolver (no HTTP needed for the fixed-hour path).
        bot.resolver = imm.EventStartResolver(http_get_json=lambda url: {})

    def test_quotes_all_markets_555(self):
        client, ev = self._client(n_markets=6)
        bot = IncentiveMarketMaker(client=client, live=False)
        self._use_resolver(bot)
        bot.run_cycle()
        # every market selected (quote_all), each with a 5/5/5 x2 ladder
        self.assertEqual(len(bot.state.selected), 6)
        per_market = {}
        for o in bot.state.sim_orders.values():
            per_market.setdefault(o["ticker"], []).append(o["remaining_count"])
        for t, sizes in per_market.items():
            self.assertEqual(sorted(sizes), [5, 5, 5, 5, 5, 5])   # 3 bids + 3 asks

    def test_bypasses_max_markets(self):
        client, ev = self._client(n_markets=12)
        old = imm.MAX_MARKETS
        imm.MAX_MARKETS = 3
        try:
            bot = IncentiveMarketMaker(client=client, live=False)
            self._use_resolver(bot)
            bot.run_cycle()
            self.assertEqual(len(bot.state.selected), 12)   # all, despite cap 3
        finally:
            imm.MAX_MARKETS = old

    def test_max_position_50(self):
        client, ev = self._client(n_markets=1)
        bot = IncentiveMarketMaker(client=client, live=False)
        self._use_resolver(bot)
        t = f"{ev}-M0"
        bot.pnl.pos[t] = 47          # near the 50 cap on the long side
        bot.run_cycle()
        bids = sum(o["remaining_count"] for o in bot.state.sim_orders.values()
                   if o["ticker"] == t and o["book_side"] == "bid")
        self.assertLessEqual(bids, 3)    # only 3 more before hitting 50

    def test_orders_expire_by_cutoff(self):
        client, ev = self._client(n_markets=1)
        bot = IncentiveMarketMaker(client=client, live=False)
        self._use_resolver(bot)
        bot.run_cycle()
        cutoff = imm.series_hard_expiry_utc("KXLOVEISLMENTION", ev).timestamp()
        for o in bot.state.sim_orders.values():
            self.assertLessEqual(o["expire_at"], cutoff + 0.001)

    def test_effective_cutoff_is_9pm_no_buffer(self):
        """The selected meta's cutoff (what actually stops quoting) is 9:00pm ET
        — the 30-min pre-broadcast buffer is zeroed for Love Island."""
        client, ev = self._client(n_markets=1)
        bot = IncentiveMarketMaker(client=client, live=False)
        self._use_resolver(bot)
        bot.run_cycle()
        meta = bot.state.selected[f"{ev}-M0"]
        et = meta.cutoff.astimezone(imm.ET)
        self.assertEqual((et.hour, et.minute), (21, 0))

    def test_user_position_does_not_yield_loveisl(self):
        """The user holding a manual Love Island position must NOT stop the bot
        — it quotes the whole event anyway (unlike non-quote_all series)."""
        client, ev = self._client(n_markets=3)
        bot = IncentiveMarketMaker(client=client, live=False)
        self._use_resolver(bot)
        client.positions[f"{ev}-M0"] = 80    # big manual position, not bot's book
        bot.run_cycle()
        self.assertEqual(len(bot.state.selected), 3)   # all still quoted
        self.assertEqual(bot.manual_events(client.positions), set())

    def test_user_order_yields_only_that_market(self):
        """A live foreign order on ONE Love Island market yields just that
        market; the rest of the event keeps quoting."""
        _clean_persist()
        client, ev = self._client(n_markets=3)
        blocked = f"{ev}-M1"
        base_get = client.get_orders

        def get_orders(**kw):
            return {"orders": [
                {"order_id": "jack1", "ticker": blocked, "status": "resting",
                 "client_order_id": "", "book_side": "bid", "yes_price": 40,
                 "remaining_count": 100}], "cursor": None}
        client.get_orders = get_orders
        bot = IncentiveMarketMaker(client=client, live=True)
        self._use_resolver(bot)
        bot.run_cycle()
        self.assertIn(blocked, bot.state.manual_standoff)
        self.assertNotIn(blocked, bot.state.selected)
        self.assertIn(f"{ev}-M0", bot.state.selected)
        self.assertIn(f"{ev}-M2", bot.state.selected)

    # ---- depth padding (pad_to_target) ----

    def test_deep_book_no_pad(self):
        client, ev = self._client(n_markets=1)          # 1200/1200 both sides
        bot = IncentiveMarketMaker(client=client, live=False)
        self._use_resolver(bot)
        bot.run_cycle()
        pads = [o for o in bot.state.sim_orders.values()
                if o["yes_price"] in (imm.PAD_BID_CENTS, imm.PAD_ASK_CENTS)]
        self.assertEqual(pads, [])

    def test_thin_bid_side_padded_at_1c(self):
        # Padding is hourly-TEMP-only since 2026-08-05; this test's
        # SUBJECT is the pad machinery, so enable it explicitly rather
        # than relying on a default that no longer holds.
        _pad = imm.PAD_TO_TARGET_GLOBAL
        imm.PAD_TO_TARGET_GLOBAL = True
        self.addCleanup(setattr, imm, 'PAD_TO_TARGET_GLOBAL', _pad)
        client, ev = self._client(n_markets=1, yes_depth="300", no_depth="1200")
        bot = IncentiveMarketMaker(client=client, live=False)
        self._use_resolver(bot)
        bot.run_cycle()
        t = f"{ev}-M0"
        bid_pad = [o for o in bot.state.sim_orders.values()
                   if o["ticker"] == t and o["yes_price"] == imm.PAD_BID_CENTS]
        self.assertEqual(len(bid_pad), 1)
        # basis 300 + 15 near-touch -> pad up to 1000, rounded to 100s
        self.assertEqual(bid_pad[0]["remaining_count"], 1000)   # gap 685+300 -> 1000 (within PAD_MAX)
        # deep NO side gets no pad
        ask_pad = [o for o in bot.state.sim_orders.values()
                   if o["ticker"] == t and o["yes_price"] == imm.PAD_ASK_CENTS]
        self.assertEqual(ask_pad, [])
        # near-touch ladder still present alongside the pad
        near = [o for o in bot.state.sim_orders.values()
                if o["ticker"] == t and o["book_side"] == "bid"
                and o["yes_price"] != imm.PAD_BID_CENTS]
        self.assertEqual(sorted(o["remaining_count"] for o in near), [5, 5, 5])

    def test_both_sides_thin_padded(self):
        # Padding is hourly-TEMP-only since 2026-08-05; this test's
        # SUBJECT is the pad machinery, so enable it explicitly rather
        # than relying on a default that no longer holds.
        _pad = imm.PAD_TO_TARGET_GLOBAL
        imm.PAD_TO_TARGET_GLOBAL = True
        self.addCleanup(setattr, imm, 'PAD_TO_TARGET_GLOBAL', _pad)
        client, ev = self._client(n_markets=1, yes_depth="200", no_depth="200")
        bot = IncentiveMarketMaker(client=client, live=False)
        self._use_resolver(bot)
        bot.run_cycle()
        t = f"{ev}-M0"
        bid_pad = [o for o in bot.state.sim_orders.values()
                   if o["ticker"] == t and o["yes_price"] == imm.PAD_BID_CENTS]
        ask_pad = [o for o in bot.state.sim_orders.values()
                   if o["ticker"] == t and o["yes_price"] == imm.PAD_ASK_CENTS]
        self.assertEqual(bid_pad[0]["remaining_count"], 1000)  # (1000-215)+300 -> capped at PAD_MAX 1000
        self.assertEqual(ask_pad[0]["remaining_count"], 1000)

    def test_series_side_sizes_scale_each_side_of_the_ladder(self):
        # Jack 2026-10-22, the Trump B test ("Half bids, 1.5x asks on B"):
        # SIDE_MULT_SERIES scales the series' bid and ask rungs apart, and
        # place_with_caps lets the bigger side through
        def rungs(mults):
            client, ev = self._client(n_markets=1)
            with mock.patch.dict(imm.SIDE_MULT_SERIES, mults, clear=True):
                bot = IncentiveMarketMaker(client=client, live=False)
                self._use_resolver(bot)
                bot.run_cycle()
            t = f"{ev}-M0"
            mine = [o for o in bot.state.sim_orders.values() if o["ticker"] == t
                    and o["yes_price"] not in (imm.PAD_BID_CENTS, imm.PAD_ASK_CENTS)]
            return (sorted(o["remaining_count"] for o in mine if o["book_side"] == "bid"),
                    sorted(o["remaining_count"] for o in mine if o["book_side"] == "ask"))
        base_bids, base_asks = rungs({})
        self.assertEqual(base_bids, [5, 5, 5])
        self.assertEqual(base_asks, [5, 5, 5])
        bids, asks = rungs({"KXLOVEISLMENTION": (0.4, 2.0)})
        self.assertEqual(bids, [2, 2, 2])          # 5 x 0.4, half-up
        self.assertEqual(asks, [10, 10, 10])       # 5 x 2, past the 1x side cap
        self.assertEqual(rungs({"KXOTHER": (0.4, 2.0)}), (base_bids, base_asks))

    def test_a_side_cut_reaches_the_orders_where_the_event_share_binds(self):
        # 2026-10-27: on a wide Trump mention event the per-market share of
        # the event's room set the bids (~39 a word), so halving the ladder
        # alone left them at their old size; the cut now scales the room too
        def bids(mults):
            client, ev = self._client(n_markets=4)
            with mock.patch.dict(imm.SIDE_MULT_SERIES, mults, clear=True), \
                    mock.patch.object(imm, "event_cap_contracts", return_value=20.0):
                bot = IncentiveMarketMaker(client=client, live=False)
                self._use_resolver(bot)
                bot.run_cycle()
            return sum(o["remaining_count"] for o in bot.state.sim_orders.values()
                       if o["book_side"] == "bid"
                       and o["yes_price"] not in (imm.PAD_BID_CENTS, imm.PAD_ASK_CENTS))
        self.assertEqual(bids({}), 20)                                   # the event's room, 5 a market
        self.assertEqual(bids({"KXLOVEISLMENTION": (0.5, 1.0)}), 10)     # half of it
        self.assertEqual(bids({"KXLOVEISLMENTION": (1.0, 1.5)}), 20)     # a raise: room unscaled

    def test_pad_nets_out_own_pad_live_stable(self):
        """With our 1000 pad already resting inside the book, the desired pad
        stays 1000 (not 0) — no self-referential churn."""
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=True)
        yes_levels = [[48, 300.0], [1, 1000.0]]  # 300 external + our 1000 pad
        no_levels = [[49, 1200.0]]
        near_touch = [imm.Quote("T", "bid", 48, 5)]
        own = [("bid", imm.PAD_BID_CENTS, 700.0)]
        pads = bot._pad_quotes("T", near_touch, yes_levels, no_levels, own, 1000,
                               ext_bid=48, ext_ask=51)
        bid_pad = [p for p in pads if p.book_side == "bid"]
        self.assertEqual(len(bid_pad), 1)
        self.assertEqual(bid_pad[0].count, 700)
        self.assertTrue(bid_pad[0].is_pad)

    def test_pad_only_on_quoted_side(self):
        """No near-touch on a side (bot not quoting it) -> no pad there."""
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        pads = bot._pad_quotes("T", [imm.Quote("T", "bid", 48, 5)],
                               [[48, 100.0]], [[49, 100.0]], [], 1000,
                               ext_bid=48, ext_ask=51)
        self.assertEqual({p.book_side for p in pads}, {"bid"})   # no ask pad


class TestPadQuantity(unittest.TestCase):
    def test_rounds_up_with_slack(self):
        # gap + 300 slack, rounded up to 100 (slack survives external
        # withdrawal between requotes — the AUG0110-T82.99 lesson)
        self.assertEqual(imm.pad_quantity(315, 1000), 1000)   # gap 685+300 -> 1000 (PAD_MAX 1k)
        self.assertEqual(imm.pad_quantity(300, 1000), 1000)   # gap 700+300 -> 1000
        self.assertEqual(imm.pad_quantity(901, 1000), 400)    # gap 99 + 300
        self.assertEqual(imm.pad_quantity(900, 1000), 400)    # gap 100 + 300

    def test_at_or_over_target_no_pad(self):
        # no slack when the side already reaches target on its own
        self.assertEqual(imm.pad_quantity(1000, 1000), 0)
        self.assertEqual(imm.pad_quantity(1500, 1000), 0)

    def test_capped(self):
        self.assertEqual(imm.pad_quantity(0, 10 ** 9), imm.PAD_MAX_CONTRACTS)


class TestStickyPads(unittest.TestCase):
    """Sticky pads (Jack 2026-10-22: "Sticky pad fix"). From 10/21 another
    maker added ~600 to both sides of each KXMAMDANIMENTION word whenever our
    1c pad lifted its YES side past 1,000; the plain resize then read the pad
    as redundant and pulled it, they left, we re-padded -- a two-cycle loop.
    A resting pad now stays until the depth outside it reaches
    PAD_STICKY_RELEASE_MULT x target."""

    def setUp(self):
        _clean_persist()
        self.bot = IncentiveMarketMaker(client=FakeClient(), live=True)
        self.addCleanup(setattr, imm, "PAD_STICKY", imm.PAD_STICKY)
        imm.PAD_STICKY = True

    def _bid_pads(self, yes_levels, own, ext_bid=54):
        pads = self.bot._pad_quotes(
            "T", [imm.Quote("T", "bid", ext_bid, 57)], yes_levels,
            [[40, 3000.0]], own, 1000, ext_bid=ext_bid, ext_ask=62)
        return [p.count for p in pads if p.book_side == "bid"]

    def test_the_mamdani_loop_keeps_the_resting_pad(self):
        # 576 outside + the other maker's 600 + our 800 pad: the plain resize
        # reads 1,176 >= 1,000 and pulls the pad; sticky keeps it
        own = [("bid", imm.PAD_BID_CENTS, 800.0)]
        self.assertEqual(imm.pad_quantity(1176.0, 1000), 0)
        self.assertEqual(self._bid_pads([[54, 576.0], [50, 600.0], [1, 800.0]], own),
                         [800])

    def test_released_once_the_outside_depth_holds_twice_target(self):
        # twice the target outside, held PAD_RELEASE_HOLD_SECS (2026-10-25)
        own = [("bid", imm.PAD_BID_CENTS, 800.0)]
        t0 = 1_800_000_000.0
        with mock.patch.object(imm.time, "time", return_value=t0):
            self.assertEqual(self._bid_pads([[54, 1999.0], [1, 800.0]], own), [800])
            self.assertEqual(self._bid_pads([[54, 2000.0], [1, 800.0]], own), [800])
        with mock.patch.object(imm.time, "time", return_value=t0 + imm.PAD_RELEASE_HOLD_SECS):
            self.assertEqual(self._bid_pads([[54, 2000.0], [1, 800.0]], own), [])
        with mock.patch.object(imm, "PAD_RELEASE_HOLD_SECS", 0.0):     # the plain release
            self.assertEqual(self._bid_pads([[54, 2000.0], [1, 800.0]], own), [])

    def test_a_resting_pad_is_not_shrunk(self):
        # 602 outside wants 700 (gap 398 + 300 slack); the resting 800 stays
        own = [("bid", imm.PAD_BID_CENTS, 800.0)]
        self.assertEqual(self._bid_pads([[54, 602.0], [1, 800.0]], own), [800])

    def test_a_resting_pad_still_grows(self):
        own = [("bid", imm.PAD_BID_CENTS, 400.0)]
        self.assertEqual(self._bid_pads([[54, 300.0], [1, 400.0]], own), [1000])

    def test_no_resting_pad_sizes_as_before(self):
        self.assertEqual(self._bid_pads([[54, 1176.0]], []), [])
        self.assertEqual(self._bid_pads([[54, 576.0]], []), [800])

    def test_a_partly_filled_pad_keeps_what_is_left(self):
        own = [("bid", imm.PAD_BID_CENTS, 790.37)]
        self.assertEqual(self._bid_pads([[54, 1176.0], [1, 790.37]], own), [790])

    def test_the_distance_gate_still_pulls_it(self):
        # a 2c best bid leaves a 1c pad 1 tick behind: no pad is wanted at
        # all, so the diff cancels the resting one
        own = [("bid", imm.PAD_BID_CENTS, 800.0)]
        self.assertEqual(self._bid_pads([[2, 576.0], [1, 800.0]], own, ext_bid=2), [])

    def test_pads_hold_through_a_reflexive_maker(self):
        """Jack 2026-10-25: "Make sure Low and high temp have pads", then "Yes
        extend" -- another maker adds ~5,000 to a side whenever our pad lifts
        it to target and pulls them when ours goes; a pad is released only
        once the outside depth has held the release level for
        PAD_RELEASE_HOLD_SECS, in every family."""
        own = [("bid", imm.PAD_BID_CENTS, 900.0)]

        def pads(T, outside, now):
            with mock.patch.object(imm.time, "time", return_value=now):
                out = self.bot._pad_quotes(
                    T, [imm.Quote(T, "bid", 2, 225)], [[15, outside], [1, 900.0]],
                    [[40, 3000.0]], own, 1000, ext_bid=15, ext_ask=22)
            return [p.count for p in out if p.book_side == "bid"]
        t0 = 1_800_000_000.0
        self.assertEqual(imm.PAD_RELEASE_HOLD_SECS, 600.0)
        for T in ("KXLOWTEWR-26OCT26-T41", "KXMAMDANIMENTION-26NOV18-BILL"):
            self.assertEqual(pads(T, 5641.0, t0), [900], T)       # their 5,000 arrives: kept
            self.assertEqual(pads(T, 5641.0, t0 + 599), [900], T)
            self.assertEqual(pads(T, 436.0, t0 + 620), [900], T)  # they pulled: clock clears
            self.assertEqual(pads(T, 5641.0, t0 + 700), [900], T)  # back: the clock restarts
            self.assertEqual(pads(T, 5641.0, t0 + 1300), [], T)   # held 10 min: released

    def test_the_ask_side_mirrors(self):
        pads = self.bot._pad_quotes(
            "T", [imm.Quote("T", "ask", 62, 57)], [[54, 3000.0]],
            [[38, 1100.0], [1, 700.0]], [("ask", imm.PAD_ASK_CENTS, 700.0)],
            1000, ext_bid=54, ext_ask=62)
        self.assertEqual([p.count for p in pads if p.book_side == "ask"], [700])

    def test_knob_off_restores_the_plain_resize(self):
        imm.PAD_STICKY = False
        own = [("bid", imm.PAD_BID_CENTS, 800.0)]
        self.assertEqual(self._bid_pads([[54, 576.0], [50, 600.0], [1, 800.0]], own), [])

    def test_the_diff_leaves_a_kept_pad_resting(self):
        now = time.time()
        own = [("bid", imm.PAD_BID_CENTS, 800.0)]
        (n,) = self._bid_pads([[54, 576.0], [50, 600.0], [1, 800.0]], own)
        resting = [_resting("p", "T", "bid", imm.PAD_BID_CENTS, 800.0)]
        place, cancel, amend = diff_orders(
            [Quote("T", "bid", imm.PAD_BID_CENTS, n, is_pad=True)], resting,
            {"p": now - 60}, now)
        self.assertEqual((place, cancel, amend), ([], [], []))


class TestSeriesSideMults(unittest.TestCase):
    """Jack 2026-10-22, after the Trump mentions post-mortem: "Half bids,
    1.5x asks on B. Keep main series same." -> 2026-10-27: "do 1 and 3"
    (3: halve the main series' YES bids), then "Trump mentions B -- 1x asks
    instead of 1.5" -> 2026-10-29: "Dial down trumpmention and trumpmentionb
    by 50%"."""

    def test_both_trump_series_quarter_bids_half_asks(self):
        for s in ("KXTRUMPMENTIONB", "KXTRUMPMENTION"):
            self.assertEqual(imm.series_side_mults(s), (0.25, 0.5), s)
        now = utc(2026, 10, 28, 15, 0)
        self.assertEqual(imm.side_size_mults("KXTRUMPMENTIONB-26OCT29-SOCI", now), (0.25, 0.5))
        self.assertEqual(imm.side_size_mults("KXTRUMPMENTION-26OCT29-SOCI", now), (0.25, 0.5))
        # no other series sized by side on its own
        self.assertEqual(set(imm.SIDE_MULT_SERIES), {"KXTRUMPMENTIONB", "KXTRUMPMENTION"})

    def test_the_cut_scales_the_room_and_a_raise_does_not(self):
        # both sides now cut: bids x0.25, asks x0.5
        self.assertEqual(imm.side_cut_room("KXTRUMPMENTION", 40.0, 30.0), (10.0, 15.0))
        self.assertEqual(imm.side_cut_room("KXTRUMPMENTIONB", -8.0, 30.0), (-2.0, 15.0))
        self.assertEqual(imm.side_cut_room("KXOTHER", 40.0, 30.0), (40.0, 30.0))
        with mock.patch.dict(imm.SIDE_MULT_SERIES, {"KXA": (0.5, 1.5)}, clear=True):
            self.assertEqual(imm.side_cut_room("KXA", 40.0, 30.0), (20.0, 30.0))

    def test_spec(self):
        self.assertEqual(imm._side_mult_spec("kxa:0.5:1.5, KXB:bad:1, :1:1, KXC:0:2, KXD:1"),
                         {"KXA": (0.5, 1.5), "KXC": (0.0, 2.0)})
        self.assertEqual(imm._side_mult_spec(""), {})


class TestFamilySideLeans(unittest.TestCase):
    """Jack 2026-10-22, after the bids-vs-asks study: "Both leans now but
    1.5x the winning side and .75 the losing side" + "Also build lean for
    Econ and rates"."""

    FAMS = {"KXRT": "Rotten Tomatoes", "KXWCMENTION": "Other mentions",
            "KXUST10AD": "Econ & rates", "KXSUEZWEEKLY": "Commodities & shipping",
            "KXLUV": "Company KPIs", "KXOPENSOURCESHARE": "AI & tech",
            "KXLULUCC": "Carbon Arc consumer", "KXTRUMPMENTIONB": "TRUMP mentions",
            "KXHIGHNY": "Weather & quakes"}

    def setUp(self):
        self.real_family = imm._dashboard_family
        imm._family_cache.clear()
        self.addCleanup(imm._family_cache.clear)
        p = mock.patch.object(imm, "FAMILY_SIDE_LEANS",
                              imm._family_lean_spec(imm._DEFAULT_FAMILY_SIDE_LEANS))
        p.start()
        self.addCleanup(p.stop)
        self.calls = []

        def fam(series):
            self.calls.append(series)
            return self.FAMS.get(series, "")
        p = mock.patch.object(imm, "_dashboard_family", side_effect=fam)
        p.start()
        self.addCleanup(p.stop)

    def test_the_default_leans(self):
        self.assertEqual(imm._family_lean_spec(imm._DEFAULT_FAMILY_SIDE_LEANS), {
            "Rotten Tomatoes": (0.75, 1.5), "Other mentions": (0.75, 1.5),
            "Econ & rates": (0.75, 1.5), "Commodities & shipping": (1.5, 0.75),
            "Company KPIs": (1.5, 0.75), "AI & tech": (1.5, 0.75),
            "Carbon Arc consumer": (1.5, 0.75)})
        self.assertEqual(imm._family_lean_spec("A & B:0.5:2|bad|C:1:x| :1:1"),
                         {"A & B": (0.5, 2.0)})
        self.assertEqual(imm._family_lean_spec(""), {})
        self.assertIn("FAMILY_SIDE_LEANS", imm._CONFIG_CODE_KNOBS)

    def test_each_family_leans_its_winning_side(self):
        for s in ("KXRT", "KXWCMENTION", "KXUST10AD"):
            self.assertEqual(imm.series_side_mults(s), (0.75, 1.5), s)
        for s in ("KXSUEZWEEKLY", "KXLUV", "KXOPENSOURCESHARE", "KXLULUCC"):
            self.assertEqual(imm.series_side_mults(s), (1.5, 0.75), s)
        # no lean for the rest; Trump B keeps its own sizes (quarter bids,
        # half asks since 2026-10-29)
        self.assertEqual(imm.series_side_mults("KXHIGHNY"), (1.0, 1.0))
        self.assertEqual(imm.series_side_mults("KXTRUMPMENTIONB"), (0.25, 0.5))
        now = utc(2026, 10, 23, 15, 0)
        self.assertEqual(imm.side_size_mults("KXRT-WILD-90", now), (0.75, 1.5))
        self.assertEqual(imm.side_size_mults("KXSUEZWEEKLY-26OCT25-T40", now), (1.5, 0.75))
        with mock.patch.object(imm, "FAMILY_SIDE_LEANS", {}):
            self.assertEqual(imm.series_side_mults("KXRT"), (1.0, 1.0))

    def test_the_family_is_cached(self):
        imm.series_side_mults("KXRT")
        imm.series_side_mults("KXRT")
        self.assertEqual(self.calls, ["KXRT"])
        imm._family_cache["KXRT"] = (time.time() - imm.FAMILY_LEAN_TTL_SECS - 1, "x")
        self.assertEqual(imm.series_side_mults("KXRT"), (0.75, 1.5))
        self.assertEqual(self.calls, ["KXRT", "KXRT"])

    def test_the_real_lookup_and_its_failure(self):
        import builtins
        import sys
        real = self.real_family                     # not the setUp mock
        with mock.patch.object(imm, "_family_mod_failed", 0.0):
            self.assertEqual(real("KXWCMENTION"), "Other mentions")
            self.assertEqual(real("KXRT"), "Rotten Tomatoes")
            real_import = builtins.__import__

            def no_dash(name, *a, **k):
                if name == "imm_dashboard":
                    raise ImportError("gone")
                return real_import(name, *a, **k)
            with mock.patch.dict(sys.modules, {"imm_dashboard": None}), \
                    mock.patch.object(builtins, "__import__", side_effect=no_dash):
                self.assertEqual(real("KXRT"), "")
                self.assertGreater(imm._family_mod_failed, 0)
            # an hour's rest before the next try, even with the module back
            self.assertEqual(real("KXRT"), "")


class TestEventLongshotCut(unittest.TestCase):
    """Jack 2026-10-22: "1, and give me email report" -- in the event
    families the side that buys the cheap contract rests at 0.75x."""

    FAMS = {"KXNBAGAME": "Sports & awards", "KXSENATE": "Elections",
            "KXRAIN": "Weather & quakes", "KXRT": "Rotten Tomatoes"}

    def setUp(self):
        imm._family_cache.clear()
        self.addCleanup(imm._family_cache.clear)
        for name, val in (("LONGSHOT_MULT", 0.75), ("FAMILY_SIDE_LEANS", {})):
            p = mock.patch.object(imm, name, val)
            p.start()
            self.addCleanup(p.stop)
        p = mock.patch.object(imm, "_dashboard_family",
                              side_effect=lambda s: self.FAMS.get(s, ""))
        p.start()
        self.addCleanup(p.stop)

    def test_defaults(self):
        self.assertEqual(imm.LONGSHOT_FAMILIES, frozenset((
            "Sports & awards", "Politics & approval", "Elections", "Weather & quakes")))
        self.assertEqual((imm.LONGSHOT_BID_BELOW, imm.LONGSHOT_ASK_FROM), (30.0, 70.0))
        for k in ("LONGSHOT_MULT", "LONGSHOT_BID_BELOW", "LONGSHOT_ASK_FROM",
                  "LONGSHOT_FAMILIES"):
            self.assertIn(k, imm._CONFIG_CODE_KNOBS)

    def test_the_side_buying_the_cheap_contract_shrinks(self):
        f = imm.longshot_side_mults
        self.assertEqual(f("KXNBAGAME", 12.0), (0.75, 1.0))     # cheap YES: bids
        self.assertEqual(f("KXNBAGAME", 29.5), (0.75, 1.0))
        self.assertEqual(f("KXNBAGAME", 30.0), (1.0, 1.0))      # the middle: as is
        self.assertEqual(f("KXSENATE", 69.5), (1.0, 1.0))
        self.assertEqual(f("KXSENATE", 70.0), (1.0, 0.75))      # cheap NO: asks
        self.assertEqual(f("KXRAIN", 95.0), (1.0, 0.75))
        # not an event family, no mid, or off
        self.assertEqual(f("KXRT", 12.0), (1.0, 1.0))
        self.assertEqual(f("KXNBAGAME", None), (1.0, 1.0))
        with mock.patch.object(imm, "LONGSHOT_MULT", 1.0):
            self.assertEqual(f("KXNBAGAME", 12.0), (1.0, 1.0))

    def test_rides_side_size_mults_with_a_mid(self):
        now = utc(2026, 10, 23, 15, 0)
        self.assertEqual(imm.side_size_mults("KXNBAGAME-26OCT23LALGSW-LAL", now, 20.0),
                         (0.75, 1.0))
        self.assertEqual(imm.side_size_mults("KXNBAGAME-26OCT23LALGSW-LAL", now), (1.0, 1.0))
        self.assertEqual(imm.touch_mid(18, 22), 20.0)
        self.assertEqual(imm.touch_mid(None, 22), 22)
        self.assertIsNone(imm.touch_mid(None, None))


class TestCutoffEnforcement(unittest.TestCase):
    def _bot(self):
        _clean_persist()
        return IncentiveMarketMaker(client=FakeClient(), live=False)

    def test_cutoff_cancels_and_abandons(self):
        bot = self._bot()
        bot.run_cycle()
        t = "KXGOOD-99DEC31-A"
        self.assertTrue(bot.state.sim_orders)
        bot.state.selected[t].cutoff = datetime.now(timezone.utc) - timedelta(minutes=1)
        bot.state.universe_at = time.time()   # keep the mutated meta
        bot.run_cycle()
        self.assertEqual(bot.state.sim_orders, {})
        self.assertNotIn(t, bot.state.selected)

    def test_no_pre_cutoff_reduce_only_by_default(self):
        # Jack 2026-08-02: the pre-cutoff reduce-only window is OFF bot-wide
        # (default 0) — both sides keep quoting up to the cutoff; the
        # exchange-side expiration cap at the cutoff is the remaining guard.
        bot = self._bot()
        t = "KXGOOD-99DEC31-A"
        bot.run_cycle()
        bot.state.selected[t].cutoff = datetime.now(timezone.utc) + timedelta(minutes=30)
        bot.state.universe_at = time.time()
        bot.run_cycle()
        self.assertTrue(bot.state.sim_orders)   # still quoting inside 30min

    def test_pre_cutoff_reduce_only_env_restorable(self):
        # IMM_PRE_CUTOFF_REDUCE_ONLY > 0 restores the old behavior: inside
        # the window and flat -> nothing rests.
        bot = self._bot()
        t = "KXGOOD-99DEC31-A"
        bot.run_cycle()
        old = imm.PRE_CUTOFF_REDUCE_ONLY_SECS
        imm.PRE_CUTOFF_REDUCE_ONLY_SECS = 3600
        try:
            bot.state.selected[t].cutoff = \
                datetime.now(timezone.utc) + timedelta(minutes=30)
            bot.state.universe_at = time.time()
            bot.run_cycle()
            self.assertEqual(bot.state.sim_orders, {})
        finally:
            imm.PRE_CUTOFF_REDUCE_ONLY_SECS = old

    def test_order_expiration_capped_at_cutoff(self):
        bot = self._bot()
        t = "KXGOOD-99DEC31-A"
        cutoff = time.time() + 120   # inside the TTL
        bot.state.cutoff_ts[t] = cutoff
        bot.place_order(Quote(t, "bid", 49, 5), time.time())
        (order,) = bot.state.sim_orders.values()
        self.assertLessEqual(order["expire_at"], cutoff)

    def test_place_refused_at_cutoff(self):
        bot = self._bot()
        t = "KXGOOD-99DEC31-A"
        bot.state.cutoff_ts[t] = time.time() - 1
        self.assertFalse(bot.place_order(Quote(t, "bid", 49, 5), time.time()))
        self.assertEqual(bot.state.sim_orders, {})


class TestLossHalt(unittest.TestCase):
    def _bot(self):
        _clean_persist()
        return IncentiveMarketMaker(client=FakeClient(), live=False)

    def test_daily_loss_halts_and_cancels(self):
        bot = self._bot()
        bot.run_cycle()
        self.assertTrue(bot.state.sim_orders)
        bot.pnl.realized["X"] = -(imm.DAILY_LOSS_LIMIT + 10)
        bot.run_cycle()
        self.assertEqual(bot.state.sim_orders, {})
        self.assertGreater(bot.state.halted_until, time.time())

    def test_baseline_prevents_permanent_rehalt(self):
        """Yesterday's -$60 must not halt today once the baseline rolled."""
        bot = self._bot()
        bot.pnl.realized["X"] = -(imm.DAILY_LOSS_LIMIT + 10)
        bot.state.realized_baseline = -(imm.DAILY_LOSS_LIMIT + 10)
        bot.run_cycle()
        self.assertEqual(bot.state.halted_until, 0.0)
        self.assertTrue(bot.state.sim_orders)

    def test_banked_profit_does_not_mask_todays_loss(self):
        bot = self._bot()
        bot.pnl.realized["X"] = 200.0 - (imm.DAILY_LOSS_LIMIT + 5)
        bot.state.realized_baseline = 200.0
        bot.state.day_baseline = 200.0       # as rolled at the last summary
        bot.run_cycle()
        self.assertGreater(bot.state.halted_until, time.time())


class TestMtmAndSettlement(unittest.TestCase):
    def _bot(self):
        _clean_persist()
        return IncentiveMarketMaker(client=FakeClient(), live=False)

    def test_unrealized_math(self):
        p = imm.PnlTracker()
        p.pos["L"], p.avg["L"] = 10.0, 40.0
        p.pos["S"], p.avg["S"] = -10.0, 40.0
        marks = {"L": 50.0, "S": 30.0}
        # long +10c x 10 = +$1; short: -10 x (30-40)/100 = +$1
        self.assertAlmostEqual(p.unrealized(marks), 2.0)
        self.assertAlmostEqual(p.unrealized({}), 0.0)   # unmarked -> at cost
        self.assertAlmostEqual(p.inventory_contracts(), 20.0)

    def test_settlement_loss_booked(self):
        """Own position rides to a NO settlement: the loss must reach the
        P&L tracker even though no fill ever reports it."""
        bot = self._bot()
        t = "KXGOOD-99DEC31-A"
        bot.state.universe_at = time.time()   # nothing selected
        bot.pnl.pos[t], bot.pnl.avg[t] = 10.0, 40.0
        bot.client.markets[t]["result"] = "no"
        bot.run_cycle()                        # account flat -> settle path
        self.assertAlmostEqual(bot.pnl.realized[t], -4.0)
        self.assertAlmostEqual(bot.pnl.pos.get(t, 0.0), 0.0)

    def test_settlement_win_booked(self):
        bot = self._bot()
        t = "KXGOOD-99DEC31-A"
        bot.state.universe_at = time.time()
        bot.pnl.pos[t], bot.pnl.avg[t] = 10.0, 40.0
        bot.client.markets[t]["result"] = "yes"
        bot.run_cycle()
        self.assertAlmostEqual(bot.pnl.realized[t], 6.0)

    def test_manual_offset_dropped_without_pnl(self):
        """Account flat, market still open: user manually closed our lot —
        drop the stale entry, book nothing."""
        bot = self._bot()
        t = "KXGOOD-99DEC31-A"
        bot.state.universe_at = time.time()
        bot.pnl.pos[t], bot.pnl.avg[t] = 10.0, 40.0   # result stays ""
        bot.run_cycle()
        self.assertNotIn(t, bot.pnl.pos)
        self.assertAlmostEqual(bot.pnl.total_realized(), 0.0)

    def test_mtm_loss_trips_halt(self):
        """A gapped position that has NOT settled must still trip the halt.
        Position sized off DAILY_LOSS_LIMIT so the 40c gap always clears the
        configured limit (was hardcoded 150 lots = -$60, stale once the limit
        passed $60)."""
        bot = self._bot()
        t = "KXGOOD-99DEC31-A"
        n = float(int(imm.DAILY_LOSS_LIMIT * 4))   # 40c gap -> 1.6x the limit
        bot.state.universe_at = time.time()
        bot.client.positions[t] = n
        bot.pnl.pos[t], bot.pnl.avg[t] = n, 50.0
        bot.run_cycle()                        # mark ~50 -> baseline ~0
        self.assertEqual(bot.state.halted_until, 0.0)
        bot.client.markets[t]["yes_bid_dollars"] = "0.0900"   # gap to mid 10
        bot.client.markets[t]["yes_ask_dollars"] = "0.1100"
        bot.client.books[t] = {"orderbook_fp": {
            "yes_dollars": [["0.09", "600"]], "no_dollars": [["0.89", "1200"]]}}
        bot.run_cycle()                        # unrealized -$60 today
        self.assertGreater(bot.state.halted_until, time.time())
        self.assertEqual(bot.state.sim_orders, {})


class TestScalarVoidSettlement(unittest.TestCase):
    """2026-09-29: Kalshi settles the sports ladders / escalators (and the
    early-closed KXBKNUGGETS strikes on 9/10) as result "scalar" at a
    fractional settlement_value_dollars. _settle_or_drop knew only yes/no, so
    every one took the manual-offset branch -- 34 of 34 offset rows on
    9/6-9/29 -- and was dropped at cost with the settlement leg unbooked."""
    T = "KXGOOD-99DEC31-A"

    def _bot(self, **market):
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        bot.state.universe_at = time.time()          # nothing selected
        bot.client.markets[self.T].update(market)
        self.rows = []
        bot._sink = lambda name, rec: self.rows.append((name, dict(rec)))
        return bot

    def _settlements(self):
        return [r for n, r in self.rows if n == "settlements"]

    def test_settlement_value_parsed_exactly(self):
        f = imm.settlement_value_cents
        self.assertAlmostEqual(f({"settlement_value_dollars": "0.1200"}), 12.0)
        self.assertAlmostEqual(f({"settlement_value_dollars": "0.2160"}), 21.6)
        self.assertEqual(f({"settlement_value_dollars": "1.0000"}), 100.0)
        self.assertEqual(f({"settlement_value_dollars": "0.0000"}), 0.0)
        for bad in ({}, {"settlement_value_dollars": None},
                    {"settlement_value_dollars": ""},
                    {"settlement_value_dollars": "n/a"},
                    {"settlement_value_dollars": "1.5000"},
                    {"settlement_value_dollars": "-0.0100"}):
            self.assertIsNone(f(bad), bad)

    def test_scalar_booked_at_settlement_value(self):
        """KXNFLFFPTSLADDER-26SEP27LVNO-LVAJEANTY2: short 90 @ 16c, settled
        scalar 0.1200 -> +$3.60 realized, through the cycle's settle loop."""
        bot = self._bot(result="scalar", status="finalized",
                        settlement_value_dollars="0.1200",
                        settlement_ts="2026-09-28T00:03:26.398535Z")
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -90.0, 16.0
        bot.state.last_mark[self.T] = 82.0
        bot.run_cycle()
        self.assertAlmostEqual(bot.pnl.realized[self.T], 90 * (16 - 12) / 100.0)
        self.assertAlmostEqual(bot.pnl.pos.get(self.T, 0.0), 0.0)
        self.assertNotIn(self.T, bot.state.last_mark)
        [row] = self._settlements()
        self.assertEqual(row["result"], "scalar")
        self.assertAlmostEqual(row["settle_price_cents"], 12.0)
        self.assertEqual(row["own_pos_at_settle"], -90.0)
        self.assertEqual(row["own_avg_cents"], 16.0)
        self.assertAlmostEqual(row["market_realized_dollars"], 3.6)
        self.assertEqual(row["market_status"], "finalized")
        self.assertEqual(row["settlement_ts"], "2026-09-28T00:03:26.398535Z")
        self.assertEqual(row["via"], "settle_loop")

    def test_day_pnl_moves_from_the_mark_to_the_settlement(self):
        """The loss halt reads realized + MTM. Marked at 82c (the last trade
        on an empty book), the short 90 @ 16c that settles at 12c must move
        the day's P&L by the whole 82 -> 12 leg, +$63.00; dropping it as an
        offset at cost moved it 82 -> 16 only, +$59.40."""
        bot = self._bot(yes_bid_dollars="0.8100", yes_ask_dollars="0.8300")
        bot.client.positions[self.T] = -90.0
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -90.0, 16.0
        bot.run_cycle()                              # held, marked at 82
        self.assertAlmostEqual(bot.state.last_mark[self.T], 82.0)
        self.assertAlmostEqual(bot.state.pnl_today_last, 0.0)
        bot.client.positions.clear()
        bot.client.markets[self.T].update(
            result="scalar", status="finalized", settlement_value_dollars="0.1200",
            yes_bid_dollars="0.0000", yes_ask_dollars="1.0000")
        bot.run_cycle()
        self.assertAlmostEqual(bot.state.pnl_today_last, 90 * (82 - 12) / 100.0)
        self.assertAlmostEqual(bot.pnl.total_realized(), 3.6)

    def test_fractional_scalar_value_not_rounded(self):
        """Escalators settle in 0.0001 steps: 0.2160 is 21.6c, not 22c
        (KXNFLESCALATORRECYDS-26SEP27SEAWAS-SEAJSMITHNJIGBA11, short 36.4
        @ 18.08c)."""
        bot = self._bot(result="scalar", status="finalized",
                        settlement_value_dollars="0.2160")
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -36.4, 18.08
        bot._settle_or_drop(self.T)
        self.assertAlmostEqual(bot.pnl.realized[self.T], 36.4 * (18.08 - 21.6) / 100.0)
        self.assertAlmostEqual(self._settlements()[0]["settle_price_cents"], 21.6)

    def test_scalar_waits_for_final_status(self):
        """Result set but not finalized: the payout is not fixed yet. Keep
        the entry and retry; book once Kalshi finalizes."""
        bot = self._bot(result="scalar", status="determined",
                        settlement_value_dollars="0.1200")
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -90.0, 16.0
        bot.state.last_mark[self.T] = 14.0
        bot._settle_or_drop(self.T)
        self.assertEqual(bot.pnl.pos[self.T], -90.0)
        self.assertEqual(bot.pnl.avg[self.T], 16.0)
        self.assertEqual(bot.pnl.total_realized(), 0.0)
        self.assertEqual(bot.state.last_mark[self.T], 14.0)
        self.assertEqual(self._settlements(), [])
        bot.client.markets[self.T]["status"] = "settled"      # the older name
        bot._settle_or_drop(self.T)
        self.assertAlmostEqual(bot.pnl.realized[self.T], 3.6)
        self.assertEqual([r["result"] for r in self._settlements()], ["scalar"])

    def test_scalar_without_a_value_is_kept(self):
        bot = self._bot(result="scalar", status="finalized")
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -90.0, 16.0
        bot._settle_or_drop(self.T)
        self.assertEqual(bot.pnl.pos[self.T], -90.0)
        self.assertEqual(bot.pnl.total_realized(), 0.0)
        self.assertEqual(self._settlements(), [])

    def test_void_refunds_cost(self):
        bot = self._bot(result="void", status="finalized")
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = 25.0, 37.0
        bot._settle_or_drop(self.T)
        self.assertAlmostEqual(bot.pnl.pos.get(self.T, 0.0), 0.0)
        self.assertAlmostEqual(bot.pnl.total_realized(), 0.0)
        [row] = self._settlements()
        self.assertEqual(row["result"], "void")
        self.assertAlmostEqual(row["settle_price_cents"], 37.0)

    def test_unknown_result_is_kept_not_offset(self):
        """Kalshi decided the market with a result this code cannot value:
        not a manual offset, so the entry stays (marked, in the halt)."""
        bot = self._bot(result="mystery", status="finalized")
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -90.0, 16.0
        bot._settle_or_drop(self.T)
        self.assertEqual(bot.pnl.pos[self.T], -90.0)
        self.assertEqual(self._settlements(), [])

    def test_yes_no_rows(self):
        for result, px in (("yes", 100.0), ("no", 0.0)):
            bot = self._bot(result=result, status="finalized")
            bot.pnl.pos[self.T], bot.pnl.avg[self.T] = 10.0, 40.0
            bot.run_cycle()
            self.assertAlmostEqual(bot.pnl.realized[self.T], 10 * (px - 40) / 100.0)
            self.assertAlmostEqual(bot.pnl.pos.get(self.T, 0.0), 0.0)
            [row] = self._settlements()
            self.assertEqual(row["result"], result)
            self.assertEqual(row["settle_price_cents"], px)
            self.assertEqual(row["via"], "settle_loop")

    def test_genuine_offset_is_still_a_manual_offset(self):
        """Account flat, market NOT settled (result "", still active): the
        lot was taken out by hand -- dropped at cost, no P&L, and the row
        says manual_offset."""
        bot = self._bot()
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = 10.0, 40.0
        bot.run_cycle()
        self.assertNotIn(self.T, bot.pnl.pos)
        self.assertEqual(bot.pnl.total_realized(), 0.0)
        [row] = self._settlements()
        self.assertEqual(row["result"], "manual_offset")
        self.assertIsNone(row["settle_price_cents"])
        self.assertEqual(row["market_status"], "active")
        self.assertEqual(row["via"], "settle_loop")

    def test_market_read_failure_retries(self):
        bot = self._bot(result="scalar", status="finalized",
                        settlement_value_dollars="0.1200")
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -90.0, 16.0

        def boom(ticker):
            raise RuntimeError("503")
        bot.client.get_market = boom
        bot._settle_or_drop(self.T)
        self.assertEqual(bot.pnl.pos[self.T], -90.0)
        self.assertEqual(self._settlements(), [])


class TestRefreshMarksOneSided(unittest.TestCase):
    """2026-10-01: _refresh_marks marked a held position on a book with no
    offer at (bid + 100) / 2 -- Kalshi reads an empty ask as $1.00. The 10/1
    case: short 58.64 YES @ 91.5c on KXDDCOLDBREW-26OCT02-T4.45, last trade
    97, a stray 5c bid and no offer at the ET midnight, marked 52.5: +$26 of
    fake gain in the dashboard's 9/30 that reversed on 10/1 when the market
    settled YES."""
    T = "KXGOOD-99DEC31-A"

    def setUp(self):
        _clean_persist()
        self.bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        self.bot.pnl.pos[self.T], self.bot.pnl.avg[self.T] = -58.64, 91.5

    def _book(self, bid, ask, last=None):
        m = self.bot.client.markets[self.T]
        m.update(yes_bid_dollars=bid, yes_ask_dollars=ask)
        m.pop("last_price_dollars", None)
        if last is not None:
            m["last_price_dollars"] = last

    def test_no_offer_marks_the_last_trade(self):
        self._book("0.0500", "1.0000", "0.9700")
        self.bot._refresh_marks(set())
        self.assertEqual(self.bot.state.last_mark[self.T], 97.0)        # was 52.5

    def test_no_offer_last_trade_under_the_bid_marks_the_bid(self):
        self._book("0.3200", "1.0000", "0.2000")
        self.bot._refresh_marks(set())
        self.assertEqual(self.bot.state.last_mark[self.T], 32.0)        # was 66

    def test_no_bid_marks_the_last_trade_capped_at_the_offer(self):
        self._book("0.0000", "0.9300", "0.9700")
        self.bot._refresh_marks(set())
        self.assertEqual(self.bot.state.last_mark[self.T], 93.0)        # was 97

    def test_two_sided_marks_the_mid(self):
        self._book("0.9500", "0.9800", "0.9700")
        self.bot._refresh_marks(set())
        self.assertEqual(self.bot.state.last_mark[self.T], 96.5)

    def test_one_sided_with_no_last_trade_keeps_the_previous_mark(self):
        self.bot.state.last_mark[self.T] = 96.5
        self._book("0.0500", "1.0000")
        self.bot._refresh_marks(set())
        self.assertEqual(self.bot.state.last_mark[self.T], 96.5)
        del self.bot.state.last_mark[self.T]
        self.bot._refresh_marks(set())
        self.assertNotIn(self.T, self.bot.state.last_mark)

    def test_marked_from_its_book_this_cycle_is_left_alone(self):
        self.bot.state.last_mark[self.T] = 50.0
        self._book("0.0500", "1.0000", "0.9700")
        self.bot._refresh_marks({self.T})
        self.assertEqual(self.bot.state.last_mark[self.T], 50.0)

    def test_a_book_read_this_cycle_is_judged_on_its_external_touch(self):
        # Kalshi's 94/98 touch has our own 98c ask in it; externally there is
        # no offer, so the mark is max(last 97, bid 94) -- not the 96 mid
        self._book("0.9400", "0.9800", "0.9700")
        self.bot._refresh_marks(set(), {self.T: (94, None)})
        self.assertEqual(self.bot.state.last_mark[self.T], 97.0)
        self.bot._refresh_marks(set(), {"KXOTHER-99DEC31-Z": (94, None)})
        self.assertEqual(self.bot.state.last_mark[self.T], 96.0)

    def test_day_pnl_holds_when_the_offer_disappears(self):
        """Through the loss meter: marked 97 on a 96/98 book, then the offer
        goes and a stray 5c bid is left with the last trade still 97. The
        mark and the day's P&L must not move; the old mid moved them to 52.5
        and +$26.09."""
        bot = self.bot
        bot.state.universe_at = time.time()          # nothing selected
        bot.client.positions[self.T] = -58.64
        self._book("0.9600", "0.9800", "0.9700")
        bot.run_cycle()
        self.assertAlmostEqual(bot.state.last_mark[self.T], 97.0)
        self.assertAlmostEqual(bot.state.pnl_today_last, 0.0)
        self._book("0.0500", "1.0000", "0.9700")
        bot.run_cycle()
        self.assertAlmostEqual(bot.state.last_mark[self.T], 97.0)
        self.assertAlmostEqual(bot.state.pnl_today_last, 0.0)


class TestStartupReconcileSettles(unittest.TestCase):
    """2026-09-29: the positions that left the own book with no settlement,
    offset or realized row -- KXWORLDNEWSMENTION-26SEP09-IRAN (9/10),
    KXTRUMPENDORSEMENTS-26SEP25-A10/A20 (9/26), an NFL escalator (9/27) and
    five KXDIESELD-26SEP03 strikes (9/03) -- had all settled while the bot
    restarted. The first trusted cycle's _reconcile_orphaned_fills runs
    BEFORE the settle loop, read "account flat" as an orphaned fill and
    adopted 0, dropping the settlement with no P&L and no record."""
    T = "KXGOOD-99DEC31-A"

    def _live_bot(self, **market):
        _clean_persist()
        client = FakeClient()
        client.markets[self.T].update(market)
        bot = IncentiveMarketMaker(client=client, live=True)
        bot.state.known_tickers = {self.T}
        self.rows = []
        bot._sink = lambda name, rec: self.rows.append((name, dict(rec)))
        return bot

    def _settlements(self):
        return [r for n, r in self.rows if n == "settlements"]

    def test_market_settled_during_restart_is_booked(self):
        """KXTRUMPENDORSEMENTS-26SEP25-A10: short 40 @ 56c, settled NO at
        14:45Z, zeroed by the 14:47Z restart reconcile: +$22.40."""
        bot = self._live_bot(result="no", status="finalized",
                             settlement_value_dollars="0.0000")
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -40.0, 56.0
        bot._reconcile_orphaned_fills({})
        self.assertAlmostEqual(bot.pnl.realized[self.T], 40 * 56 / 100.0)
        self.assertAlmostEqual(bot.pnl.pos.get(self.T, 0.0), 0.0)
        [row] = self._settlements()
        self.assertEqual((row["result"], row["via"]), ("no", "startup_reconcile"))

    def test_scalar_settled_during_restart_is_booked(self):
        bot = self._live_bot(result="scalar", status="finalized",
                             settlement_value_dollars="0.2160")
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -36.4, 18.08
        bot._reconcile_orphaned_fills({})
        self.assertAlmostEqual(bot.pnl.realized[self.T], 36.4 * (18.08 - 21.6) / 100.0)
        [row] = self._settlements()
        self.assertEqual((row["result"], row["via"]), ("scalar", "startup_reconcile"))
        self.assertAlmostEqual(row["settle_price_cents"], 21.6)

    def test_unsettled_flat_account_is_a_recorded_offset(self):
        """Account flat, Kalshi has not settled: the same book effect as the
        old adopt-0 (no P&L), but no longer without a record."""
        bot = self._live_bot()
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -40.0, 56.0
        bot._reconcile_orphaned_fills({})
        self.assertNotIn(self.T, bot.pnl.pos)
        self.assertEqual(bot.pnl.total_realized(), 0.0)
        [row] = self._settlements()
        self.assertEqual((row["result"], row["via"]), ("manual_offset", "startup_reconcile"))

    def test_first_live_cycle_books_it(self):
        """Through run_cycle, where the reconcile runs on the first trusted
        cycle ahead of the settle loop (KXWORLDNEWSMENTION-26SEP09-IRAN:
        short 42.4 @ 86.69c, settled NO 20 s before the reconcile)."""
        bot = self._live_bot(result="no", status="finalized")
        bot.state.universe_at = time.time()
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -42.4, 86.69
        bot.run_cycle()
        self.assertAlmostEqual(bot.pnl.realized[self.T], 42.4 * 86.69 / 100.0)
        self.assertAlmostEqual(bot.pnl.pos.get(self.T, 0.0), 0.0)
        [row] = self._settlements()
        self.assertEqual(row["via"], "startup_reconcile")


class _FillsClient(FakeClient):
    """FakeClient whose fills read honors ticker / min_ts the way Kalshi's
    does (the base fake returns every fill on every read)."""

    def get_fills(self, **kw):
        self.fills_reads = getattr(self, "fills_reads", 0) + 1
        return {"fills": [f for f in getattr(self, "fills", [])
                          if (not kw.get("ticker") or f.get("ticker") == kw["ticker"])
                          and f.get("ts", 0) >= (kw.get("min_ts") or 0)],
                "cursor": None}


class TestReconcileOwnershipGate(unittest.TestCase):
    """2026-09-30: the startup reconcile adopted ANY divergence on a quoted
    market within the cap, at the mid. The 9/30 03:17Z restart claimed 22.36
    contracts of Jack's own 400-lot pair on KXMLBSEASONGAMES-27-2425 (placed
    by hand, no client_order_id) as the bot's: -25 @ 38 -> -47.36 @ 42.5. It
    now books only the unbooked fills on OUR orders (our_order_ids or the
    imm- client prefix), each at its own price."""
    T = "KXGOOD-99DEC31-A"

    def _live_bot(self):
        _clean_persist()
        bot = IncentiveMarketMaker(client=_FillsClient(), live=True)
        bot.state.known_tickers = {self.T}
        bot._inherited_fill_ts = int(time.time()) - 120
        bot.client.order_lookup = {}
        return bot

    def _fill(self, fid, oid, count, yes, side="yes", action="buy", age=60):
        return TestFillsPipeline._fill(fid, int(time.time()) - age, ticker=self.T,
                                       side=side, action=action, count=count,
                                       yes=yes, order_id=oid)

    def test_a_manual_fill_is_not_adopted(self):
        bot = self._live_bot()
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -25.0, 38.0
        bot.client.fills = [self._fill("jack-f1", "jack-o1", "22.36", "0.43",
                                       side="no", action="buy")]
        bot.client.order_lookup = {"jack-o1": {"client_order_id": ""}}
        bot._reconcile_orphaned_fills({self.T: -47.36})
        self.assertEqual((bot.pnl.pos[self.T], bot.pnl.avg[self.T]), (-25.0, 38.0))
        self.assertNotIn("jack-f1", bot.state.seen_fill_ids)
        self.assertNotIn("jack-o1", bot.state.our_order_ids)

    def test_orphaned_own_fill_booked_at_its_price(self):
        """An imm- order whose id the killed run never saved: booked through
        the normal fill path at 37c (not the 50c mid), claimed for later
        fills, kept out of the pick-off queue, and never booked twice."""
        bot = self._live_bot()
        bot.client.fills = [self._fill("f1", "lost-o1", "10.00", "0.37")]
        bot.client.order_lookup = {"lost-o1": {"client_order_id": "imm-dead0001-0123456789ab"}}
        with mock.patch.object(imm, "TOXIC_HALT", True):
            bot._reconcile_orphaned_fills({self.T: 10.0})
        self.assertAlmostEqual(bot.pnl.pos[self.T], 10.0)
        self.assertAlmostEqual(bot.pnl.avg[self.T], 37.0)
        self.assertIn("f1", bot.state.seen_fill_ids)
        self.assertIn("lost-o1", bot.state.our_order_ids)
        self.assertEqual(bot.state.toxic_pending, [])
        self.assertEqual(bot.fetch_new_fills(), [])

    def test_a_position_up_to_the_saturday_cap_is_ours_any_day(self):
        """SAT_MAX_POSITION (2026-10-30): a 180-lot built under Saturday's 200
        cap and found by a later restart is booked whatever the day; with the
        Saturday cap off it is past the 150 cap and left as manual."""
        for sat_cap, want in ((200.0, 180.0), (0.0, 0.0)):
            with self.subTest(sat_cap=sat_cap):
                bot = self._live_bot()
                bot.client.fills = [self._fill("f1", "lost-o1", "180.00", "0.40")]
                bot.client.order_lookup = {
                    "lost-o1": {"client_order_id": "imm-dead0001-0123456789ab"}}
                with mock.patch.multiple(imm, MAX_POSITION_CONTRACTS=150.0,
                                         SAT_MAX_POSITION=sat_cap,
                                         SAT_MAX_POSITION_FROM=datetime(2026, 10, 31).date()), \
                        mock.patch.object(imm, "applied_mention_mult", return_value=1.0):
                    bot._reconcile_orphaned_fills({self.T: 180.0})
                self.assertAlmostEqual(bot.pnl.pos.get(self.T, 0.0), want)

    def test_known_order_fill_missed_by_the_read_needs_no_lookup(self):
        bot = self._live_bot()
        bot.state.our_order_ids["ours-1"] = time.time()
        bot.client.fills = [self._fill("f2", "ours-1", "6.00", "0.41")]

        def no_lookup(order_id):
            raise AssertionError("looked up an order already in our_order_ids")
        bot.client.get_order = no_lookup
        bot._reconcile_orphaned_fills({self.T: 6.0})
        self.assertAlmostEqual(bot.pnl.pos[self.T], 6.0)
        self.assertAlmostEqual(bot.pnl.avg[self.T], 41.0)

    def test_mixed_divergence_books_only_our_part(self):
        """+5 on a lost imm- order, +10 on a manual one: book the 5, leave
        the 10 to the manual standoff."""
        bot = self._live_bot()
        bot.client.fills = [self._fill("f1", "lost-o1", "5.00", "0.40"),
                            self._fill("j1", "jack-o1", "10.00", "0.40")]
        bot.client.order_lookup = {"lost-o1": {"client_order_id": "imm-dead0001-aa"},
                                   "jack-o1": {"client_order_id": ""}}
        bot._reconcile_orphaned_fills({self.T: 15.0})
        self.assertAlmostEqual(bot.pnl.pos[self.T], 5.0)
        self.assertNotIn("j1", bot.state.seen_fill_ids)

    def test_a_booked_fill_is_not_booked_again(self):
        bot = self._live_bot()
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = 10.0, 40.0
        bot.state.seen_fill_ids["f1"] = int(time.time()) - 60
        bot.state.our_order_ids["ours-1"] = time.time()
        bot.client.fills = [self._fill("f1", "ours-1", "10.00", "0.40"),
                            self._fill("j1", "jack-o1", "10.00", "0.40")]
        bot.client.order_lookup = {"jack-o1": {"client_order_id": "cmm-fleet-1"}}
        bot._reconcile_orphaned_fills({self.T: 20.0})
        self.assertEqual((bot.pnl.pos[self.T], bot.pnl.avg[self.T]), (10.0, 40.0))

    def test_fill_older_than_the_window_is_left_alone(self):
        """The window opens an hour before the inherited fill high-water
        mark; an older divergence fails closed to the standoff."""
        bot = self._live_bot()
        bot.client.fills = [self._fill("f1", "lost-o1", "10.00", "0.37", age=4 * 3600)]
        bot.client.order_lookup = {"lost-o1": {"client_order_id": "imm-dead0001-aa"}}
        bot._reconcile_orphaned_fills({self.T: 10.0})
        self.assertEqual(bot.pnl.pos.get(self.T, 0.0), 0.0)

    def test_window_never_reaches_past_seen_fill_ids(self):
        bot = self._live_bot()
        bot._inherited_fill_ts = 1_000_000
        bot.state.seen_fill_ids = {}
        self.assertEqual(bot._reconcile_since(), 1_000_000 - 3600)
        bot.state.seen_fill_ids = {"a": 999_000, "b": 1_000_500}
        self.assertEqual(bot._reconcile_since(), 999_000)
        bot._inherited_fill_ts = 0                # no high-water mark: look nowhere
        self.assertAlmostEqual(bot._reconcile_since(), time.time(), delta=5)

    def test_inherited_fill_ts_is_the_persisted_one(self):
        _clean_persist()
        bot = IncentiveMarketMaker(client=_FillsClient(), live=True)
        bot.state.last_fill_ts = 1_790_000_000
        bot._save_persist()
        bot2 = IncentiveMarketMaker(client=_FillsClient(), live=True)
        self.assertEqual(bot2._inherited_fill_ts, 1_790_000_000)
        _clean_persist()

    def test_read_failure_adopts_nothing(self):
        bot = self._live_bot()

        def boom(**kw):
            raise RuntimeError("503")
        bot.client.get_fills = boom
        bot._reconcile_orphaned_fills({self.T: 10.0})
        self.assertEqual(bot.pnl.pos.get(self.T, 0.0), 0.0)

    def test_first_live_cycle_leaves_the_manual_fill_out(self):
        """End to end through run_cycle, the KXMLBSEASONGAMES shape."""
        bot = self._live_bot()
        bot.state.universe_at = time.time()
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -25.0, 38.0
        bot.client.positions[self.T] = -47.36
        bot.client.fills = [self._fill("jack-f1", "jack-o1", "22.36", "0.43",
                                       side="no", action="buy")]
        bot.client.order_lookup = {"jack-o1": {"client_order_id": ""}}
        bot.run_cycle()
        self.assertEqual((bot.pnl.pos[self.T], bot.pnl.avg[self.T]), (-25.0, 38.0))


class TestFullUnwind(unittest.TestCase):
    """Jack 2026-10-01, on KXNFLESCALATORRSHYDS-26OCT01PITCLE-PITJWARREN30
    (short 240 at the x4 skew limit, the reducing bid resting the ladder's
    80): "happy to unload the whole position on the other side so can quote
    240". The sports ladder / escalator family's reducing side rests
    max(ladder, whole position) up to the position cap."""
    T = "KXGOOD-99DEC31-A"

    def test_sizes(self):
        with mock.patch.dict(imm.SERIES_OVERRIDES):
            imm.ensure_family_override("KXNFLESCALATORRSHYDS")
            f = imm.unwind_side_sizes
            self.assertTrue(imm.series_unwind_full("KXNFLESCALATORRSHYDS"))
            self.assertEqual(f("KXNFLESCALATORRSHYDS", -240.0, 600.0), (240, 0))
            self.assertEqual(f("KXNFLESCALATORRSHYDS", 100.0, 600.0), (0, 100))
            self.assertEqual(f("KXNFLESCALATORRSHYDS", -36.4, 600.0), (36, 0))
            self.assertEqual(f("KXNFLESCALATORRSHYDS", -700.0, 600.0), (600, 0))   # the cap binds
            self.assertEqual(f("KXNFLESCALATORRSHYDS", -0.5, 600.0), (0, 0))       # flat
            self.assertEqual(f("KXGOOD", -240.0, 600.0), (0, 0))                   # off the family
            imm.SERIES_OVERRIDES["KXNFLESCALATORRSHYDS"] = dataclasses.replace(
                imm.SERIES_OVERRIDES["KXNFLESCALATORRSHYDS"], unwind_full_position=False)
            self.assertEqual(f("KXNFLESCALATORRSHYDS", -240.0, 600.0), (0, 0))     # kill switch

    def test_atref_rung_carries_the_whole_position(self):
        with mock.patch.object(imm, "LADDER_MODE", "atref"):
            q = build_side_ladder(self.T, "bid", 8, 9, 840, levels=[(0, 80)], ref_px=8,
                                  band=(1, 99), min_total=240)
            self.assertEqual([(x.price_cents, x.count) for x in q], [(8, 240)])
            q = build_side_ladder(self.T, "bid", 8, 9, 840, levels=[(0, 80)], ref_px=8,
                                  band=(1, 99))
            self.assertEqual([x.count for x in q], [80])
            q = build_side_ladder(self.T, "bid", 8, 9, 100, levels=[(0, 80)], ref_px=8,
                                  band=(1, 99), min_total=240)
            self.assertEqual([x.count for x in q], [100])                       # room binds

    def test_offsets_ladder_tops_up_the_first_rung(self):
        with mock.patch.object(imm, "LADDER_MODE", "offsets"):
            q = build_side_ladder(self.T, "ask", 52, 50, 200,
                                  levels=[(0, 5), (1, 10), (2, 20)], band=(1, 99),
                                  min_total=60)
            self.assertEqual([(x.price_cents, x.count) for x in q], [(52, 30), (53, 10), (54, 20)])

    def _short_bot(self, unwind: bool):
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        bot.client.positions[self.T] = -100.0
        bot.pnl.pos[self.T], bot.pnl.avg[self.T] = -100.0, 50.0
        with mock.patch.dict(imm.SERIES_OVERRIDES,
                             {"KXGOOD": imm.SeriesOverride(unwind_full_position=unwind)}), \
                mock.patch.object(imm, "LADDER_MODE", "offsets"):
            bot.run_cycle()
        return {side: sum(o["remaining_count"] for o in bot.state.sim_orders.values()
                          if o["ticker"] == self.T and o["book_side"] == side)
                for side in ("bid", "ask")}

    def test_cycle_rests_the_whole_position_on_the_reducing_side(self):
        """Short 100 at the default 100 cap: the skew pulls the selling side
        either way; the buying side rests the ladder's 35 without the flag
        and the whole 100 with it -- past the placement guard, which lifts
        its side cap for the reducing side only."""
        self.assertEqual(self._short_bot(unwind=False), {"bid": 35.0, "ask": 0})
        self.assertEqual(self._short_bot(unwind=True), {"bid": 100.0, "ask": 0})


