    def test_cached_series_verdicts_are_rescored_against_the_keywords(self):
        # The series cache now carries the settlement-source blobs, so a
        # keyword added after the read (openrouter, 9/24) re-judges a cached
        # verdict IN PLACE -- the scan_history_rescore pattern.
        now_ts = time.time()
        ent = {"ts": now_ts, "ok": True, "why": "",
               "category": "Science and Technology", "fiscal": False,
               "sources": ["openrouter - ai model rankings "
                           "https://openrouter.ai/rankings#top-models"]}
        self.assertEqual(imm.scan_cached_verdict(ent), (False, "live_source"))
        with mock.patch.object(imm, "SCAN_LIVE_SOURCE_KEYWORDS", ("espn",)):
            # keyword gone -> a cached live_source reject reads ok again
            self.assertEqual(imm.scan_cached_verdict(
                dict(ent, ok=False, why="live_source")), (True, ""))
            self.assertEqual(imm.scan_cached_verdict(ent), (True, ""))
        # a pre-9/24 ok-verdict has no sources: STALE, re-read (fail closed
        # -- that is how KXTOKENUSE sat admitted on a week-old ok)
        self.assertIsNone(imm.scan_cached_verdict(
            {"ts": now_ts, "ok": True, "why": "", "category": "Economics",
             "fiscal": False}))
        # ... a pre-9/24 live_source reject is trusted to its TTL, and the
        # category branch is untouched
        self.assertEqual(imm.scan_cached_verdict(
            {"ts": now_ts, "ok": False, "why": "live_source",
             "category": "Sports"}), (False, "live_source"))
        self.assertEqual(imm.scan_cached_verdict(
            {"ts": now_ts, "ok": False, "why": "category:unknown",
             "category": "", "sources": []}), (False, "category:unknown"))
        # bot level: the read persists the blobs; a later keyword change
        # lands with NO re-read
        bot = self._bot(sources=[{"name": "OpenRouter",
                                  "url": "https://openrouter.ai/rankings"}])
        self.assertEqual(bot._scan_series_ok(self.S, now_ts, {"series": 5}),
                         (False, "live_source"))
        self.assertEqual(bot.state.scan_series_meta[self.S]["sources"],
                         ["openrouter https://openrouter.ai/rankings"])
        reads = bot.client.series_reads
        with mock.patch.object(imm, "SCAN_LIVE_SOURCE_KEYWORDS", ("espn",)):
            self.assertEqual(bot._scan_series_ok(self.S, now_ts,
                                                 {"series": 5}), (True, ""))
        self.assertEqual(bot.client.series_reads, reads)
        # a stale (source-less) ok entry costs one read, then carries sources
        bot.state.scan_series_meta[self.S] = {
            "ts": now_ts, "ok": True, "why": "",
            "category": "Science and Technology", "fiscal": False}
        self.assertEqual(bot._scan_series_ok(self.S, now_ts, {"series": 5}),
                         (False, "live_source"))
        self.assertEqual(bot.client.series_reads, reads + 1)
        self.assertIn("sources", bot.state.scan_series_meta[self.S])

    def test_live_source_rejects_when_the_reward_window_covers_the_market(self):
        # Jack 2026-09-24: "dont quote markets that are easily adversely
        # selected against because there is live data flowing visibly ...
        # AND the market resolution overlaps entirely or almost entirely
        # with the incentive reward period". Prong B = the reward window
        # covers >= SCAN_LIVE_OVERLAP_MIN of the open->close life OR ends
        # within SCAN_LIVE_TAIL_HOURS of the close. Sampled 9/24: OpenRouter
        # weeklies 0.84-1.00 / tail 0-24h, Vercel 0.85 / 0h, YouTube 1.00 /
        # 0h -> all rejected.
        now = datetime.now(timezone.utc)

        def meta(open_h_ago, close_h_ahead, start_h_ago, end_h_ahead, **kw):
            base = dict(open_time=now - timedelta(hours=open_h_ago),
                        close_time=now + timedelta(hours=close_h_ahead),
                        program_start=now - timedelta(hours=start_h_ago),
                        program_end=now + timedelta(hours=end_h_ahead))
            base.update(kw)
            return self._meta(**base)

        self.assertEqual(imm.SCAN_LIVE_OVERLAP_MIN, 0.8)
        self.assertEqual(imm.SCAN_LIVE_TAIL_HOURS, 24.0)
        # KXTOKENUSE-26SEP28 shape: the program IS the market's life
        full = meta(80, 88, 80, 88)
        self.assertEqual(imm.live_window_overlap(full), (1.0, 0.0))
        self.assertTrue(imm.live_reward_overlaps(full))
        # a 3-day listing boost early in a 30-day market: not (almost) entire
        boost = meta(24, 696, 24, 48)
        frac, tail = imm.live_window_overlap(boost)
        self.assertAlmostEqual(frac, 0.1)
        self.assertAlmostEqual(tail, 648.0)
        self.assertFalse(imm.live_reward_overlaps(boost))
        # ... but a short boost that runs INTO the close is the reveal
        # (KXOPENSHARE-26SEP21: the last 3.3 days of a 6.5-day week)
        late = meta(80, 12, 60, 12)
        self.assertLess(imm.live_window_overlap(late)[0], 0.8)
        self.assertTrue(imm.live_reward_overlaps(late))
        # 0.84 covered / 24h tail (the widest OpenRouter shape seen) rejects
        edge = meta(100, 24, 100, 0)
        self.assertGreaterEqual(imm.live_window_overlap(edge)[0], 0.8)
        self.assertTrue(imm.live_reward_overlaps(edge))
        # unknown timestamps fail closed
        self.assertIsNone(imm.live_window_overlap(meta(80, 88, 80, 88,
                                                       open_time=None)))
        self.assertTrue(imm.live_reward_overlaps(meta(80, 88, 80, 88,
                                                      program_start=None)))
        self.assertTrue(imm.live_reward_overlaps(meta(24, 696, 24, 48,
                                                      close_time=None)))
        # kill switch: OVERLAP_MIN <= 0 = the pure live-source reject
        with mock.patch.object(imm, "SCAN_LIVE_OVERLAP_MIN", 0.0):
            self.assertTrue(imm.live_reward_overlaps(boost))
        # admission: live source + covering window rejects; live source +
        # an early boost passes through to the history screen; every other
        # family reject stands regardless of the window
        bot = self._bot(sources=[{"name": "OpenRouter",
                                  "url": "https://openrouter.ai/rankings"}])
        m = self._market(self.A)
        budget = {"series": 5, "history": 5}
        self.assertEqual(bot._scan_admission(full, m, {}, now, budget),
                         "live_source")
        self.assertEqual(bot._scan_admission(late, m, {}, now, budget),
                         "live_source")
        self.assertIsNone(bot._scan_admission(boost, m, {}, now, budget))
        with mock.patch.object(imm, "SCAN_LIVE_OVERLAP_MIN", 0.0):
            self.assertEqual(bot._scan_admission(boost, m, {}, now, budget),
                             "live_source")
        with mock.patch.object(imm, "SCAN_EXCLUDE_CATEGORIES",
                               frozenset({"Economics"})):
            bot.state.scan_series_meta.clear()
            bot.client.series_meta[self.S] = {"category": "Economics"}
            self.assertEqual(bot._scan_admission(boost, m, {}, now, budget),
                             "category:Economics")
        # the quote-gaps mirror applies prong B when handed the meta, and
        # reads the conservative 'live_source' without one
        import imm_quote_gaps as qg
        bot.state.scan_series_meta[self.S] = {
            "ts": now.timestamp(), "ok": False, "why": "live_source",
            "category": "Science and Technology", "fiscal": False,
            "sources": ["openrouter https://openrouter.ai/rankings"]}
        bot.state.scan_history_cache.clear()
        self.assertEqual(qg.scan_gap_label(bot, self.A, now), "live_source")
        self.assertEqual(qg.scan_gap_label(bot, self.A, now, meta=full),
                         "live_source")
        self.assertNotEqual(qg.scan_gap_label(bot, self.A, now, meta=boost),
                            "live_source")

    def test_a_member_whose_series_turns_live_is_evicted_on_refresh(self):
        # The 9/24 deploy shape: KXTOKENUSE / KXXIAOMISHARE / KX*VREQ members
        # sat on cached ok-verdicts. Members skip admission, so the refresh
        # re-tests the POLICY screens on them: the source-less entry is
        # re-read, the series is now live-source, the reward window covers
        # the market -> the member leaves the candidate list, the selection
        # and (through the stray-order sweep) its quotes. A member on a
        # scheduled-release source is retained by the same pass.
        now = datetime.now(timezone.utc)
        fmt = "%Y-%m-%dT%H:%M:%SZ"

        def run(sources):
            bot = self._bot(sources=sources)
            # the market closes when its program ends (a weekly, like
            # KXTOKENUSE-26SEP28): the window covers 7 of 9 days
            bot.client.markets[self.A]["close_time"] = (
                now + timedelta(days=6)).strftime(fmt)
            bot.state.scan_series_meta[self.S] = {
                "ts": now.timestamp(), "ok": True, "why": "",
                "category": "Science and Technology", "fiscal": False}
            bot.state.scan_members = {self.A}
            bot.state.scan_book = {self.A}
            bot.state.sticky_prev = {self.A}
            bot.state.universe_at = 0.0
            bot.refresh_universe(now, {})
            return bot

        bot = run([{"name": "OpenRouter",
                    "url": "https://openrouter.ai/rankings"}])
        self.assertNotIn(self.A, bot.state.scan_members)
        self.assertNotIn(self.A, bot.state.selected)
        self.assertEqual(bot.state.scan_series_meta[self.S]["why"],
                         "live_source")
        # control: a scheduled-release source keeps the member
        bot = run([{"name": "EIA", "url": "https://www.eia.gov"}])
        self.assertIn(self.A, bot.state.scan_members)
        self.assertIn(self.A, bot.state.selected)
        self.assertEqual(bot.state.scan_series_meta[self.S]["why"], "")

    def test_event_activity_is_a_mean_per_market_not_a_sum(self):
        # Jack 2026-09-06: "change event cap to be avg_per_market_on_event,
        # and set that to 60". The old screen was a SUM against 250, which
        # measured BREADTH: a wide quiet ladder failed for being wide.
        # thresholds raised 2026-09-06 pm (Jack: "raise to 80 for the
        # market, and avg 100 for the event"); the STATISTIC is what this
        # test pins, so it drives the screens off the live constants
        self.assertEqual(imm.SCAN_MAX_VOLUME_24H, 80)
        self.assertEqual(imm.SCAN_MAX_EVENT_AVG_VOLUME_24H, 100)
        self.assertFalse(hasattr(imm, "SCAN_MAX_EVENT_VOLUME_24H"))
        mcap = imm.SCAN_MAX_VOLUME_24H
        ecap = imm.SCAN_MAX_EVENT_AVG_VOLUME_24H
        now = datetime.now(timezone.utc)

        def run(vols):
            """Build an event with these per-strike volumes, drive
            refresh_universe, and return (event mean the screen saw,
            {ticker: admission verdict}). Verdicts are what the ACTIVITY
            screens said — membership additionally depends on the walk's
            3-per-event slot cap, which is not what this test is about."""
            tickers = [f"{self.EV}-T{i}" for i in range(len(vols))]
            bot = self._bot(tickers=tickers)
            for t, v in zip(tickers, vols):
                bot.client.markets[t] = self._market(t, vol24=str(v))
            seen, verdicts = {}, {}
            real = bot._scan_admission
            def spy(meta, m, ev_vol24, now_utc, budget):
                seen.update(ev_vol24)
                verdicts[meta.ticker] = real(meta, m, ev_vol24, now_utc, budget)
                return verdicts[meta.ticker]
            bot._scan_admission = spy
            bot.state.universe_at = 0.0
            bot.refresh_universe(now, {})
            # FakeClient ships unrelated default markets (KXGOOD/KXWIDE) that
            # are also scan universe — judge only the event under test
            mine = {t: v for t, v in verdicts.items() if t.startswith(self.EV)}
            return seen.get(self.EV), mine, bot

        # SIX strikes at the market cap each: the sum is 6x the cap, which a
        # SUM rule rejects for the event being WIDE; the mean equals the
        # per-strike volume, so every strike is admitted. This is the
        # KXAGTWINNER-26SEP24 class the 9/6 measurement found.
        mean, verdicts, bot = run([mcap] * 6)
        self.assertAlmostEqual(mean, mcap)
        self.assertLessEqual(mean, ecap)
        self.assertEqual(set(verdicts.values()), {None})
        self.assertEqual(len(bot.state.scan_members), imm.SCAN_EVENT_TOP_N)

        # TWO strikes, one silent and one far over the event cap: the mean
        # exceeds the cap, so the QUIET one is rejected too — the
        # neighbour-contamination the screen exists for
        hot = int(ecap * 2 + 2)
        mean, verdicts, bot = run([0, hot])
        self.assertAlmostEqual(mean, hot / 2.0)
        self.assertGreater(mean, ecap)
        self.assertEqual(verdicts[f"{self.EV}-T0"], "event_avg_volume")
        self.assertEqual(verdicts[f"{self.EV}-T1"], "volume")  # its own cap
        self.assertEqual(bot.state.scan_members, set())

        # KNOWN, DELIBERATE LOOSENING (documented at the constant): one hot
        # strike hides behind quiet siblings — 20 strikes, one very busy,
        # mean under the cap -> the quiet ones pass the event screen and the
        # hot one still fails the per-market cap. The old sum and a max()
        # would both have rejected the whole event. Pinned so nobody "fixes"
        # it by accident.
        buried = int(ecap * 20)          # mean lands exactly on the cap
        mean, verdicts, bot = run([buried] + [0] * 19)
        self.assertAlmostEqual(mean, ecap)
        self.assertGreater(buried, mcap)
        self.assertEqual(verdicts[f"{self.EV}-T0"], "volume")
        self.assertEqual({v for t, v in verdicts.items()
                          if t != f"{self.EV}-T0"}, {None})

    def test_admission_screens_fail_closed(self):
        bot = self._bot()
        now = datetime.now(timezone.utc)
        m = self._market(self.A)
        budget = {"series": 5, "history": 5}
        self.assertIsNone(bot._scan_admission(self._meta(), m, {}, now, budget))
        self.assertEqual(budget, {"series": 4, "history": 4})
        # cached verdicts: a zero budget still admits (no read needed)
        self.assertIsNone(bot._scan_admission(
            self._meta(), m, {}, now, {"series": 0, "history": 0}))
        # activity screens
        self.assertEqual(bot._scan_admission(
            self._meta(open_time=None), m, {}, now, budget), "age")
        self.assertEqual(bot._scan_admission(
            self._meta(open_time=now - timedelta(hours=2)), m, {}, now,
            budget), "age")
        # Jack 2026-09-10: "drop the open scan 24h requirement to 6h"
        self.assertEqual(imm.SCAN_MIN_AGE_HOURS, 6)
        # and "bulk read the top 2k markets by pool by day"; 2026-09-22 pm
        # "set default to 5000" -- the whole 3,018-market universe read
        # every refresh, no more feed-order lottery among the $14.29 ties
        self.assertEqual(imm.SCAN_MAX_BULK, 5000)
        self.assertIsNone(bot._scan_admission(
            self._meta(open_time=now - timedelta(hours=7)), m, {}, now,
            budget))
        self.assertEqual(bot._scan_admission(
            self._meta(volume_24h=imm.SCAN_MAX_VOLUME_24H + 1), m, {}, now,
            budget), "volume")
        # the event screen is an AVERAGE per market (Jack 2026-09-06)
        self.assertEqual(bot._scan_admission(
            self._meta(), m, {self.EV: imm.SCAN_MAX_EVENT_AVG_VOLUME_24H + 1},
            now, budget), "event_avg_volume")
        self.assertIsNone(bot._scan_admission(
            self._meta(), m, {self.EV: imm.SCAN_MAX_EVENT_AVG_VOLUME_24H},
            now, budget))
        # structure (strike_type from the market object counts)
        self.assertEqual(bot._scan_admission(
            self._meta(t="KXNOVEL-99DEC31-HOLD"), dict(m, strike_type="custom"),
            {}, now, budget), "shape")
        # evicted event / struck series never come back
        bot.state.scan_evicted_events[self.EV] = time.time()
        self.assertEqual(bot._scan_admission(self._meta(), m, {}, now, budget),
                         "evicted")
        bot.state.scan_evicted_events.clear()
        bot.state.scan_series_strikes[self.S] = [time.time(), time.time()]
        self.assertEqual(bot._scan_admission(self._meta(), m, {}, now, budget),
                         "series_struck")
        bot.state.scan_series_strikes.clear()
        # strikes age out
        bot.state.scan_series_strikes[self.S] = [
            time.time() - imm.SCAN_SERIES_STRIKE_TTL_SECS - 1] * 3
        self.assertIsNone(bot._scan_admission(self._meta(), m, {}, now, budget))
        bot.state.scan_series_strikes.clear()
        # family screen: category (knob only — no ban by default, Jack
        # 2026-09-06), live source, unreadable, budget
        bot.state.scan_series_meta.clear()
        bot.client.series_meta[self.S] = {"category": "Sports"}
        # (own read budgets: the shared one below is sized for the original
        # sequence of reads)
        self.assertIsNone(bot._scan_admission(
            self._meta(), m, {}, now, {"series": 5, "history": 5}))
        bot.state.scan_series_meta.clear()
        with mock.patch.object(imm, "SCAN_EXCLUDE_CATEGORIES",
                               frozenset({"Sports"})):
            self.assertEqual(bot._scan_admission(
                self._meta(), m, {}, now, {"series": 5, "history": 5}),
                "category:Sports")
        # ... a sports series on a live scoreboard is the realtime-risk
        # reject, judged per series
        bot.state.scan_series_meta.clear()
        bot.client.series_meta[self.S] = {
            "category": "Sports",
            "settlement_sources": [{"name": "ESPN", "url": "https://www.espn.com"}]}
        self.assertEqual(bot._scan_admission(
            self._meta(), m, {}, now, {"series": 5, "history": 5}),
            "live_source")
        bot.state.scan_series_meta.clear()
        bot.client.series_meta[self.S] = {
            "category": "Economics",
            "settlement_sources": [{"name": "Coinbase", "url": ""}]}
        self.assertEqual(bot._scan_admission(self._meta(), m, {}, now, budget),
                         "live_source")
        bot.state.scan_series_meta.clear()
        bot.client.series_meta.pop(self.S)
        self.assertEqual(bot._scan_admission(self._meta(), m, {}, now, budget),
                         "series_meta_unavailable")
        self.assertNotIn(self.S, bot.state.scan_series_meta)   # not cached
        bot.client.series_meta[self.S] = {
            "category": "Economics",
            "settlement_sources": [{"name": "EIA", "url": "https://www.eia.gov"}]}
        self.assertEqual(bot._scan_admission(
            self._meta(), m, {}, now, {"series": 0, "history": 5}),
            "series_meta_pending")
        self.assertIsNone(bot._scan_admission(self._meta(), m, {}, now, budget))
        # history screen: thin / moved / busy / unreadable / budget
        bot.state.scan_history_cache.clear()
        bot.client.candles[self.A] = self._candles(n=3)
        # the bar-count cap is OFF by default since 2026-09-07 — arm it to
        # keep covering the wiring from the screen to the reject reason
        with mock.patch.object(imm, "SCAN_MIN_HISTORY_BARS", 12):
            self.assertEqual(bot._scan_admission(self._meta(), m, {}, now,
                                                 budget), "history_thin")
        bot.state.scan_history_cache.clear()
        bot.client.candles[self.A] = (self._candles(n=12)
                                      + self._candles(n=8, bid=60, ask=64))
        # a 20c re-level: the RANGE cap is off since 2026-09-07, so this is
        # now caught by the JUMP cap (one 20c step)
        self.assertEqual(bot._scan_admission(self._meta(), m, {}, now, budget),
                         "history_jump")
        bot.state.scan_history_cache.clear()
        bot.client.candles[self.A] = self._candles(vol=60)   # 1200 in 72h
        self.assertEqual(bot._scan_admission(self._meta(), m, {}, now, budget),
                         "history_volume")
        bot.state.scan_history_cache.clear()
        bot.client.candles.pop(self.A)
        self.assertEqual(bot._scan_admission(self._meta(), m, {}, now, budget),
                         "history_unavailable")
        self.assertNotIn(self.A, bot.state.scan_history_cache)
        bot.client.candles[self.A] = self._candles()
        self.assertEqual(bot._scan_admission(
            self._meta(), m, {}, now, {"series": 5, "history": 0}),
            "history_pending")
        # a fresh budget (the one above is spent): admissible again
        self.assertIsNone(bot._scan_admission(
            self._meta(), m, {}, now, {"series": 5, "history": 5}))

    def test_cached_category_verdicts_follow_the_knob(self):
        # The persisted series verdict (7d TTL) is re-read against the
        # CURRENT category knob (2026-09-06 ban lift): a verdict from a
        # lifted ban is stale and triggers a fresh /series read (the
        # live-source screen needs the sources, which are not cached); a
        # category newly named on the knob rejects in place, no read.
        now_ts = time.time()
        # pure helper
        stale = {"ts": now_ts, "ok": False, "why": "category:Sports",
                 "category": "Sports"}
        self.assertIsNone(imm.scan_cached_verdict(stale))
        # ... an old entry without the category field still names it in why
        self.assertIsNone(imm.scan_cached_verdict(
            {"ts": now_ts, "ok": False, "why": "category:Politics"}))
        self.assertEqual(imm.scan_cached_verdict(
            {"ts": now_ts, "ok": True, "why": "", "category": "Sports",
             "sources": ["the league https://league.example"]}),
            (True, ""))
        # (an ok entry WITHOUT persisted sources is stale since 2026-09-24:
        # the live-source screen re-reads it -- see
        # test_cached_series_verdicts_are_rescored_against_the_keywords)
        self.assertIsNone(imm.scan_cached_verdict(
            {"ts": now_ts, "ok": True, "why": "", "category": "Sports"}))
        self.assertEqual(imm.scan_cached_verdict(
            {"ts": now_ts, "ok": False, "why": "live_source",
             "category": "Sports"}), (False, "live_source"))
        # fail-closed 'unknown' is a verdict, not a ban: trusted as cached
        self.assertEqual(imm.scan_cached_verdict(
            {"ts": now_ts, "ok": False, "why": "category:unknown",
             "category": ""}), (False, "category:unknown"))
        with mock.patch.object(imm, "SCAN_EXCLUDE_CATEGORIES",
                               frozenset({"Sports"})):
            self.assertEqual(imm.scan_cached_verdict(stale),
                             (False, "category:Sports"))
            self.assertEqual(imm.scan_cached_verdict(
                {"ts": now_ts, "ok": True, "why": "", "category": "Sports"}),
                (False, "category:Sports"))
            self.assertEqual(imm.scan_cached_verdict(
                {"ts": now_ts, "ok": True, "why": "", "category": "Economics",
                 "sources": ["eia https://www.eia.gov"]}),
                (True, ""))
        # bot-level: the stale ban re-reads the series (one budgeted read)
        # and the fresh verdict replaces the cache entry
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        bot.state.scan_series_meta[self.S] = dict(stale)
        bot.client.series_meta[self.S] = {
            "category": "Sports",
            "settlement_sources": [{"name": "Forbes", "url": "https://forbes.com"}]}
        budget = {"series": 5, "history": 5}
        self.assertEqual(bot._scan_series_ok(self.S, now_ts, budget), (True, ""))
        self.assertEqual(budget["series"], 4)
        self.assertTrue(bot.state.scan_series_meta[self.S]["ok"])
        # ... and a stale ban with no read budget left is 'pending', never
        # admitted on the strength of a lifted ban alone
        bot.state.scan_series_meta[self.S] = dict(stale)
        self.assertEqual(bot._scan_series_ok(self.S, now_ts, {"series": 0}),
                         (False, "series_meta_pending"))
        # a fresh ok verdict on a newly banned category rejects with NO read
        bot.state.scan_series_meta[self.S] = {
            "ts": now_ts, "ok": True, "why": "", "category": "Sports"}
        reads = getattr(bot.client, "series_reads", 0)
        with mock.patch.object(imm, "SCAN_EXCLUDE_CATEGORIES",
                               frozenset({"Sports"})):
            self.assertEqual(bot._scan_series_ok(self.S, now_ts, budget),
                             (False, "category:Sports"))
        self.assertEqual(getattr(bot.client, "series_reads", 0), reads)

    def test_fiscal_month_named_admission(self):
        # Bot-level: a month-named KPI market on a Fiscal.ai-settled series
        # is admissible (the series read happens BEFORE the structure
        # verdict and is cached); the same ticker on a non-fiscal series is
        # 'undated'; a month binary is 'shape' with no series read; a
        # market whose report month has begun is 'cutoff_passed'.
        _clean_persist()
        bot = IncentiveMarketMaker(client=FakeClient(), live=False)
        now = datetime.now(timezone.utc)
        now_ts = now.timestamp()
        nxt = (now.astimezone(imm.ET) + timedelta(days=40))
        ev = f"KXFISC-{nxt.strftime('%y%b').upper()}ALBD"      # next month+
        t = f"{ev}-25800000.0"
        fiscal_src = [{"name": "Fiscal.ai", "url": "https://fiscal.ai"}]
        m = dict(self._market(t), event_ticker=ev)
        bot.client.candles[t] = self._candles()
        # cutoff=None on purpose: since 2026-09-07 a RESOLVED cutoff is on
        # its own sufficient (cutoff_known short-circuits before any series
        # read), so the fiscal path is only exercised when none resolved.
        # In the live loop a month-named event already carries its month
        # cutoff by this point, so it is admitted without paying for a read.
        meta = self._meta(t=t, event_ticker=ev, series="KXFISC", cutoff=None)
        budget = {"series": 5, "history": 5}
        # fiscal series -> admissible; one series read, flag cached
        bot.client.series_meta["KXFISC"] = {"category": "Financials",
                                            "settlement_sources": fiscal_src}
        self.assertIsNone(bot._scan_admission(meta, m, {}, now, budget))
        self.assertEqual(budget["series"], 4)
        self.assertTrue(bot.state.scan_series_meta["KXFISC"]["fiscal"])
        # second look: cached, no further read
        self.assertIsNone(bot._scan_admission(meta, m, {}, now, budget))
        self.assertEqual(budget["series"], 4)
        # a verdict persisted before the flag existed is re-read once
        bot.state.scan_series_meta["KXFISC"] = {
            "ts": now_ts, "ok": True, "why": "", "category": "Financials"}
        self.assertIsNone(bot._scan_admission(meta, m, {}, now, budget))
        self.assertEqual(budget["series"], 3)
        self.assertIn("fiscal", bot.state.scan_series_meta["KXFISC"])
        # non-fiscal series: the month is no guard -> 'undated', cached so
        # the string pre-screen drops it next refresh without a read
        bot.state.scan_series_meta.clear()
        bot.client.series_meta["KXFISC"] = {
            "category": "Economics",
            "settlement_sources": [{"name": "EIA", "url": "https://eia.gov"}]}
        self.assertEqual(bot._scan_admission(meta, m, {}, now, budget), "undated")
        self.assertFalse(bot.state.scan_series_meta["KXFISC"]["fiscal"])
        self.assertFalse(imm.scan_month_prescreen_ok(
            t, bot.state.scan_series_meta["KXFISC"]))
        # read budget exhausted while unknown: pending, never admitted on
        # the month alone
        bot.state.scan_series_meta.clear()
        self.assertEqual(bot._scan_admission(meta, m, {}, now, {"series": 0}),
                         "series_meta_pending")
        # a month-named BINARY never earns the series read
        bot.state.scan_series_meta.clear()
        reads = getattr(bot.client, "series_reads", 0)
        tb = f"{ev}-YES"
        self.assertEqual(bot._scan_admission(
            self._meta(t=tb, event_ticker=ev, series="KXFISC"),
            dict(self._market(tb), event_ticker=ev, strike_type="custom"),
            {}, now, budget), "shape")
        self.assertEqual(getattr(bot.client, "series_reads", 0), reads)
        # report month already begun: out (the cutoff is the month start)
        bot.client.series_meta["KXFISC"] = {"category": "Financials",
                                            "settlement_sources": fiscal_src}
        bot.state.scan_series_meta.clear()
        past_ev = f"KXFISC-{now.astimezone(imm.ET).strftime('%y%b').upper()}ALBD"
        pt = f"{past_ev}-1"
        self.assertEqual(bot._scan_admission(
            self._meta(t=pt, event_ticker=past_ev, series="KXFISC",
                       cutoff=imm.scan_report_month_cutoff(past_ev, None)),
            dict(self._market(pt), event_ticker=past_ev), {}, now, budget),
            "cutoff_passed")

    # ---- the walk ------------------------------------------------------------

    def test_group_walk_15_slots_3_per_event_openings(self):
        def m(t, est, scan=True):
            return imm.MarketMeta(
                ticker=t, event_ticker=t.rsplit("-", 1)[0],
                series=t.split("-")[0], dollars_per_day=20.0,
                program_end=None, target_size=1000, discount_factor=0.5,
                cutoff=None, close_time=None, est_dollars_per_day=est,
                est_exposure_dollars=10.0, est_collateral_dollars=0.0,
                scan=scan)
        # the walk MECHANICS are what this pins; the production slot count
        # moved 15 -> 30 on 2026-09-07 and 30 -> 60 (hard cap, openings 0)
        # on 2026-09-13, and neither must break the fixture
        self.assertEqual(imm.SCAN_TOP_N, 60)
        self.assertEqual(imm.SCAN_DAILY_OPENINGS, 0)
        self.enterContext(mock.patch.object(imm, "SCAN_TOP_N", 15))
        self.enterContext(mock.patch.object(imm, "SCAN_DAILY_OPENINGS", 5))
        self.assertEqual(imm.SCAN_EVENT_TOP_N, 3)
        # 5 strikes of one event with the best ROIs: only 3 survive, the
        # slack flows to other events; a non-scan meta is never touched
        ev1 = [m(f"KXAAA-26SEP09-T{i}", 9.0 - i) for i in range(5)]
        ev2 = [m(f"KXBBB-26SEP09-T{i}", 3.0 - i * 0.1) for i in range(3)]
        others = [m(f"KXC{i}-26SEP09-T1", 1.0 - i * 0.01) for i in range(12)]
        fin = [m("KXSPRLVL-26SEP09-T286", 50.0, scan=False)]
        cut = imm.scan_group_cut(ev1 + ev2 + others + fin, incumbent=set())
        kept = {x.ticker for x in ev1 + ev2 + others} - cut
        self.assertEqual(len(kept), 15)
        self.assertEqual(sum(1 for t in kept if t.startswith("KXAAA")), 3)
        self.assertEqual(sum(1 for t in kept if t.startswith("KXBBB")), 3)
        self.assertEqual(sum(1 for t in kept if t.startswith("KXC")), 9)
        self.assertNotIn("KXSPRLVL-26SEP09-T286", cut)
        # members are never cut and consume slots; openings go THROUGH a
        # full cap, never past the per-event 3
        members = [m(f"KXM{e}-26SEP09-T{i}", 0.01) for e in range(5)
                   for i in range(3)]
        mem_ids = {x.ticker for x in members}
        new = [m("KXNEW-26OCT07-T100", 9.0), m("KXNEW-26OCT07-T102", 8.0),
               m("KXNEW-26OCT07-T104", 7.5), m("KXNEW-26OCT07-T106", 7.0),
               m("KXOTHER-26OCT03-T95", 6.0)]
        cut = imm.scan_group_cut(members + new, set(), members=mem_ids)
        self.assertEqual(cut, {x.ticker for x in new})
        cut = imm.scan_group_cut(members + new, set(), members=mem_ids,
                                 extra_openings=5)
        self.assertEqual(cut, {"KXNEW-26OCT07-T106"})
        self.assertEqual(imm.scan_openings_used(19, 15), 4)
        self.assertEqual(imm.scan_openings_used(15, 15), 0)
        self.assertEqual(imm.scan_openings_used(14, 12), 0)
        # finecon's walk still answers to ITS knobs (shared engine).
        # Driven off FINECON_TOP_N so raising the cap (15 -> 20 on
        # 2026-09-09) cannot silently invalidate the fixture.
        _f = imm.FINECON_TOP_N
        self.assertEqual(imm.finecon_openings_used(_f + 2, _f), 2)
        self.assertEqual(imm.finecon_openings_used(_f, _f), 0)

    # ---- guard geometry ------------------------------------------------------

    def test_guard_set_applied_tightened_released(self):
        # Jack 2026-09-05 pm: "same contracts/max net position/deep
        # reference/overnight size as the normal book" — the guard set is
        # safe-join + no rate bar; sizing is inherited, not overridden
        self.assertIsNone(imm.SCAN_LEVELS)
        self.assertIsNone(imm.SCAN_MAX_POSITION)
        imm.ensure_scan_override(self.S)
        ov = imm.SERIES_OVERRIDES[self.S]
        self.assertIsNone(ov.levels)
        self.assertIsNone(ov.max_position)
        self.assertEqual(imm.series_levels(self.S), imm.LEVELS)
        self.assertEqual(imm.series_max_position(self.S),
                         imm.MAX_POSITION_CONTRACTS)
        self.assertTrue(imm.series_safe_join(self.S))
        self.assertEqual(imm.series_min_est_rate(self.S), 0.0)
        # a dormant hand-tuned entry (the re-entry loop seeds company series
        # that are not allowlisted) keeps its own ladder/cap and gains
        # safe-join + no rate bar
        prior = imm.SeriesOverride(min_est_per_day=2.0, safe_join=True,
                                   max_position=150)
        imm.SERIES_OVERRIDES["KXPRIOR"] = prior
        imm.ensure_scan_override("KXPRIOR")
        ov2 = imm.SERIES_OVERRIDES["KXPRIOR"]
        self.assertIsNone(ov2.levels)
        self.assertEqual(ov2.max_position, 150)
        self.assertEqual(ov2.min_est_per_day, 0.0)
        self.assertTrue(ov2.safe_join)
        # the optional tightening knobs still bite when set
        old_l, old_p = imm.SCAN_LEVELS, imm.SCAN_MAX_POSITION
        imm.release_scan_override(self.S)
        imm.release_scan_override("KXPRIOR")
        imm.SCAN_LEVELS, imm.SCAN_MAX_POSITION = [(0, 10)], 50.0
        try:
            imm.ensure_scan_override(self.S)
            self.assertEqual(imm.series_levels(self.S), [(0, 10)])
            self.assertEqual(imm.series_max_position(self.S), 50)
            imm.ensure_scan_override("KXPRIOR")
            self.assertEqual(imm.SERIES_OVERRIDES["KXPRIOR"].max_position, 50)
        finally:
            imm.SCAN_LEVELS, imm.SCAN_MAX_POSITION = old_l, old_p
        imm.release_scan_override("KXPRIOR")
        self.assertIs(imm.SERIES_OVERRIDES["KXPRIOR"], prior)
        imm.release_scan_override(self.S)
        self.assertNotIn(self.S, imm.SERIES_OVERRIDES)
        self.assertNotIn(self.S, imm.SCAN_GUARDED_SERIES)

    def test_scan_ladder_geometry_matches_normal_book_plus_safe_join(self):
        # build_side_ladder is the single placement site (quote loop AND
        # estimator). A scan series rests the SAME ladder at the SAME
        # deep-reference size as an ordinary series on the same book; the
        # only difference is safe-join placement.
        imm.ensure_scan_override(self.S)
        lv = imm.series_levels(self.S)
        self.assertEqual(lv, imm.LEVELS)
        total = sum(s for _t, s in lv)
        # reference 4 ticks behind a 49 touch: the rung rests AT the
        # reference (safe-join wants 47; 45 is deeper, so 45 wins) at the
        # full 1 + 0.25 x 4 = 2.0x size — identical to the ordinary series
        q = imm.build_side_ladder(self.A, "bid", 49, 51, room=1000,
                                  levels=lv, ref_px=45)
        q_other = imm.build_side_ladder("KXOTHER-99DEC31-T5", "bid", 49, 51,
                                        room=1000, levels=lv, ref_px=45)
        self.assertEqual([(x.price_cents, x.count) for x in q],
                         [(45, total * 2)])
        self.assertEqual([(x.price_cents, x.count) for x in q],
                         [(x.price_cents, x.count) for x in q_other])
        # reference AT the touch: safe-join wants 47 but is capped at the
        # reference (2026-08-05: two ticks below a touch-level reference
        # scores exactly zero), so the rung joins the touch at plain size
        q = imm.build_side_ladder(self.A, "bid", 49, 51, room=1000,
                                  levels=lv, ref_px=49)
        self.assertEqual([(x.price_cents, x.count) for x in q], [(49, total)])
        # a wide book (spread >= 5) is its own safety net: no offset applied
        q = imm.build_side_ladder(self.A, "bid", 40, 60, room=1000,
                                  levels=lv, ref_px=40)
        self.assertEqual([(x.price_cents, x.count) for x in q], [(40, total)])
        # room (position cap / event share / skew) still shaves the rung
        q = imm.build_side_ladder(self.A, "ask", 51, 49, room=4,
                                  levels=lv, ref_px=51)
        self.assertEqual([(x.price_cents, x.count) for x in q], [(51, 4)])
        # the optional ref-mult cap knob shrinks ONLY the scan series
        imm.SCAN_REF_MULT_CAP = 1.5
        try:
            q = imm.build_side_ladder(self.A, "bid", 49, 51, room=1000,
                                      levels=lv, ref_px=45)
            self.assertEqual([(x.price_cents, x.count) for x in q],
                             [(45, int(round(total * 1.5)))])
            q_other = imm.build_side_ladder("KXOTHER-99DEC31-T5", "bid", 49,
                                            51, room=1000, levels=lv, ref_px=45)
            self.assertEqual(q_other[0].count, total * 2)
        finally:
            imm.SCAN_REF_MULT_CAP = 0.0

    def test_overnight_and_deep_reference_sizing_match_normal_book(self):
        imm.ensure_scan_override(self.S)
        now = datetime.now(timezone.utc)
        old = imm.HOUR_SIZE_MULTS
        imm.HOUR_SIZE_MULTS = {h: 2.0 for h in range(24)}
        try:
            # same quiet-hours window as every other series...
            self.assertEqual(imm.hour_size_mult(self.S, now), 2.0)
            self.assertEqual(imm.hour_scaled_levels(self.S, now),
                             imm.hour_scaled_levels("KXOTHER", now))
            # ...unless the knob switches it off for the tier
            imm.SCAN_HOUR_MULT = False
            try:
                self.assertEqual(imm.hour_size_mult(self.S, now), 1.0)
                self.assertEqual(imm.hour_size_mult("KXOTHER", now), 2.0)
            finally:
                imm.SCAN_HOUR_MULT = True
        finally:
            imm.HOUR_SIZE_MULTS = old
        old_mode = imm.LADDER_MODE
        imm.LADDER_MODE = "atref"
        try:
            # same deep-reference multiplier as the normal book...
            self.assertEqual(imm.SCAN_REF_MULT_CAP, 0.0)
            self.assertEqual(imm.capped_ref_mult(50, 30, "bid", series=self.S),
                             3.0)
            self.assertEqual(imm.capped_ref_mult(50, 30, "bid", series=self.S),
                             imm.capped_ref_mult(50, 30, "bid", series="KXOTHER"))
            # ...unless the knob caps it for the tier
            imm.SCAN_REF_MULT_CAP = 1.5
            try:
                self.assertEqual(
                    imm.capped_ref_mult(50, 30, "bid", series=self.S), 1.5)
                self.assertEqual(
                    imm.capped_ref_mult(50, 30, "bid", series="KXOTHER"), 3.0)
                self.assertEqual(
                    imm.capped_ref_mult(50, 49, "bid", series=self.S), 1.25)
            finally:
                imm.SCAN_REF_MULT_CAP = 0.0
        finally:
            imm.LADDER_MODE = old_mode

    # ---- end to end: admission, quoting geometry, persistence ----------------

    def test_admission_quotes_with_scan_geometry(self):
        bot = self._bot()
        bot.run_cycle()
        self.assertIn(self.A, bot.state.selected)
        self.assertTrue(bot.state.selected[self.A].scan)
        self.assertEqual(bot.state.scan_members, {self.A})
        self.assertIn(self.A, bot.state.scan_book)
        self.assertEqual(bot.state.scan_entry_mid[self.A], 50.0)
        self.assertIn(self.S, imm.SCAN_GUARDED_SERIES)
        # the fixture's KXGOOD/KXWIDE are NOT allowed under the real policy
        # and carry categorical strikes -> never enter via the scan either
        self.assertNotIn("KXGOOD-99DEC31-A", bot.state.selected)
        self.assertNotIn("KXWIDE-99DEC31-B", bot.state.selected)
        # one at-reference rung per side at the NORMAL book's size (Jack
        # 2026-09-05 pm): on this 49x51 book the reference IS the touch
        # (600 at 49 >= target/5), so safe-join is capped there and the
        # rung joins at 49/51 — never improving the touch
        self.assertEqual(imm.series_levels(self.S), imm.LEVELS)
        total = float(sum(s for _t, s in imm.LEVELS))
        orders = self._orders(bot, self.A)
        rungs = [o for o in orders if o[1] not in (imm.PAD_BID_CENTS,
                                                    imm.PAD_ASK_CENTS)]
        bids = [o for o in rungs if o[0] == "bid"]
        asks = [o for o in rungs if o[0] == "ask"]
        self.assertEqual([(o[1], o[2]) for o in bids], [(49, total)])
        self.assertEqual([(o[1], o[2]) for o in asks], [(51, total)])
        # status carries the tier
        bot.write_status(datetime.now(timezone.utc))
        with open(os.path.join(imm.STATUS_DIR, "status_incentive_mm.json"),
                  encoding="utf-8") as f:
            st = json.load(f)
        self.assertEqual(st["scan_members"], [self.A])
        self.assertEqual(st["scan_slots"], f"1/{imm.SCAN_TOP_N}")
        self.assertFalse(st["scan_halted_today"])
        # the admission was an in-cap slot fill: no opening burned
        self.assertEqual(bot.state.scan_admits_today, 0)

