class TestLowTempFamily(unittest.TestCase):
    """Jack 2026-10-23: "Build low temp fair value as part of IMM, only quote
    the next day never the same day (I should have the bones already as part
    of the low temp bot)"."""

    T = "KXLOWTEWR-26OCT24-B38.5"

    def setUp(self):
        self._p = [mock.patch.dict(imm._lowt_owner, {"at": 1e18, "paused": True}),
                   mock.patch.dict(imm._lowt_state, {"mtime": 0.0, "events": {}})]
        for x in self._p:
            x.start()

    def tearDown(self):
        for x in self._p:
            x.stop()

    def _read(self, now_ts, **kw):
        e = {"ts": now_ts - 600, "mu": 38.3, "b": 1.79, "nws": 38.0, "wu": None,
             "skip": None, "markets": {self.T: 0.30, "KXLOWTEWR-26OCT24-T38": 0.60}}
        e.update(kw)
        imm._lowt_state["events"]["KXLOWTEWR-26OCT24"] = e

    def test_allowed_only_while_the_low_bot_is_paused(self):
        prev = imm.ALLOWLIST_ONLY
        try:
            imm.ALLOWLIST_ONLY = True
            self.assertTrue(imm.lowt_series("KXLOWTEWR"))
            self.assertTrue(IncentiveMarketMaker._allowed(self.T))
            self.assertFalse(imm.lowt_series("KXLOW"))                 # Lowe's KPI series
            with mock.patch.dict(imm._lowt_owner, {"at": 1e18, "paused": False}):
                self.assertFalse(imm.lowt_series("KXLOWTEWR"))
                self.assertFalse(IncentiveMarketMaker._allowed(self.T))
            with mock.patch.object(imm, "LOWT_ENABLE", False):
                self.assertFalse(imm.lowt_series("KXLOWTEWR"))
        finally:
            imm.ALLOWLIST_ONLY = prev
        # the flag is the low bot's own pause file, re-checked by the minute
        with tempfile.TemporaryDirectory() as d:
            flag = os.path.join(d, "low_temp.paused")
            with mock.patch.object(imm, "LOWT_OWNER_FLAG", flag):
                self.assertFalse(imm.lowt_owner_paused(force=True))
                open(flag, "w").close()
                self.assertFalse(imm.lowt_owner_paused(now_ts=time.time()))   # cached
                self.assertTrue(imm.lowt_owner_paused(force=True))

    def test_next_day_only(self):
        # out at 00:00 ET of the market day: never quoted on the day itself
        self.assertEqual(imm.trade_cutoff_utc("KXLOWTEWR-26OCT24", None, None),
                         utc(2026, 10, 24, 4, 0))
        self.assertEqual(imm.trade_cutoff_utc("KXLOWTLAX-26DEC02", None, None),
                         utc(2026, 12, 2, 5, 0))                      # EST, still ET midnight

    def test_gate_fails_closed_and_stands_aside_only_far_from_fair(self):
        now = time.time()
        g = imm.lowt_gate
        self.assertEqual(g(self.T, now, 28, 32)[1]["reason"], "no_read")
        self._read(now, ts=now - (imm.LOWT_FAIR_TTL_MIN * 60 + 5))
        self.assertEqual(g(self.T, now, 28, 32)[1]["reason"], "stale")
        self._read(now, skip="late-day drop: x")
        self.assertEqual(g(self.T, now, 28, 32)[1]["reason"], "skip")
        self._read(now)
        self.assertEqual(g("KXLOWTEWR-26OCT24-B40.5", now, 28, 32)[1]["reason"], "no_market")
        # fair 30c, tol 40c (Jack 2026-10-24: "Yes widen"): a touch inside the
        # band quotes, unchanged
        self.assertEqual(imm.LOWT_FAIR_TOL_CENTS, 40)
        why, inputs = g(self.T, now, 50, 60)
        self.assertEqual((why, inputs["fair"]), ("", 30.0))
        self.assertEqual(g(self.T, now, 70, 75)[0], "")              # bid exactly at fair + tol
        why, inputs = g(self.T, now, 71, 75)                         # bid touch above fair + tol
        self.assertEqual((inputs["reason"], inputs["bid_bad"]), ("band", True))
        t38 = "KXLOWTEWR-26OCT24-T38"                                # fair 60c
        self.assertEqual(g(t38, now, 15, 20)[0], "")                 # ask exactly at fair - tol
        why, inputs = g(t38, now, 15, 19)                            # ask touch under fair - tol
        self.assertEqual((inputs["reason"], inputs["ask_bad"]), ("band", True))

    def test_the_fair_file_reloads_by_mtime(self):
        with tempfile.TemporaryDirectory() as d:
            path = os.path.join(d, "lowt_fair.json")
            with open(path, "w", encoding="utf-8") as f:
                json.dump({"events": {"KXLOWTEWR-26OCT24": {
                    "fetched_at": "2026-10-23T19:00:00+00:00", "skip": None,
                    "markets": {self.T: 0.3}},
                    "KXLOWTX-26OCT24": {"fetched_at": "bad"}}}, f)
            with mock.patch.object(imm, "LOWT_FAIR_FILE", path):
                self.assertEqual(imm.load_lowt_fair(), 1)
                self.assertEqual(imm.load_lowt_fair(), 0)               # unchanged mtime
            e = imm._lowt_state["events"]["KXLOWTEWR-26OCT24"]
            self.assertEqual(e["ts"], utc(2026, 10, 23, 19, 0).timestamp())

    def test_family_size_x3_and_band_3_to_97(self):
        # Jack 2026-10-23: "3x and also extend range to 3-97"; x5 since
        # 2026-10-24 ("5x multiplier")
        names = ("KXLOWTEWR", "KXLOWTZZZ", "KXLOWTSEA")    # ZZZ: a city listed later
        saved = {s: imm.SERIES_OVERRIDES.pop(s, None) for s in names}
        try:
            for s in names[:2]:
                imm.ensure_family_override(s)
                ov = imm.series_override(s)
                self.assertEqual((ov.size_mult, ov.price_min_cents, ov.price_max_cents),
                                 (5.0, 3, 97), s)
                self.assertEqual(imm.member_price_band(s, False), (3, 97))
                self.assertEqual(imm.member_price_band(s, True), (3, 97))
                self.assertIsNone(imm.size_test_arm(s))                 # out of the size test
                self.assertEqual(imm.applied_mention_mult(s), 5.0)
            # the low bot running again: no family, no clone
            with mock.patch.dict(imm._lowt_owner, {"at": 1e18, "paused": False}):
                imm.ensure_family_override("KXLOWTSEA")
                self.assertIsNone(imm.series_override("KXLOWTSEA"))
        finally:
            for s, ov in saved.items():
                imm.SERIES_OVERRIDES.pop(s, None)
                if ov is not None:
                    imm.SERIES_OVERRIDES[s] = ov
        for k in ("LOWT_SIZE_MULT", "LOWT_PRICE_MIN", "LOWT_PRICE_MAX"):
            self.assertIn(k, imm._CONFIG_CODE_KNOBS)

    def test_breaker_and_one_family_loss_budget(self):
        self.assertTrue(imm.move_breaker_on("KXLOWTEWR"))
        # off since 2026-10-25 (Jack: "remove the $100 cap on temps")
        self.assertEqual(imm.LOWT_DAILY_LOSS_LIMIT, 0.0)
        self.assertIsNone(imm.pilot_budget_key(self.T))
        self.assertNotIn(imm.LOWT_HALT_KEY, imm.pilot_halt_keys())
        with mock.patch.object(imm, "LOWT_DAILY_LOSS_LIMIT", 100.0):   # $100 from 10/23
            self.assertEqual(imm.pilot_budget_key(self.T), imm.LOWT_HALT_KEY)
            self.assertEqual(imm.pilot_budget_key("KXLOWTSEA-26OCT24-T41"),
                             imm.LOWT_HALT_KEY)
            self.assertEqual(imm.pilot_halt_limit(imm.LOWT_HALT_KEY), 100.0)
            self.assertIn(imm.LOWT_HALT_KEY, imm.pilot_halt_keys())
        for k in ("LOWT_ENABLE", "LOWT_FAIR_TOL_CENTS", "LOWT_DAILY_LOSS_LIMIT"):
            self.assertIn(k, imm._CONFIG_CODE_KNOBS)


class TestHighTempFamily(unittest.TestCase):
    """Jack 2026-10-23: "Investigate building the same thing for high temp
    IMM. I know there's a separate bot quoting it, is it possible to keep it
    separate?" -> "Yes build high temp recommendation"."""

    T = "KXHIGHNY-26OCT24-B62.5"

    def setUp(self):
        self._p = mock.patch.dict(imm._hight_state, {
            "mtime": 0.0, "events": {},
            "series": {"KXHIGHNY", "KXHIGHTATL", "KXHIGHTLV"}})
        self._p.start()

    def tearDown(self):
        self._p.stop()

    def test_the_family_lifts_the_high_bots_block_for_its_markets_only(self):
        prev = imm.ALLOWLIST_ONLY
        try:
            imm.ALLOWLIST_ONLY = True
            self.assertIn("KXHIGH", imm.SERIES_BLOCKLIST_PREFIXES)    # the high bot's
            self.assertTrue(imm.hight_series("KXHIGHTATL"))
            self.assertFalse(IncentiveMarketMaker._blocked(self.T))
            self.assertTrue(IncentiveMarketMaker._allowed(self.T))
            # every other blocklist prefix still blocks, and so does the high
            # bot's prefix on a KXHIGH series the fair writer did not model
            self.assertTrue(IncentiveMarketMaker._blocked("KXETHMAXMON-ETH-26OCT31-5000"))
            self.assertTrue(IncentiveMarketMaker._blocked("KXHIGHCC-26OCT07-T1"))
            self.assertTrue(IncentiveMarketMaker._blocked("KXHIGH-26SEP11-NYC"))
            self.assertFalse(imm.hight_series("KXHIGHCC"))
            with mock.patch.object(imm, "HIGHT_ENABLE", False):
                self.assertTrue(IncentiveMarketMaker._blocked(self.T))
                self.assertFalse(IncentiveMarketMaker._allowed(self.T))
        finally:
            imm.ALLOWLIST_ONLY = prev

    def test_out_at_2045_et_the_evening_before(self):
        f = imm.apply_series_cutoff_adjustments
        self.assertEqual(f("KXHIGHNY", "KXHIGHNY-26OCT24", None),
                         utc(2026, 10, 24, 0, 45))                   # 20:45 EDT Oct 23
        self.assertEqual(f("KXHIGHTLV", "KXHIGHTLV-26NOV02", None),
                         utc(2026, 11, 2, 1, 45))                    # 20:45 EST Nov 1
        # the earlier of the two
        self.assertEqual(f("KXHIGHNY", "KXHIGHNY-26OCT24", utc(2026, 10, 23, 20, 0)),
                         utc(2026, 10, 23, 20, 0))
        self.assertEqual(f("KXHIGHNY", "KXHIGHNY-X", None), imm.RELEASE_GUARD_UNKNOWN)
        with mock.patch.object(imm, "HIGHT_ENABLE", False):
            self.assertIsNone(f("KXHIGHNY", "KXHIGHNY-26OCT24", None))

    def test_gate_reads_the_high_temp_file(self):
        now = time.time()
        g = imm.hight_gate
        self.assertEqual(g(self.T, now, 30, 34)[1]["reason"], "no_read")
        imm._hight_state["events"]["KXHIGHNY-26OCT24"] = {
            "ts": now - 60, "mu": 62.2, "b": 2.25, "skip": None,
            "markets": {self.T: 0.33}}
        self.assertEqual(g(self.T, now, 30, 34), ("", dict(fair=33.0, mu=62.2, b=2.25, nws=None,
                                                          wu=None, tol=imm.HIGHT_FAIR_TOL_CENTS)))
        self.assertEqual(imm.HIGHT_FAIR_TOL_CENTS, 40)
        self.assertEqual(g(self.T, now, 73, 76)[0], "")              # bid at fair + 40
        self.assertEqual(g(self.T, now, 74, 76)[1]["reason"], "band")
        with tempfile.TemporaryDirectory() as d:
            path = os.path.join(d, "hight_fair.json")
            with open(path, "w", encoding="utf-8") as fh:
                json.dump({"events": {"KXHIGHNY-26OCT25": {
                    "fetched_at": "2026-10-24T15:00:00+00:00", "markets": {}}}}, fh)
            # (a file with a series map: only CLI-modelled series join)
            with open(path + "2", "w", encoding="utf-8") as fh:
                json.dump({"events": {}, "series": {"KXHIGHNY": "CLINYC",
                                                    "KXHIGHTEGLL": None}}, fh)
            with mock.patch.object(imm, "HIGHT_FAIR_FILE", path + "2"):
                imm.load_hight_fair()
                self.assertEqual(imm._hight_state["series"], {"KXHIGHNY"})
                imm._hight_state["mtime"] = 0.0
            with mock.patch.object(imm, "HIGHT_FAIR_FILE", path):
                self.assertEqual(imm.load_hight_fair(), 1)
        self.assertEqual(list(imm._hight_state["events"]), ["KXHIGHNY-26OCT25"])
        self.assertEqual(imm._hight_state["series"], set())          # the file had no map

    def test_family_override_budget_breaker_knobs(self):
        saved = imm.SERIES_OVERRIDES.pop("KXHIGHTATL", None)
        try:
            imm.ensure_family_override("KXHIGHTATL")
            ov = imm.series_override("KXHIGHTATL")
            # Jack 2026-10-23: "3x and 3-97"
            self.assertEqual((ov.size_mult, ov.price_min_cents, ov.price_max_cents),
                             (5.0, 3, 97))
            self.assertEqual(imm.member_price_band("KXHIGHTATL", False), (3, 97))
            self.assertIsNone(imm.size_test_arm("KXHIGHTATL"))          # out of the size test
            self.assertEqual(imm.applied_mention_mult("KXHIGHTATL"), 5.0)
        finally:
            imm.SERIES_OVERRIDES.pop("KXHIGHTATL", None)
            if saved is not None:
                imm.SERIES_OVERRIDES["KXHIGHTATL"] = saved
        self.assertTrue(imm.move_breaker_on("KXHIGHTATL"))
        # the family loss budget: off since 2026-10-25, as the low family's
        self.assertEqual(imm.HIGHT_DAILY_LOSS_LIMIT, 0.0)
        self.assertIsNone(imm.pilot_budget_key(self.T))
        self.assertNotIn(imm.HIGHT_HALT_KEY, imm.pilot_halt_keys())
        with mock.patch.object(imm, "HIGHT_DAILY_LOSS_LIMIT", 100.0):
            self.assertEqual(imm.pilot_budget_key(self.T), imm.HIGHT_HALT_KEY)
            self.assertEqual(imm.pilot_halt_limit(imm.HIGHT_HALT_KEY), 100.0)
            self.assertIn(imm.HIGHT_HALT_KEY, imm.pilot_halt_keys())
        for k in ("HIGHT_ENABLE", "HIGHT_STOP_BEFORE_MIN", "HIGHT_FAIR_TOL_CENTS",
                  "HIGHT_DAILY_LOSS_LIMIT", "HIGHT_SIZE_MULT"):
            self.assertIn(k, imm._CONFIG_CODE_KNOBS)


class TestOpportunisticAsTestGas(unittest.TestCase):
    """Jack 2026-10-25: "Build Opportunistic test of adversely selectable
    markets, but where the rewards are high enough + risk controls to where
    it could be profitable" -> 2026-10-26: "Run a smaller test first, not 51
    markets that are correlated": five AAA gas states, ASTEST_GAS_STATES.
    Fixture event on the first of them, 68DEC05 (far from any cutoff)."""

    ST = imm.ASTEST_GAS_STATES[0]
    ST2 = imm.ASTEST_GAS_STATES[1]
    OUT = next(x for x in ("TX", "CA", "FL", "OH", "IL", "GA")
               if x not in imm.ASTEST_GAS_STATES)
    T = f"KXAAAGASD{ST}-68DEC05-3.7000"
    EV = f"KXAAAGASD{ST}-68DEC05"
    CLOSE = datetime(2068, 12, 6, 3, 59, tzinfo=timezone.utc)

    def setUp(self):
        _clean_persist()
        for p in (mock.patch.dict(imm._astest_stop, {"checked": 0.0, "stopped": False}),
                  mock.patch.dict(imm.SERIES_OVERRIDES)):
            p.start()
            self.addCleanup(p.stop)
        for s in (self.ST, self.ST2, self.OUT):
            imm.SERIES_OVERRIDES.pop(f"KXAAAGASD{s}", None)
        stop = os.path.join(imm.STATUS_DIR, imm.ASTEST_STOP_FILE)
        self.addCleanup(lambda: os.path.exists(stop) and os.remove(stop))

    def test_five_states_and_only_they_lift_the_state_block(self):
        self.assertEqual(len(imm.ASTEST_GAS_STATES), 5)
        self.assertEqual(imm.ASTEST_GAS_SERIES,
                         {f"KXAAAGASD{x}" for x in imm.ASTEST_GAS_STATES})
        prev = imm.ALLOWLIST_ONLY
        try:
            imm.ALLOWLIST_ONLY = True
            for x in imm.ASTEST_GAS_STATES:
                t = f"KXAAAGASD{x}-68DEC05-3.7000"
                self.assertTrue(imm.astest_gas_series(imm.series_of(t)), t)
                self.assertFalse(IncentiveMarketMaker._blocked(t), t)
                self.assertTrue(IncentiveMarketMaker._allowed(t), t)
            # the national, the other states, a longer suffix, the diesel
            # daily and the gas monthly stay out
            for t in ("KXAAAGASD-68DEC05-3.1000", f"KXAAAGASD{self.OUT}-68DEC05-3.7",
                      "KXAAAGASDTXX-68DEC05-3.7", "KXDIESELD-68DEC05-3.7",
                      "KXAAAGASM-68DEC31-3.1"):
                self.assertFalse(imm.astest_gas_series(imm.series_of(t)), t)
                self.assertTrue(IncentiveMarketMaker._blocked(t), t)
            # the kill switch: blocked exactly as before
            with mock.patch.object(imm, "ASTEST_ENABLE", False):
                self.assertTrue(IncentiveMarketMaker._blocked(self.T))
                self.assertFalse(imm.astest_gas_member(f"KXAAAGASD{self.ST}"))
            # the stop file, read once a minute, blocks them too -- but a
            # member stays a member (its clone keeps the test's stops)
            with open(os.path.join(imm.STATUS_DIR, imm.ASTEST_STOP_FILE), "w") as fh:
                fh.write("stop")
            self.assertFalse(IncentiveMarketMaker._blocked(self.T))     # cached
            imm._astest_stop["checked"] = 0.0
            self.assertTrue(imm.astest_stopped())
            self.assertTrue(IncentiveMarketMaker._blocked(self.T))
            self.assertIsNone(imm.pilot_budget_key(self.T))
            self.assertTrue(imm.astest_gas_member(f"KXAAAGASD{self.ST}"))
        finally:
            imm.ALLOWLIST_ONLY = prev

    def test_window_cap_x1_and_out_of_the_size_test(self):
        self.assertEqual(imm.astest_blackout(("16:00", "24:00")), ("00:00", "16:00"))
        self.assertEqual(imm.astest_blackout(("10:00", "22:00")), ("22:00", "10:00"))
        self.assertEqual(imm.ASTEST_GAS_WINDOW_ET, ("16:00", "24:00"))
        self.assertEqual(imm.ASTEST_GAS_MAX_POSITION, 50.0)
        member, out = f"KXAAAGASD{self.ST}", f"KXAAAGASD{self.OUT}"
        # the national's override is untouched (the trial's window); a
        # member's clone carries the test's window and cap, and still drops
        # the national's rate floor like every state
        nat = imm.SERIES_OVERRIDES["KXAAAGASD"]
        self.assertEqual(nat.blackout_et, ("00:00", "13:00"))
        imm.ensure_family_override(member)
        imm.ensure_family_override(out)
        st = imm.SERIES_OVERRIDES[member]
        self.assertEqual((st.blackout_et, st.max_position), (("00:00", "16:00"), 50.0))
        self.assertEqual(st.min_est_per_day, imm.GB_STATE_MIN_RATE)
        o = imm.SERIES_OVERRIDES[out]
        self.assertEqual((o.blackout_et, o.max_position), (nat.blackout_et, nat.max_position))
        # (EDT: ET = UTC-4)
        for now, shut in ((utc(2026, 10, 27, 12, 0), True),            # 08:00 ET
                          (utc(2026, 10, 27, 19, 59), True),           # 15:59 ET
                          (utc(2026, 10, 27, 20, 0), False),           # 16:00 ET
                          (utc(2026, 10, 28, 3, 59), False)):          # 23:59 ET
            self.assertEqual(imm.series_in_blackout(member, now), shut, now)
        # x1 in the window: the 4pm-1am gas halving is lifted for the
        # members only (the other states and the diesel daily keep it)
        evening = utc(2026, 10, 27, 21, 0)                              # 17:00 ET
        with mock.patch.object(imm, "SERIES_HOUR_MULTS",
                               imm._parse_series_hour_mults("KXDIESELD:16-1:0.5,KXAAAGASD:16-1:0.5")):
            self.assertEqual(imm.hour_size_mult(member, evening), 1.0)
            self.assertEqual(imm.hour_size_mult(out, evening), 0.5)
            self.assertEqual(imm.hour_size_mult("KXDIESELD", evening), 0.5)
            with mock.patch.object(imm, "ASTEST_ENABLE", False):
                self.assertEqual(imm.hour_size_mult(member, evening), 0.5)
        # a hand cap: literal, and out of both halves of the base-size test
        self.assertEqual(imm.applied_mention_mult(member), 1.0)
        self.assertIsNone(imm.size_test_arm(member))

    def test_family_loss_budget(self):
        self.assertEqual(imm.ASTEST_GAS_DAILY_LOSS, 100.0)
        self.assertEqual(imm.pilot_budget_key(self.T), imm.ASTEST_GAS_HALT_KEY)
        self.assertEqual(imm.pilot_halt_limit(imm.ASTEST_GAS_HALT_KEY), 100.0)
        self.assertIn(imm.ASTEST_GAS_HALT_KEY, imm.pilot_halt_keys())
        for t in ("KXAAAGASD-68DEC05-3.1000", f"KXAAAGASD{self.OUT}-68DEC05-3.7"):
            self.assertIsNone(imm.pilot_budget_key(t), t)
        with mock.patch.object(imm, "ASTEST_GAS_DAILY_LOSS", 0.0):
            self.assertIsNone(imm.pilot_budget_key(self.T))
            self.assertNotIn(imm.ASTEST_GAS_HALT_KEY, imm.pilot_halt_keys())
        for k in ("ASTEST_ENABLE", "ASTEST_GAS_STATES", "ASTEST_GAS_WINDOW_ET",
                  "ASTEST_GAS_MAX_POSITION", "ASTEST_GAS_DAILY_LOSS",
                  "ASTEST_GAS_FILL_PAUSE_MIN"):
            self.assertIn(k, imm._CONFIG_CODE_KNOBS)

    def _bot(self):
        client = FakeClient()
        client.programs.append(
            {"market_ticker": self.T, "incentive_type": "liquidity",
             "period_reward": 7000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": client.programs[0]["start_date"],
             "end_date": client.programs[0]["end_date"]})
        client.markets[self.T] = {
            "ticker": self.T, "event_ticker": self.EV, "status": "active",
            "close_time": self.CLOSE.strftime("%Y-%m-%dT%H:%M:%SZ"),
            "yes_bid_dollars": "0.4900", "yes_ask_dollars": "0.5100",
            "volume_fp": "500.00"}
        lv = [["0.45", "400"], ["0.46", "400"], ["0.47", "400"],
              ["0.48", "400"], ["0.49", "300"]]
        client.books[self.T] = {"orderbook_fp": {"yes_dollars": lv,
                                                 "no_dollars": lv}}
        return IncentiveMarketMaker(client=client, live=False)

    def _quotes(self, bot):
        return sorted((o["book_side"], o["yes_price"])
                      for o in bot.state.sim_orders.values()
                      if o["ticker"] == self.T)

    def test_quoted_plain_in_the_window_and_a_fill_pauses_the_event(self):
        # inside the window (the clock is the test's), with no GasBuddy read:
        # the members skip the gate that would stand a state daily aside
        self.assertTrue(imm.gb_fair_series(f"KXAAAGASD{self.ST}"))
        with mock.patch.object(imm, "series_in_blackout", lambda s, n: False):
            bot = self._bot()
            bot.run_cycle()
            self.assertNotEqual(self._quotes(bot), [])
            self.assertNotIn(self.T, bot._guard_now)
            # our maker fill stands the whole event aside the pause
            now = time.time()
            self.assertEqual(imm.ASTEST_GAS_FILL_PAUSE_MIN, 15.0)
            bot._sweep_note_fill({"order_id": "o-ws", "market_ticker": self.T,
                                  "count_fp": "3.00", "ts_ms": int(now * 1000),
                                  "is_taker": False}, now)
            self.assertAlmostEqual(bot.state.astest_fill_pause_until[self.EV],
                                   now + 900, delta=1)
            bot.run_cycle()
            self.assertEqual(self._quotes(bot), [])
            self.assertEqual(bot._guard_now[self.T]["guard"], "astest_fill_pause")
            # it survives a restart
            bot._save_persist()
            bot2 = IncentiveMarketMaker(client=bot.client, live=False)
            self.assertAlmostEqual(bot2.state.astest_fill_pause_until[self.EV],
                                   now + 900, delta=1)
            # over: quoting resumes
            bot.state.astest_fill_pause_until[self.EV] = now - 1
            bot.run_cycle()
            self.assertNotEqual(self._quotes(bot), [])
        # outside the window the blackout holds it
        with mock.patch.object(imm, "series_in_blackout", lambda s, n: True):
            bot.run_cycle()
            self.assertEqual(self._quotes(bot), [])

    def test_only_our_maker_fills_start_the_pause(self):
        bot = self._bot()
        now = time.time()
        # a taker fill and a non-member's fill start nothing
        bot._sweep_note_fill({"order_id": "o-1", "market_ticker": self.T,
                              "count_fp": "3.00", "ts_ms": int(now * 1000),
                              "is_taker": True}, now)
        bot._astest_fill_pause_note(f"KXAAAGASD{self.OUT}-68DEC05-3.7", now, "fill")
        self.assertEqual(bot.state.astest_fill_pause_until, {})
        # the cycle's read: a later fill extends, an older one never shortens
        bot._astest_fill_pause_note(self.T, now, "fill")
        bot._astest_fill_pause_note(self.T, now + 60, "fill")
        bot._astest_fill_pause_note(self.T, now - 600, "fill")
        self.assertAlmostEqual(bot.state.astest_fill_pause_until[self.EV],
                               now + 60 + 900, delta=1)
        bot.state.astest_fill_pause_until.clear()
        with mock.patch.object(imm, "ASTEST_GAS_FILL_PAUSE_MIN", 0.0):
            bot._astest_fill_pause_note(self.T, now, "fill")
        self.assertEqual(bot.state.astest_fill_pause_until, {})

    def test_event_cap_and_the_family_burst_breaker(self):
        # the states move together on the national price: one sweep can hit
        # every member at once, so our fills across the family are budgeted
        self.assertEqual(imm.event_cap_contracts(self.EV), 150.0)
        self.assertEqual(imm.ASTEST_GAS_BURST_CONTRACTS, 100.0)
        other = f"KXAAAGASD{self.ST2}-68DEC05-4.5000"
        bot = self._bot()
        now = time.time()
        fam = imm.ASTEST_GAS_FAMILY_KEY
        with mock.patch.object(bot.alerter, "alert") as al:
            bot._astest_fill_pause_note(self.T, now - 1000, "fill", count=250)   # outside 15m
            bot._astest_fill_pause_note(self.T, now, "fill", count=60)
            # the WS note carries no count: never counted twice
            bot._astest_fill_pause_note(other, now, "WS fill")
            self.assertNotIn(fam, bot.state.astest_fill_pause_until)
            al.assert_not_called()
            # another member's fill takes the family to the bar
            bot._astest_fill_pause_note(other, now, "fill", count=40)
            self.assertAlmostEqual(bot.state.astest_fill_pause_until[fam], now + 1800, delta=2)
            al.assert_called_once()
            self.assertEqual(al.call_args[0][0], "astest_burst")
        # every member's event stands aside, this one included
        with mock.patch.object(imm, "series_in_blackout", lambda s, n: False):
            bot.state.astest_fill_pause_until.pop(self.EV, None)
            bot.run_cycle()
            self.assertEqual(self._quotes(bot), [])
            self.assertEqual(bot._guard_now[self.T]["guard"], "astest_fill_pause")
            self.assertTrue(bot._guard_now[self.T]["inputs"]["family"])
        with mock.patch.object(imm, "ASTEST_GAS_BURST_CONTRACTS", 0.0):
            bot.state.astest_fill_pause_until.clear()
            bot._astest_fill_pause_note(self.T, now, "fill", count=10_000)
            self.assertNotIn(fam, bot.state.astest_fill_pause_until)
        for k in ("ASTEST_GAS_EVENT_CAP", "ASTEST_GAS_BURST_CONTRACTS",
                  "ASTEST_GAS_BURST_WINDOW_MIN", "ASTEST_GAS_BURST_PAUSE_MIN"):
            self.assertIn(k, imm._CONFIG_CODE_KNOBS)


class TestOpportunisticAsTestBillboardVoteHub(unittest.TestCase):
    """Jack 2026-10-27: "build billboard and votehub" -- the AS test's second
    and third families, KXBBSINGLE and KXVHGCB, on the gas family's stops with
    a stop file and budgets each. Fixture events far from any cutoff: the
    Billboard chart dated 2068-12-05 (its tracking week ends 2068-11-27), the
    VoteHub read of 2068-12-05."""

    BB = "KXBBSINGLE-68DEC05ALL-1T2"
    BB_EV = "KXBBSINGLE-68DEC05ALL"
    VH = "KXVHGCB-68DEC05-E8.4"
    VH_EV = "KXVHGCB-68DEC05"
    GAS = f"KXAAAGASD{imm.ASTEST_GAS_STATES[0]}-68DEC05-3.7000"

    def setUp(self):
        _clean_persist()
        for p in (mock.patch.dict(imm._astest_stop, {"checked": 0.0, "stopped": False}),
                  mock.patch.dict(imm._astest_family_stop["BB"], {"checked": 0.0, "stopped": False}),
                  mock.patch.dict(imm._astest_family_stop["VH"], {"checked": 0.0, "stopped": False}),
                  mock.patch.object(imm, "ALLOWLIST_ONLY", True)):
            p.start()
            self.addCleanup(p.stop)
        for f in (imm.ASTEST_STOP_FILE, imm.ASTEST_BB_STOP_FILE, imm.ASTEST_VH_STOP_FILE):
            stop = os.path.join(imm.STATUS_DIR, f)
            self.addCleanup(lambda s=stop: os.path.exists(s) and os.remove(s))

    def _stop(self, fname):
        with open(os.path.join(imm.STATUS_DIR, fname), "w") as fh:
            fh.write("stop")
        for st in (imm._astest_stop, imm._astest_family_stop["BB"],
                   imm._astest_family_stop["VH"]):
            st["checked"] = 0.0

    def test_admitted_while_live_and_each_family_stops_alone(self):
        self.assertEqual(imm.ASTEST_FAMILIES, ("BB", "VH", "PICK"))
        self.assertEqual(imm.ASTEST_BB_SERIES, {"KXBBSINGLE"})
        self.assertEqual(imm.ASTEST_VH_SERIES, {"KXVHGCB"})
        self.assertEqual(imm.astest_family("KXBBSINGLE"), "BB")
        self.assertEqual(imm.astest_family("KXVHGCB"), "VH")
        self.assertEqual(imm.astest_family(imm.series_of(self.GAS)), "GAS")
        for t in (self.BB, self.VH):
            self.assertTrue(IncentiveMarketMaker._allowed(t), t)
        # a look-alike stays out
        for t in ("KXBBSINGLES-68DEC05ALL-1T2", "KXVHGCBX-68DEC05-E8.4",
                  "KXGENERICBALLOTVOTEHUBX-68DEC05-T8.4"):
            self.assertIsNone(imm.astest_family(imm.series_of(t)), t)
            self.assertFalse(IncentiveMarketMaker._allowed(t), t)
        # the gas family's stop file stops gas only
        self._stop(imm.ASTEST_STOP_FILE)
        self.assertIsNone(imm.astest_family(imm.series_of(self.GAS)))
        self.assertTrue(IncentiveMarketMaker._allowed(self.BB))
        self.assertTrue(IncentiveMarketMaker._allowed(self.VH))
        # Billboard's stops Billboard only -- its member stays a member
        self._stop(imm.ASTEST_BB_STOP_FILE)
        self.assertIsNone(imm.astest_family("KXBBSINGLE"))
        self.assertEqual(imm.astest_member_family("KXBBSINGLE"), "BB")
        self.assertFalse(IncentiveMarketMaker._allowed(self.BB))
        self.assertTrue(IncentiveMarketMaker._allowed(self.VH))
        self.assertIsNone(imm.pilot_budget_key(self.BB))
        self._stop(imm.ASTEST_VH_STOP_FILE)
        self.assertFalse(IncentiveMarketMaker._allowed(self.VH))
        # the kill switches: all AS test families, or one
        for f in (imm.ASTEST_BB_STOP_FILE, imm.ASTEST_VH_STOP_FILE):
            os.remove(os.path.join(imm.STATUS_DIR, f))
        for st in (imm._astest_family_stop["BB"], imm._astest_family_stop["VH"]):
            st["checked"] = 0.0
        with mock.patch.object(imm, "ASTEST_ENABLE", False):
            self.assertFalse(IncentiveMarketMaker._allowed(self.BB))
            self.assertFalse(IncentiveMarketMaker._allowed(self.VH))
            self.assertNotIn(imm.ASTEST_BB_HALT_KEY, imm.pilot_halt_keys())
        with mock.patch.object(imm, "ASTEST_BB_ENABLE", False):
            self.assertFalse(IncentiveMarketMaker._allowed(self.BB))
            self.assertTrue(IncentiveMarketMaker._allowed(self.VH))
            self.assertNotIn(imm.ASTEST_BB_HALT_KEY, imm.pilot_halt_keys())
            self.assertIn(imm.ASTEST_VH_HALT_KEY, imm.pilot_halt_keys())

    def test_x3_literal_sizes_at_every_hour_and_out_of_the_size_test(self):
        # x3 of the gas family's sizes, literal: rungs, caps and burst bar
        saturday_night = utc(2068, 12, 1, 7, 0)              # Sat 02:00 ET
        self.assertEqual(saturday_night.astimezone(imm.ET).weekday(), 5)
        for fam, s, ev in (("BB", "KXBBSINGLE", self.BB_EV), ("VH", "KXVHGCB", self.VH_EV)):
            self.assertEqual(imm.astest_knob(fam, "SIZE_MULT"), 3.0)
            self.assertEqual(imm.series_levels(s), imm.scale_levels(imm.LEVELS, 3.0), s)
            self.assertEqual(imm.series_max_position(s), 150.0, s)
            self.assertEqual(imm.event_cap_contracts(ev), 450.0, s)
            self.assertEqual(imm.astest_knob(fam, "BURST_CONTRACTS"), 300.0)
            self.assertEqual(imm.astest_knob(fam, "DAILY_LOSS"), 100.0)
            # x1 by the clock: no quiet-hours, evening, Saturday or yield size
            self.assertTrue(imm.is_daily_series(s), s)
            self.assertEqual(imm.hour_size_mult(s, saturday_night), 1.0, s)
            self.assertFalse(imm.yield_size_eligible(s), s)
            self.assertEqual(imm.applied_mention_mult(s), 1.0, s)
            self.assertIsNone(imm.size_test_arm(s), s)
        # at x1 the global ladder itself
        with mock.patch.object(imm, "ASTEST_BB_SIZE_MULT", 1.0):
            self.assertIsNone(imm._astest_levels("BB"))
        # stopped, the family's event cap goes (the hand sizes stay code)
        self._stop(imm.ASTEST_BB_STOP_FILE)
        self.assertNotEqual(imm.event_cap_contracts(self.BB_EV), 450.0)

    def test_votehub_quotes_overnight_only_and_leaves_at_5am_on_the_read_day(self):
        self.assertEqual(imm.ASTEST_VH_WINDOW_ET, ("20:00", "05:00"))
        ov = imm.SERIES_OVERRIDES["KXVHGCB"]
        self.assertEqual(ov.blackout_et, ("05:00", "20:00"))
        self.assertEqual(ov.event_day_cutoff_et, (5, 0))
        # (EDT: ET = UTC-4)
        for now, shut in ((utc(2026, 10, 27, 14, 1), True),            # 10:01 ET listing
                          (utc(2026, 10, 27, 23, 59), True),           # 19:59 ET
                          (utc(2026, 10, 28, 0, 0), False),            # 20:00 ET
                          (utc(2026, 10, 28, 8, 59), False),           # 04:59 ET
                          (utc(2026, 10, 28, 9, 0), True)):            # 05:00 ET
            self.assertEqual(imm.series_in_blackout("KXVHGCB", now), shut, now)
        # each event: out at 05:00 ET on its read day (the 17:05 ET read is
        # Kalshi's occurrence one minute after its close: no earlier candidate)
        ev = "KXVHGCB-26OCT28"
        occ, exp = utc(2026, 10, 28, 21, 4), utc(2026, 10, 28, 21, 5)
        cut = imm.apply_series_cutoff_adjustments(
            "KXVHGCB", ev, trade_cutoff_utc(ev, occ, exp), occ)
        self.assertEqual(cut, utc(2026, 10, 28, 9, 0))
        # Billboard has no window: every hour to its cutoff
        self.assertFalse(imm.series_in_blackout("KXBBSINGLE", utc(2026, 10, 27, 16, 0)))

    def test_billboard_out_when_the_tracking_week_ends(self):
        # chart dated Sat Nov 7 2026: tracking week Fri Oct 23 - Thu Oct 29,
        # out 8 days before the chart date's midnight (05:00Z Nov 7, EST) =
        # 05:00Z Fri Oct 30 (01:00 EDT -- the DST change adds the hour)
        self.assertEqual(imm.ASTEST_BB_CUTOFF_DAYS, 8.0)
        self.assertEqual(imm.SERIES_OVERRIDES["KXBBSINGLE"].cutoff_before_event_min, 8 * 1440)
        ev = "KXBBSINGLE-26NOV07HOU"
        close = utc(2026, 11, 2, 15, 0)
        base = trade_cutoff_utc(ev, None, close)
        cut = imm.apply_series_cutoff_adjustments("KXBBSINGLE", ev, base, close)
        self.assertEqual(cut, utc(2026, 10, 30, 5, 0))
        # a December chart: out Nov 27 -- after its program ends anyway
        ev2 = "KXBBSINGLE-26DEC05ALL"
        close2 = utc(2026, 11, 30, 15, 0)
        cut2 = imm.apply_series_cutoff_adjustments(
            "KXBBSINGLE", ev2, trade_cutoff_utc(ev2, None, close2), close2)
        self.assertEqual(cut2, utc(2026, 11, 27, 5, 0))

    def test_family_loss_budgets(self):
        self.assertEqual(imm.pilot_budget_key(self.BB), imm.ASTEST_BB_HALT_KEY)
        self.assertEqual(imm.pilot_budget_key(self.VH), imm.ASTEST_VH_HALT_KEY)
        self.assertEqual(imm.pilot_budget_key(self.GAS), imm.ASTEST_GAS_HALT_KEY)
        for k in (imm.ASTEST_BB_HALT_KEY, imm.ASTEST_VH_HALT_KEY):
            self.assertEqual(imm.pilot_halt_limit(k), 100.0)
            self.assertIn(k, imm.pilot_halt_keys())
        with mock.patch.object(imm, "ASTEST_VH_DAILY_LOSS", 0.0):
            self.assertIsNone(imm.pilot_budget_key(self.VH))
            self.assertNotIn(imm.ASTEST_VH_HALT_KEY, imm.pilot_halt_keys())
            self.assertEqual(imm.pilot_budget_key(self.BB), imm.ASTEST_BB_HALT_KEY)
        for k in ("ASTEST_BB_ENABLE", "ASTEST_BB_CUTOFF_DAYS", "ASTEST_BB_SIZE_MULT",
                  "ASTEST_BB_MAX_POSITION", "ASTEST_BB_DAILY_LOSS", "ASTEST_VH_ENABLE",
                  "ASTEST_VH_WINDOW_ET", "ASTEST_VH_SIZE_MULT", "ASTEST_VH_MAX_POSITION",
                  "ASTEST_VH_DAILY_LOSS", "ASTEST_VH_BURST_CONTRACTS"):
            self.assertIn(k, imm._CONFIG_CODE_KNOBS)

    def _bot(self, ticker, event, close):
        client = FakeClient()
        client.programs.append(
            {"market_ticker": ticker, "incentive_type": "liquidity",
             "period_reward": 7000000, "target_size_fp": "1000.00",
             "discount_factor_bps": 5000, "paid_out": False,
             "start_date": client.programs[0]["start_date"],
             "end_date": client.programs[0]["end_date"]})
        client.markets[ticker] = {
            "ticker": ticker, "event_ticker": event, "status": "active",
            "close_time": close.strftime("%Y-%m-%dT%H:%M:%SZ"),
            "yes_bid_dollars": "0.4900", "yes_ask_dollars": "0.5100",
            "volume_fp": "500.00"}
        lv = [["0.45", "400"], ["0.46", "400"], ["0.47", "400"],
              ["0.48", "400"], ["0.49", "300"]]
        client.books[ticker] = {"orderbook_fp": {"yes_dollars": lv, "no_dollars": lv}}
        return IncentiveMarketMaker(client=client, live=False)

    @staticmethod
    def _quotes(bot, ticker):
        return sorted((o["book_side"], o["yes_price"])
                      for o in bot.state.sim_orders.values() if o["ticker"] == ticker)

    def test_quoted_and_a_fill_pauses_the_event(self):
        # (inside VoteHub's window: the clock is the test's)
        for t, ev, close in ((self.BB, self.BB_EV, utc(2068, 11, 30, 15, 0)),
                             (self.VH, self.VH_EV, utc(2068, 12, 5, 22, 4))):
            p = mock.patch.object(imm, "series_in_blackout", lambda s, n: False)
            p.start()
            self.addCleanup(p.stop)
            bot = self._bot(t, ev, close)
            bot.run_cycle()
            self.assertNotEqual(self._quotes(bot, t), [], t)
            now = time.time()
            bot._sweep_note_fill({"order_id": "o-ws", "market_ticker": t,
                                  "count_fp": "3.00", "ts_ms": int(now * 1000),
                                  "is_taker": False}, now)
            self.assertAlmostEqual(bot.state.astest_fill_pause_until[ev], now + 900, delta=1)
            bot.run_cycle()
            self.assertEqual(self._quotes(bot, t), [], t)
            self.assertEqual(bot._guard_now[t]["guard"], "astest_fill_pause")
            bot.state.astest_fill_pause_until[ev] = now - 1
            bot.run_cycle()
            self.assertNotEqual(self._quotes(bot, t), [], t)

    def test_burst_breakers_count_each_family_alone(self):
        bot = self._bot(self.BB, self.BB_EV, utc(2068, 11, 30, 15, 0))
        now = time.time()
        pauses = bot.state.astest_fill_pause_until
        other_bb = "KXBBSINGLE-68DEC12ALL-1T2"
        bar = imm.ASTEST_BB_BURST_CONTRACTS
        with mock.patch.object(bot.alerter, "alert") as al:
            # just under each bar on gas and VoteHub: neither family trips,
            # and neither counts toward Billboard's
            bot._astest_fill_pause_note(self.GAS, now, "fill",
                                        count=imm.ASTEST_GAS_BURST_CONTRACTS - 1)
            bot._astest_fill_pause_note(self.VH, now, "fill",
                                        count=imm.ASTEST_VH_BURST_CONTRACTS - 1)
            bot._astest_fill_pause_note(self.BB, now, "fill", count=bar - 40)
            for k in ("*GAS", "*VH", "*BB"):
                self.assertNotIn(k, pauses)
            al.assert_not_called()
            # another Billboard event takes Billboard to its bar
            bot._astest_fill_pause_note(other_bb, now, "fill", count=40)
            self.assertAlmostEqual(pauses["*BB"], now + 1800, delta=2)
            self.assertNotIn("*GAS", pauses)
            self.assertNotIn("*VH", pauses)
            al.assert_called_once()
            self.assertEqual(al.call_args[0][0], "astest_burst")
            self.assertEqual(al.call_args[1]["key"], "astest_burst:BB")
            self.assertIn("Billboard", al.call_args[0][1])
        # every Billboard event stands aside, this one included
        pauses.pop(self.BB_EV, None)
        bot.run_cycle()
        self.assertEqual(self._quotes(bot, self.BB), [])
        self.assertEqual(bot._guard_now[self.BB]["guard"], "astest_fill_pause")
        self.assertTrue(bot._guard_now[self.BB]["inputs"]["family"])


class TestOpportunisticAsTestDailyPicks(unittest.TestCase):
    """Jack 2026-10-27: "Turn back on opportunistic bot but now pick 5
    distinct events each day, optimizing for likelihood of profitability,
    even better if fair value can be built, quote it at 1x size, and add it
    to the opportunistic daily report email" -- the AS test's fourth family,
    the events imm_astest_picks.py writes to ASTEST_PICK_FILE. Fixture events
    far from any cutoff (2068, EST)."""

    EV = "KXPICKTEST-68DEC05"
    T = "KXPICKTEST-68DEC05-T5"
    OTHER = "KXPICKTEST-68DEC12-T5"          # the same series, not picked
    GAS_EV = "KXAAAGASDOR-68DEC05"
    GAS = "KXAAAGASDOR-68DEC05-3.7000"

    def setUp(self):
        _clean_persist()
        for p in (mock.patch.dict(imm._astest_family_stop["PICK"],
                                  {"checked": 0.0, "stopped": False}),
                  mock.patch.dict(imm.SERIES_OVERRIDES),
                  mock.patch.object(imm, "ALLOWLIST_ONLY", True),
                  mock.patch.object(imm, "ASTEST_PICK_EVENTS", {}),
                  mock.patch.object(imm, "ASTEST_PICK_SERIES", frozenset()),
                  mock.patch.dict(imm._ASTEST_PICK_PRIOR, clear=True)):
            p.start()
            self.addCleanup(p.stop)
        for s in ("KXPICKTEST", "KXAAAGASDOR"):
            imm.SERIES_OVERRIDES.pop(s, None)
        for f in (imm.ASTEST_PICK_FILE, imm.ASTEST_PICK_STOP_FILE):
            path = os.path.join(imm.STATUS_DIR, f)
            self.addCleanup(lambda s=path: os.path.exists(s) and os.remove(s))

    def _write(self, picks, age_h=0.0):
        gen = datetime.now(timezone.utc) - timedelta(hours=age_h)
        with open(os.path.join(imm.STATUS_DIR, imm.ASTEST_PICK_FILE), "w") as fh:
            json.dump({"generated_at": gen.strftime("%Y-%m-%dT%H:%M:%SZ"),
                       "picks": picks}, fh)

    def _stop(self):
        with open(os.path.join(imm.STATUS_DIR, imm.ASTEST_PICK_STOP_FILE), "w") as fh:
            fh.write("stop")
        imm._astest_family_stop["PICK"]["checked"] = 0.0

    def test_the_file_admits_each_picked_event_alone(self):
        self.assertEqual(imm.ASTEST_FAMILIES, ("BB", "VH", "PICK"))
        self.assertFalse(IncentiveMarketMaker._allowed(self.T))
        self.assertTrue(IncentiveMarketMaker._blocked(self.GAS))
        self._write([{"event": self.EV},
                     {"event": self.GAS_EV, "window_et": "16:00-24:00"}])
        self.assertEqual(imm.load_astest_picks(), 2)
        self.assertEqual(imm.ASTEST_PICK_EVENTS,
                         {"KXPICKTEST": self.EV, "KXAAAGASDOR": self.GAS_EV})
        self.assertEqual(imm.astest_family("KXPICKTEST"), "PICK")
        self.assertTrue(IncentiveMarketMaker._allowed(self.T))
        self.assertTrue(IncentiveMarketMaker._allowed(self.EV))
        # never the rest of its series
        self.assertFalse(IncentiveMarketMaker._allowed(self.OTHER))
        # the gas pick: its event alone lifts the state block, quoted plain
        self.assertFalse(IncentiveMarketMaker._blocked(self.GAS))
        self.assertTrue(IncentiveMarketMaker._allowed(self.GAS))
        self.assertTrue(imm.astest_plain_gas("KXAAAGASDOR"))
        for t in ("KXAAAGASDOR-68DEC06-3.7000", "KXAAAGASDWA-68DEC05-3.7000",
                  "KXAAAGASD-68DEC05-3.1000"):
            self.assertTrue(IncentiveMarketMaker._blocked(t), t)
        self.assertIsNone(imm.astest_family("KXPICKTESTX"))
        self.assertEqual(imm.pilot_budget_key(self.T), imm.ASTEST_PICK_HALT_KEY)
        # the stop file takes every pick back out; membership stays
        self._stop()
        self.assertIsNone(imm.astest_family("KXPICKTEST"))
        self.assertEqual(imm.astest_member_family("KXPICKTEST"), "PICK")
        self.assertFalse(IncentiveMarketMaker._allowed(self.T))
        self.assertTrue(IncentiveMarketMaker._blocked(self.GAS))
        self.assertFalse(imm.astest_plain_gas("KXAAAGASDOR"))
        self.assertIsNone(imm.pilot_budget_key(self.T))

    def test_stale_missing_refused_or_doubled_picks(self):
        self.assertEqual(imm.load_astest_picks(), 0)                     # no file
        self._write([{"event": self.EV}], age_h=imm.ASTEST_PICK_MAX_AGE_H + 1)
        self.assertEqual(imm.load_astest_picks(), 0)                     # lapsed
        self.assertFalse(IncentiveMarketMaker._allowed(self.T))
        # one event a series; a blocked, excluded or other AS family's
        # series is refused whatever the file says
        self._write([{"event": self.EV}, {"event": "KXPICKTEST-68DEC12"},
                     {"event": "KXBTCD-68DEC05"}, {"event": "KXTEMPNYCH-68DEC05"},
                     {"event": "KXBBSINGLE-68DEC05ALL"}, {"event": ""}, {"x": 1}])
        self.assertEqual(imm.load_astest_picks(), 1)
        self.assertEqual(imm.ASTEST_PICK_EVENTS, {"KXPICKTEST": self.EV})
        # an unreadable file is no picks
        with open(os.path.join(imm.STATUS_DIR, imm.ASTEST_PICK_FILE), "w") as fh:
            fh.write("{not json")
        self.assertEqual(imm.load_astest_picks(), 0)
        self.assertIsNone(imm.astest_family("KXPICKTEST"))
        # the kill switches
        self._write([{"event": self.EV}])
        with mock.patch.object(imm, "ASTEST_PICK_ENABLE", False):
            self.assertEqual(imm.load_astest_picks(), 0)
            self.assertNotIn(imm.ASTEST_PICK_HALT_KEY, imm.pilot_halt_keys())
        with mock.patch.object(imm, "ASTEST_ENABLE", False):
            self.assertEqual(imm.load_astest_picks(), 0)

    def test_x1_literal_at_every_hour_with_the_picks_caps_and_window(self):
        self._write([{"event": self.EV},
                     {"event": self.GAS_EV, "window_et": "16:00-24:00"}])
        imm.load_astest_picks()
        saturday_night = utc(2068, 12, 1, 7, 0)              # 02:00 ET
        evening = utc(2068, 12, 4, 1, 0)                     # 20:00 ET
        for s, ev in (("KXPICKTEST", self.EV), ("KXAAAGASDOR", self.GAS_EV)):
            self.assertEqual(imm.series_levels(s), imm.LEVELS, s)
            self.assertEqual(imm.series_max_position(s), 50.0, s)
            self.assertEqual(imm.event_cap_contracts(ev), 150.0, s)
            # x1 by the clock: no quiet-hours, gas-evening, Saturday or yield size
            self.assertTrue(imm.is_daily_series(s), s)
            self.assertEqual(imm.hour_size_mult(s, saturday_night), 1.0, s)
            self.assertEqual(imm.hour_size_mult(s, evening), 1.0, s)
            self.assertFalse(imm.yield_size_eligible(s), s)
            self.assertEqual(imm.applied_mention_mult(s), 1.0, s)
            self.assertIsNone(imm.size_test_arm(s), s)
        # the gas pick quotes 16:00-24:00 ET only, on the national's guards
        self.assertEqual(imm.SERIES_OVERRIDES["KXAAAGASDOR"].blackout_et, ("00:00", "16:00"))
        self.assertTrue(imm.series_in_blackout("KXAAAGASDOR", utc(2068, 12, 4, 15, 0)))
        self.assertFalse(imm.series_in_blackout("KXAAAGASDOR", utc(2068, 12, 4, 22, 0)))
        self.assertFalse(imm.series_in_blackout("KXPICKTEST", utc(2068, 12, 4, 15, 0)))
        self.assertEqual(imm.pilot_halt_limit(imm.ASTEST_PICK_HALT_KEY), 100.0)
        self.assertIn(imm.ASTEST_PICK_HALT_KEY, imm.pilot_halt_keys())
        # a pick that leaves gets its series' prior override back
        self._write([{"event": self.GAS_EV, "window_et": "16:00-24:00"}])
        imm.load_astest_picks()
        self.assertNotIn("KXPICKTEST", imm.SERIES_OVERRIDES)
        self.assertIsNone(imm.astest_family("KXPICKTEST"))
        self.assertFalse(IncentiveMarketMaker._allowed(self.T))
        for k in ("ASTEST_PICK_ENABLE", "ASTEST_PICK_MAX_AGE_H", "ASTEST_PICK_MAX_POSITION",
                  "ASTEST_PICK_EVENT_CAP", "ASTEST_PICK_DAILY_LOSS",
                  "ASTEST_PICK_BURST_CONTRACTS"):
            self.assertIn(k, imm._CONFIG_CODE_KNOBS)

    def _bot(self):
        client = FakeClient()
        close = utc(2068, 12, 5, 4, 0)
        for t, ev in ((self.T, self.EV), (self.OTHER, "KXPICKTEST-68DEC12")):
            client.programs.append(
                {"market_ticker": t, "incentive_type": "liquidity",
                 "period_reward": 7000000, "target_size_fp": "1000.00",
                 "discount_factor_bps": 5000, "paid_out": False,
                 "start_date": client.programs[0]["start_date"],
                 "end_date": client.programs[0]["end_date"]})
            client.markets[t] = {
                "ticker": t, "event_ticker": ev, "status": "active",
                "close_time": close.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "yes_bid_dollars": "0.4900", "yes_ask_dollars": "0.5100",
                "volume_fp": "500.00"}
            lv = [["0.45", "400"], ["0.46", "400"], ["0.47", "400"],
                  ["0.48", "400"], ["0.49", "300"]]
            client.books[t] = {"orderbook_fp": {"yes_dollars": lv, "no_dollars": lv}}
        return IncentiveMarketMaker(client=client, live=False)

    @staticmethod
    def _quotes(bot, ticker):
        return sorted((o["book_side"], o["yes_price"])
                      for o in bot.state.sim_orders.values() if o["ticker"] == ticker)

    def test_a_pick_is_quoted_at_x1_and_a_fill_pauses_its_event(self):
        self._write([{"event": self.EV}])
        bot = self._bot()
        bot.run_cycle()
        q = [o for o in bot.state.sim_orders.values() if o["ticker"] == self.T]
        self.assertNotEqual(q, [])
        self.assertEqual(self._quotes(bot, self.OTHER), [])          # not picked
        self.assertTrue(all(o["remaining_count"] <= imm.ASTEST_PICK_MAX_POSITION for o in q), q)
        now = time.time()
        bot._sweep_note_fill({"order_id": "o-ws", "market_ticker": self.T,
                              "count_fp": "3.00", "ts_ms": int(now * 1000),
                              "is_taker": False}, now)
        self.assertAlmostEqual(bot.state.astest_fill_pause_until[self.EV], now + 900, delta=1)
        bot.run_cycle()
        self.assertEqual(self._quotes(bot, self.T), [])
        self.assertEqual(bot._guard_now[self.T]["guard"], "astest_fill_pause")
        bot.state.astest_fill_pause_until[self.EV] = now - 1
        bot.run_cycle()
        self.assertNotEqual(self._quotes(bot, self.T), [])


if __name__ == "__main__":
    unittest.main()
